// Shared canvas drawing helpers.
export const TAU = Math.PI * 2;

export function rr(ctx, x, y, w, h, r) {
  const rad = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.arcTo(x + w, y, x + w, y + h, rad);
  ctx.arcTo(x + w, y + h, x, y + h, rad);
  ctx.arcTo(x, y + h, x, y, rad);
  ctx.arcTo(x, y, x + w, y, rad);
  ctx.closePath();
}

export function ell(ctx, x, y, rx, ry, fill, stroke, lw = 2) {
  ctx.beginPath();
  ctx.ellipse(x, y, Math.max(0.1, rx), Math.max(0.1, ry), 0, 0, TAU);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

export function line(ctx, x1, y1, x2, y2, color, w = 2, cap = 'round') {
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.strokeStyle = color;
  ctx.lineWidth = w;
  ctx.lineCap = cap;
  ctx.stroke();
}

export function poly(ctx, pts, fill, stroke, lw = 2) {
  ctx.beginPath();
  pts.forEach((p, i) => (i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])));
  ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

export function limb(ctx, a, b, c, width, color) {
  ctx.beginPath();
  ctx.moveTo(a[0], a[1]);
  ctx.lineTo(b[0], b[1]);
  ctx.lineTo(c[0], c[1]);
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.stroke();
}

export function dark(hex, amt = 0.25) {
  if (!hex || hex[0] !== '#') return hex || '#000';
  const n = parseInt(hex.slice(1), 16);
  const r = Math.max(0, ((n >> 16) & 255) * (1 - amt));
  const g = Math.max(0, ((n >> 8) & 255) * (1 - amt));
  const b = Math.max(0, (n & 255) * (1 - amt));
  return `rgb(${r | 0},${g | 0},${b | 0})`;
}

export function light(hex, amt = 0.25) {
  if (!hex || hex[0] !== '#') return hex || '#fff';
  const n = parseInt(hex.slice(1), 16);
  const r = Math.min(255, ((n >> 16) & 255) + 255 * amt);
  const g = Math.min(255, ((n >> 8) & 255) + 255 * amt);
  const b = Math.min(255, (n & 255) + 255 * amt);
  return `rgb(${r | 0},${g | 0},${b | 0})`;
}

export function seeded(i) {
  const x = Math.sin(i * 12.9898 + 78.233) * 43758.5453;
  return x - Math.floor(x);
}

export function roundRect(ctx, x, y, w, h, r, fill) {
  rr(ctx, x, y, w, h, r);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
}

// Heads, faces, hair, masks and headgear.
import { TAU, rr, ell, line, poly, dark, light } from './draw-utils.js';

function headPath(ctx, x, y, r, shape) {
  ctx.beginPath();
  if (shape === 'square') {
    rr(ctx, x - r, y - r * 1.05, r * 2, r * 2.08, r * 0.42);
  } else if (shape === 'angular') {
    ctx.moveTo(x - r * 0.92, y - r * 0.8);
    ctx.quadraticCurveTo(x, y - r * 1.18, x + r * 0.9, y - r * 0.82);
    ctx.quadraticCurveTo(x + r * 1.08, y - r * 0.2, x + r * 0.92, y + r * 0.35);
    ctx.quadraticCurveTo(x + r * 0.7, y + r * 1.02, x + r * 0.1, y + r * 1.1);
    ctx.quadraticCurveTo(x - r * 0.7, y + r * 1.02, x - r * 0.95, y + r * 0.32);
    ctx.quadraticCurveTo(x - r * 1.08, y - r * 0.2, x - r * 0.92, y - r * 0.8);
  } else if (shape === 'long') {
    ctx.ellipse(x, y, r * 0.93, r * 1.25, 0, 0, TAU);
  } else {
    ctx.ellipse(x, y, r, r * 1.1, 0, 0, TAU);
  }
  ctx.closePath();
}

function drawEar(ctx, char, x, y, r) {
  const c = char.colors;
  if (char.ears === 'none') return;
  if (char.ears === 'pointy') {
    poly(ctx, [[x - r * 0.55, y - r * 0.15], [x - r * 1.45, y - r * 0.95], [x - r * 0.92, y + r * 0.38]], c.skin, dark(c.skin, 0.3), 1.5);
    line(ctx, x - r * 0.9, y - r * 0.2, x - r * 1.2, y - r * 0.6, dark(c.skin, 0.18), 1.2);
    return;
  }
  if (char.ears === 'long') {
    for (const [ex, rot, sc] of [[x - r * 0.4, -0.28, 1], [x + r * 0.25, 0.34, 0.85]]) {
      ctx.save();
      ctx.translate(ex, y - r * 0.7);
      ctx.rotate(rot);
      ell(ctx, 0, -r * 0.55, r * 0.27 * sc, r * 1.02 * sc, c.skin, dark(c.skin, 0.28), 1.6);
      ell(ctx, 0, -r * 0.55, r * 0.12 * sc, r * 0.72 * sc, light(c.accent, 0.1), null);
      ctx.restore();
    }
    return;
  }
  ell(ctx, x - r * 0.97, y, r * 0.23, r * 0.3, c.skin, dark(c.skin, 0.22), 1.4);
}

function drawEye(ctx, x, y, r, style, color) {
  if (style === 'blank') {
    ell(ctx, x, y, r * 0.23, r * 0.2, color, dark(color, 0.4), 1);
    ell(ctx, x + r * 0.09, y - r * 0.03, r * 0.05, r * 0.05, 'rgba(0,0,0,.35)', null);
    return;
  }
  if (style === 'neon') {
    ctx.save();
    ctx.shadowColor = color;
    ctx.shadowBlur = 9;
    ell(ctx, x, y, r * 0.23, r * 0.2, color, '#2a0b1d', 1.2);
    ell(ctx, x + r * 0.05, y, r * 0.1, r * 0.15, '#e0203f', null);
    ctx.restore();
    return;
  }
  if (style === 'glow') {
    ctx.save();
    ctx.shadowColor = color;
    ctx.shadowBlur = 8;
    ell(ctx, x, y, r * 0.22, r * 0.18, color, null);
    ell(ctx, x + r * 0.02, y, r * 0.04, r * 0.13, '#1a0505', null);
    ctx.restore();
    return;
  }
  if (style === 'small') {
    ell(ctx, x, y, r * 0.11, r * 0.1, color, null);
    ell(ctx, x + r * 0.03, y, r * 0.04, r * 0.04, '#111', null);
    return;
  }
  // normal cartoon eye
  ell(ctx, x, y, r * 0.23, r * 0.195, '#f8f4e8', '#241f1c', 1.2);
  ell(ctx, x + r * 0.06, y + r * 0.005, r * 0.105, r * 0.115, color, null);
  ell(ctx, x + r * 0.075, y - r * 0.03, r * 0.035, r * 0.035, '#101010', null);
  ell(ctx, x + r * 0.13, y - r * 0.05, r * 0.025, r * 0.025, 'rgba(255,255,255,.85)', null);
}

function drawBrows(ctx, char, headX, headY, r, col) {
  const backX = headX - r * 0.2;
  const frontX = headX + r * 0.48;
  const y = headY - r * 0.32;
  const c = col || char.brow || dark(char.colors.hair, 0.2);
  const raise = char.id === 'elmer' ? -r * 0.12 : 0;
  if (char.id === 'boris') {
    line(ctx, backX - r * 0.14, y - r * 0.02, backX + r * 0.16, y + r * 0.04, c, 1.5);
    line(ctx, frontX - r * 0.16, y + r * 0.03, frontX + r * 0.18, y - r * 0.03, c, 1.5);
    return;
  }
  ctx.beginPath();
  ctx.moveTo(frontX - r * 0.2, y + r * 0.1);
  ctx.lineTo(frontX + r * 0.2, y - r * 0.06 + raise);
  ctx.moveTo(backX - r * 0.16, y + r * 0.03 + raise);
  ctx.lineTo(backX + r * 0.19, y + r * 0.13);
  ctx.strokeStyle = c;
  ctx.lineWidth = Math.max(1.7, r * 0.12);
  ctx.lineCap = 'round';
  ctx.stroke();
}

function drawMouth(ctx, char, headX, headY, r) {
  const mx = headX + r * 0.3;
  const my = headY + r * 0.52;
  const c = char.colors;
  const lip = dark(c.skin, 0.55);
  switch (char.mouth) {
    case 'shout': {
      ell(ctx, mx, my + r * 0.05, r * 0.3, r * 0.26, '#3a1414', lip, 1.4);
      ell(ctx, mx, my + r * 0.16, r * 0.18, r * 0.1, '#8c2b2b', null);
      for (let i = 0; i < 4; i++) {
        poly(ctx, [[mx - r * 0.24 + i * r * 0.13, my - r * 0.16], [mx - r * 0.17 + i * r * 0.13, my - r * 0.04], [mx - r * 0.1 + i * r * 0.13, my - r * 0.16]], '#f3ead8');
      }
      break;
    }
    case 'grin': {
      ctx.beginPath();
      ctx.moveTo(mx - r * 0.34, my - r * 0.02);
      ctx.quadraticCurveTo(mx, my + r * 0.3, mx + r * 0.34, my - r * 0.06);
      ctx.quadraticCurveTo(mx, my + r * 0.05, mx - r * 0.34, my - r * 0.02);
      ctx.fillStyle = '#2a1111';
      ctx.fill();
      ctx.strokeStyle = lip;
      ctx.lineWidth = 1.2;
      ctx.stroke();
      for (let i = 0; i < 5; i++) {
        poly(ctx, [[mx - r * 0.26 + i * r * 0.11, my - r * 0.01], [mx - r * 0.2 + i * r * 0.11, my + r * 0.09], [mx - r * 0.14 + i * r * 0.11, my - r * 0.01]], '#f5ecd8');
      }
      break;
    }
    case 'evil': {
      ctx.beginPath();
      ctx.moveTo(mx - r * 0.3, my - r * 0.02);
      ctx.quadraticCurveTo(mx + r * 0.02, my + r * 0.24, mx + r * 0.36, my - r * 0.08);
      ctx.strokeStyle = lip;
      ctx.lineWidth = Math.max(1.6, r * 0.09);
      ctx.stroke();
      line(ctx, mx + r * 0.4, my - r * 0.2, mx + r * 0.44, my - r * 0.34, lip, 1.2);
      break;
    }
    case 'flat': {
      line(ctx, mx - r * 0.22, my, mx + r * 0.24, my - r * 0.02, lip, Math.max(1.6, r * 0.08));
      break;
    }
    case 'fangs': {
      ell(ctx, mx, my, r * 0.3, r * 0.15, '#2b0d0d', lip, 1.2);
      poly(ctx, [[mx - r * 0.24, my - r * 0.08], [mx - r * 0.18, my + r * 0.12], [mx - r * 0.12, my - r * 0.08]], '#f1e8d2');
      poly(ctx, [[mx + r * 0.12, my - r * 0.08], [mx + r * 0.18, my + r * 0.12], [mx + r * 0.24, my - r * 0.08]], '#f1e8d2');
      break;
    }
    case 'underbite': {
      ell(ctx, mx, my + r * 0.05, r * 0.32, r * 0.18, '#3a1a12', lip, 1.4);
      ctx.fillStyle = '#d9c5a2';
      ctx.beginPath();
      ctx.moveTo(mx - r * 0.28, my + r * 0.16);
      ctx.quadraticCurveTo(mx, my + r * 0.05, mx + r * 0.28, my + r * 0.16);
      ctx.quadraticCurveTo(mx, my + r * 0.3, mx - r * 0.28, my + r * 0.16);
      ctx.fill();
      for (let i = 0; i < 3; i++) {
        poly(ctx, [[mx - r * 0.18 + i * r * 0.15, my + r * 0.12], [mx - r * 0.12 + i * r * 0.15, my + r * 0.0], [mx - r * 0.06 + i * r * 0.15, my + r * 0.12]], '#f0e6cc');
      }
      break;
    }
    default: {
      ctx.beginPath();
      ctx.moveTo(mx - r * 0.24, my - r * 0.02);
      ctx.quadraticCurveTo(mx, my + r * 0.12, mx + r * 0.26, my - r * 0.04);
      ctx.strokeStyle = lip;
      ctx.lineWidth = Math.max(1.5, r * 0.075);
      ctx.lineCap = 'round';
      ctx.stroke();
    }
  }
}

function drawHairBack(ctx, char, headX, headY, r) {
  const c = char.colors;
  if (char.hair === 'longred' || char.hair === 'longbangs') {
    const col = c.hair;
    ctx.beginPath();
    ctx.moveTo(headX - r * 0.95, headY - r * 0.75);
    ctx.quadraticCurveTo(headX - r * 1.45, headY + r * 0.7, headX - r * 1.2, headY + r * 2.9);
    ctx.quadraticCurveTo(headX - r * 1.3, headY + r * 3.3, headX - r * 0.72, headY + r * 2.7);
    ctx.quadraticCurveTo(headX - r * 0.65, headY + r * 1.6, headX - r * 0.68, headY + r * 0.9);
    ctx.lineTo(headX - r * 0.2, headY - r * 0.8);
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(headX + r * 0.7, headY - r * 0.7);
    ctx.quadraticCurveTo(headX + r * 1.45, headY + r * 0.4, headX + r * 1.2, headY + r * 2.4);
    ctx.quadraticCurveTo(headX + r * 0.95, headY + r * 1.5, headX + r * 0.82, headY + r * 0.5);
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    for (let i = 0; i < 3; i++) {
      line(ctx, headX - r * (1.0 - i * 0.08), headY + r * 0.5 + i * r * 0.35, headX - r * (0.8 - i * 0.05), headY + r * 2.6, dark(col, 0.2), 1.2);
    }
  } else if (char.hair === 'clownfrizz') {
    for (const side of [-1, 1]) {
      ctx.beginPath();
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU;
        const px = headX + side * r * 1.0 + Math.cos(a) * r * 0.55 * (i % 2 ? 1 : 0.75);
        const py = headY + r * 0.1 + Math.sin(a) * r * 0.7 * (i % 2 ? 1 : 0.7);
        i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
      }
      ctx.closePath();
      ctx.fillStyle = c.hair;
      ctx.fill();
    }
  } else if (char.hair === 'hood' || char.mask === 'ghostface') {
    ctx.beginPath();
    ctx.ellipse(headX - r * 0.12, headY + r * 0.05, r * 1.35, r * 1.5, 0, 0, TAU);
    ctx.fillStyle = dark(c.primary, 0.35);
    ctx.fill();
  } else if (char.hair === 'jasonhair' || char.hair === 'leatherhair') {
    ell(ctx, headX - r * 0.1, headY - r * 0.25, r * 1.12, r * 1.05, c.hair, null);
    ell(ctx, headX - r * 0.75, headY - r * 0.1, r * 0.3, r * 0.5, c.hair, null);
  } else if (char.hair === 'clownhorn') {
    ctx.beginPath();
    ctx.moveTo(headX - r * 0.5, headY - r * 0.7);
    ctx.bezierCurveTo(headX - r * 0.6, headY - r * 2.2, headX + r * 0.1, headY - r * 3.6, headX + r * 0.75, headY - r * 4.1);
    ctx.bezierCurveTo(headX + r * 0.05, headY - r * 3.0, headX + r * 0.35, headY - r * 1.7, headX + r * 0.45, headY - r * 0.75);
    ctx.closePath();
    ctx.fillStyle = c.hair;
    ctx.fill();
  } else if (char.hair === 'bowser') {
    ctx.beginPath();
    ctx.arc(headX - r * 0.2, headY - r * 0.9, r * 0.55, Math.PI, TAU);
    ctx.fillStyle = c.hair;
    ctx.fill();
  }
}

function drawHairFront(ctx, char, headX, headY, r, time) {
  const c = char.colors;
  switch (char.hair) {
    case 'tufts': {
      for (const [dx, dy, w] of [[-0.65, -1.0, 0.3], [-0.2, -1.12, 0.26], [0.3, -1.06, 0.22]]) {
        ctx.beginPath();
        ctx.moveTo(headX + r * (dx - w / 2), headY + r * (dy + 0.12));
        ctx.quadraticCurveTo(headX + r * (dx + 0.03), headY + r * (dy - 0.35), headX + r * (dx + w / 2), headY + r * (dy + 0.1));
        ctx.closePath();
        ctx.fillStyle = c.hair;
        ctx.fill();
      }
      break;
    }
    case 'cowlick': {
      poly(ctx, [[headX - r * 0.8, headY - r * 0.75], [headX - r * 0.15, headY - r * 1.5], [headX + r * 0.1, headY - r * 0.82]], c.hair);
      poly(ctx, [[headX - r * 0.35, headY - r * 0.95], [headX + r * 0.35, headY - r * 1.55], [headX + r * 0.65, headY - r * 0.85]], c.hair);
      ctx.beginPath();
      ctx.moveTo(headX + r * 0.55, headY - r * 0.85);
      ctx.quadraticCurveTo(headX + r * 1.2, headY - r * 1.45, headX + r * 0.95, headY - r * 1.85);
      ctx.quadraticCurveTo(headX + r * 1.3, headY - r * 1.35, headX + r * 0.8, headY - r * 0.78);
      ctx.closePath();
      ctx.fillStyle = c.hair;
      ctx.fill();
      line(ctx, headX + r * 0.1, headY - r * 1.0, headX + r * 0.8, headY - r * 0.9, dark(c.hair, 0.25), 1.5);
      break;
    }
    case 'longbangs': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 1.0, headY - r * 0.8);
      ctx.quadraticCurveTo(headX - r * 0.2, headY - r * 1.25, headX + r * 1.0, headY - r * 0.72);
      ctx.lineTo(headX + r * 0.85, headY - r * 0.35);
      ctx.lineTo(headX + r * 0.35, headY - r * 0.55);
      ctx.lineTo(headX + r * 0.1, headY - r * 0.3);
      ctx.lineTo(headX - r * 0.4, headY - r * 0.55);
      ctx.lineTo(headX - r * 0.75, headY - r * 0.3);
      ctx.closePath();
      ctx.fillStyle = c.hair;
      ctx.fill();
      line(ctx, headX - r * 0.6, headY - r * 0.7, headX - r * 0.5, headY + r * 1.1, dark(c.hair, 0.2), 1.2);
      break;
    }
    case 'slickwhite': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.9, headY - r * 0.55);
      ctx.quadraticCurveTo(headX - r * 0.85, headY - r * 1.12, headX + r * 0.1, headY - r * 1.12);
      ctx.quadraticCurveTo(headX + r * 0.85, headY - r * 1.05, headX + r * 0.9, headY - r * 0.5);
      ctx.quadraticCurveTo(headX + r * 0.35, headY - r * 0.82, headX - r * 0.9, headY - r * 0.55);
      ctx.closePath();
      ctx.fillStyle = c.hair;
      ctx.fill();
      break;
    }
    case 'spikyblond': {
      for (let i = 0; i < 6; i++) {
        const bx = headX - r * 0.95 + i * r * 0.36;
        poly(ctx, [[bx - r * 0.16, headY - r * 0.82], [bx + r * 0.02, headY - r * 1.42 - (i % 2) * r * 0.2], [bx + r * 0.19, headY - r * 0.8]], c.hair);
      }
      ctx.beginPath();
      ctx.ellipse(headX - r * 0.05, headY - r * 0.7, r * 0.98, r * 0.42, 0, Math.PI, TAU);
      ctx.fillStyle = c.hair;
      ctx.fill();
      break;
    }
    case 'threehairs': {
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(headX - r * 0.5 + i * r * 0.32, headY - r * 1.02);
        ctx.quadraticCurveTo(headX - r * 0.45 + i * r * 0.35, headY - r * 1.55, headX - r * 0.15 + i * r * 0.35, headY - r * 1.75);
        ctx.strokeStyle = c.hair;
        ctx.lineWidth = 2.2;
        ctx.stroke();
      }
      ell(ctx, headX - r * 0.85, headY - r * 0.1, r * 0.22, r * 0.4, c.hair, null);
      ell(ctx, headX + r * 0.85, headY - r * 0.15, r * 0.2, r * 0.35, c.hair, null);
      for (const [sx, sy] of [[-0.3, -0.75], [0.35, -0.5], [-0.1, 0.4]]) {
        ell(ctx, headX + r * sx, headY + r * sy, r * 0.08, r * 0.06, 'rgba(90,55,35,.35)', null);
      }
      break;
    }
    case 'balding': {
      ell(ctx, headX - r * 0.92, headY - r * 0.05, r * 0.24, r * 0.42, c.hair, null);
      ell(ctx, headX + r * 0.92, headY - r * 0.05, r * 0.22, r * 0.38, c.hair, null);
      ctx.beginPath();
      ctx.ellipse(headX - r * 0.15, headY - r * 0.88, r * 0.4, r * 0.12, -0.2, 0, TAU);
      ctx.fillStyle = 'rgba(255,255,255,.13)';
      ctx.fill();
      break;
    }
    case 'longred': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.95, headY - r * 0.7);
      ctx.quadraticCurveTo(headX + r * 0.2, headY - r * 1.3, headX + r * 0.95, headY - r * 0.55);
      ctx.lineTo(headX + r * 0.65, headY - r * 0.35);
      ctx.quadraticCurveTo(headX - r * 0.1, headY - r * 0.7, headX - r * 0.9, headY - r * 0.25);
      ctx.closePath();
      ctx.fillStyle = c.hair;
      ctx.fill();
      line(ctx, headX - r * 0.4, headY - r * 0.8, headX - r * 0.1, headY + r * 0.1, dark(c.hair, 0.2), 1.4);
      break;
    }
    case 'mohawk': {
      for (let i = 0; i < 7; i++) {
        const bx = headX - r * 0.85 + i * r * 0.28;
        poly(ctx, [[bx - r * 0.13, headY - r * 0.9], [bx + r * 0.02, headY - r * 1.55 - (i % 3) * r * 0.12], [bx + r * 0.16, headY - r * 0.88]], c.hair, dark(c.hair, 0.4), 1);
      }
      break;
    }
    case 'clownhorn': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.65, headY - r * 0.6);
      ctx.quadraticCurveTo(headX - r * 0.9, headY - r * 1.2, headX - r * 0.2, headY - r * 1.1);
      ctx.quadraticCurveTo(headX - r * 0.55, headY - r * 0.95, headX - r * 0.2, headY - r * 0.7);
      ctx.closePath();
      ctx.fillStyle = c.hair;
      ctx.fill();
      break;
    }
    case 'clownfrizz': {
      for (const [dx, w] of [[-0.9, 0.4], [0.9, 0.4], [-0.35, 0.3], [0.35, 0.3]]) {
        ell(ctx, headX + r * dx, headY - r * 0.85, r * w, r * 0.35, c.hair, null);
      }
      break;
    }
    case 'slick': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.95, headY - r * 0.5);
      ctx.quadraticCurveTo(headX - r * 0.6, headY - r * 1.2, headX + r * 0.2, headY - r * 1.12);
      ctx.quadraticCurveTo(headX + r * 0.9, headY - r * 1.0, headX + r * 0.95, headY - r * 0.42);
      ctx.lineTo(headX + r * 0.2, headY - r * 0.82);
      ctx.lineTo(headX - r * 0.05, headY - r * 0.55);
      ctx.closePath();
      ctx.fillStyle = c.hair;
      ctx.fill();
      break;
    }
    case 'bowser': {
      poly(ctx, [[headX - r * 0.2, headY - r * 1.05], [headX + r * 0.5, headY - r * 1.45], [headX + r * 0.55, headY - r * 0.95]], c.hair);
      break;
    }
    case 'bald': {
      ctx.beginPath();
      ctx.ellipse(headX - r * 0.2, headY - r * 0.85, r * 0.45, r * 0.14, -0.15, 0, TAU);
      ctx.fillStyle = 'rgba(255,255,255,.16)';
      ctx.fill();
      break;
    }
    case 'antenna': {
      for (const dx of [-0.25, 0.4]) {
        ctx.beginPath();
        ctx.moveTo(headX + r * dx, headY - r * 1.05);
        ctx.quadraticCurveTo(headX + r * (dx + 0.05), headY - r * 1.7, headX + r * (dx + 0.35), headY - r * 1.9);
        ctx.strokeStyle = c.hair;
        ctx.lineWidth = 2;
        ctx.stroke();
        ell(ctx, headX + r * (dx + 0.35), headY - r * 1.9, r * 0.11, r * 0.11, c.hair, null);
      }
      break;
    }
    default: break;
  }
}

function drawHeadgear(ctx, char, headX, headY, r, time) {
  const c = char.colors;
  switch (char.headgear) {
    case 'fedora': {
      ell(ctx, headX - r * 0.12, headY - r * 0.78, r * 1.4, r * 0.3, '#5a402e', '#2c1f16', 2);
      poly(ctx, [[headX - r * 0.75, headY - r * 0.9], [headX - r * 0.55, headY - r * 1.62], [headX + r * 0.75, headY - r * 1.58], [headX + r * 0.92, headY - r * 0.85]], '#4a3425', '#2c1f16', 2);
      ctx.fillStyle = '#2a1d14';
      ctx.fillRect(headX - r * 0.6, headY - r * 1.18, r * 1.45, r * 0.18);
      break;
    }
    case 'cap': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.95, headY - r * 0.5);
      ctx.quadraticCurveTo(headX - r * 0.95, headY - r * 1.3, headX + r * 0.2, headY - r * 1.28);
      ctx.quadraticCurveTo(headX + r * 0.95, headY - r * 1.2, headX + r * 1.0, headY - r * 0.55);
      ctx.closePath();
      ctx.fillStyle = c.primary;
      ctx.fill();
      ctx.fillStyle = c.accent;
      ctx.fillRect(headX - r * 0.9, headY - r * 0.62, r * 1.9, r * 0.14);
      ell(ctx, headX + r * 0.25, headY - r * 0.95, r * 0.16, r * 0.2, c.accent, null);
      ell(ctx, headX + r * 0.25, headY - r * 0.95, r * 0.08, r * 0.1, dark(c.primary, 0.4), null);
      poly(ctx, [[headX + r * 0.55, headY - r * 0.62], [headX + r * 1.55, headY - r * 0.5], [headX + r * 0.9, headY - r * 0.35], [headX + r * 0.55, headY - r * 0.42]], '#171013');
      break;
    }
    case 'huntcap': {
      ctx.beginPath();
      ctx.arc(headX, headY - r * 0.55, r * 0.98, Math.PI, TAU);
      ctx.fillStyle = '#a63a34';
      ctx.fill();
      ctx.fillStyle = '#8a2c28';
      ctx.fillRect(headX - r * 0.98, headY - r * 0.6, r * 1.96, r * 0.16);
      poly(ctx, [[headX + r * 0.2, headY - r * 0.55], [headX + r * 1.4, headY - r * 0.48], [headX + r * 0.3, headY - r * 0.36]], '#2b2d33');
      ell(ctx, headX - r * 0.92, headY + r * 0.05, r * 0.22, r * 0.35, '#a63a34', null);
      ell(ctx, headX + r * 0.92, headY + r * 0.05, r * 0.22, r * 0.35, '#a63a34', null);
      break;
    }
    case 'turban': {
      ell(ctx, headX - r * 0.05, headY - r * 0.75, r * 1.2, r * 0.62, '#e3d9b8', '#9c8f68', 2);
      ell(ctx, headX - r * 0.05, headY - r * 0.98, r * 0.92, r * 0.4, '#efe6c9', null);
      line(ctx, headX - r * 0.9, headY - r * 0.6, headX + r * 0.9, headY - r * 0.68, '#b6a77c', 2);
      ell(ctx, headX + r * 0.35, headY - r * 0.8, r * 0.14, r * 0.18, c.primary, c.accent, 3);
      poly(ctx, [[headX + r * 0.35, headY - r * 1.0], [headX + r * 0.9, headY - r * 2.25], [headX + r * 0.52, headY - r * 1.05]], c.accent);
      break;
    }
    case 'crown': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.85, headY - r * 0.75);
      ctx.lineTo(headX - r * 0.95, headY - r * 1.5);
      ctx.lineTo(headX - r * 0.45, headY - r * 1.02);
      ctx.lineTo(headX - r * 0.05, headY - r * 1.65);
      ctx.lineTo(headX + r * 0.4, headY - r * 1.0);
      ctx.lineTo(headX + r * 0.9, headY - r * 1.5);
      ctx.lineTo(headX + r * 0.85, headY - r * 0.7);
      ctx.closePath();
      ctx.fillStyle = '#e8c24a';
      ctx.fill();
      ctx.strokeStyle = '#9a7420';
      ctx.lineWidth = 2;
      ctx.stroke();
      for (const dx of [-0.6, 0, 0.6]) ell(ctx, headX + r * dx, headY - r * 0.88, r * 0.1, r * 0.12, dx === 0 ? '#e12828' : '#5ec4e8', null);
      break;
    }
    case 'tophat': {
      ell(ctx, headX, headY - r * 1.15, r * 1.3, r * 0.2, '#14121a', null);
      ctx.fillStyle = '#14121a';
      ctx.fillRect(headX - r * 0.7, headY - r * 2.4, r * 1.4, r * 1.3);
      ctx.fillStyle = '#3a3446';
      ctx.fillRect(headX - r * 0.7, headY - r * 1.35, r * 1.4, r * 0.18);
      break;
    }
    case 'bowser': {
      poly(ctx, [[headX - r * 0.55, headY - r * 0.6], [headX - r * 0.7, headY - r * 1.55], [headX - r * 0.12, headY - r * 0.85]], '#efe8d2', '#8a7a58', 1.5);
      poly(ctx, [[headX + r * 0.3, headY - r * 0.85], [headX + r * 0.65, headY - r * 1.6], [headX + r * 0.8, headY - r * 0.7]], '#efe8d2', '#8a7a58', 1.5);
      break;
    }
    default: break;
  }
}

function drawMask(ctx, char, headX, headY, r) {
  const c = char.colors;
  switch (char.mask) {
    case 'michael': {
      // weathered, slightly asymmetric 2002 mask
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.98, headY - r * 0.82);
      ctx.quadraticCurveTo(headX - r * 0.2, headY - r * 1.22, headX + r * 0.92, headY - r * 0.86);
      ctx.quadraticCurveTo(headX + r * 1.12, headY - r * 0.1, headX + r * 0.9, headY + r * 0.45);
      ctx.quadraticCurveTo(headX + r * 0.62, headY + r * 1.08, headX + r * 0.02, headY + r * 1.15);
      ctx.quadraticCurveTo(headX - r * 0.72, headY + r * 1.06, headX - r * 1.0, headY + r * 0.38);
      ctx.quadraticCurveTo(headX - r * 1.1, headY - r * 0.25, headX - r * 0.98, headY - r * 0.82);
      ctx.closePath();
      const g = ctx.createLinearGradient(headX - r, headY - r, headX + r, headY + r);
      g.addColorStop(0, '#d7d2c3');
      g.addColorStop(0.55, '#efeadc');
      g.addColorStop(1, '#c9c3b3');
      ctx.fillStyle = g;
      ctx.fill();
      ctx.strokeStyle = '#8d8779';
      ctx.lineWidth = 1.4;
      ctx.stroke();
      // eye holes
      ell(ctx, headX - r * 0.28, headY - r * 0.13, r * 0.24, r * 0.19, '#141312', null);
      ell(ctx, headX + r * 0.46, headY - r * 0.16, r * 0.21, r * 0.17, '#141312', null);
      // nose shadow
      poly(ctx, [[headX + r * 0.12, headY + r * 0.12], [headX + r * 0.2, headY + r * 0.3], [headX + r * 0.02, headY + r * 0.32]], '#a8a294');
      ell(ctx, headX + r * 0.06, headY + r * 0.31, r * 0.045, r * 0.035, '#3a3734', null);
      ell(ctx, headX + r * 0.2, headY + r * 0.3, r * 0.045, r * 0.035, '#3a3734', null);
      // thin mouth
      line(ctx, headX - r * 0.07, headY + r * 0.62, headX + r * 0.34, headY + r * 0.58, '#7a7267', 1.6);
      // cracks / weathering
      line(ctx, headX - r * 0.62, headY - r * 0.48, headX - r * 0.5, headY - r * 0.12, 'rgba(110,102,88,.6)', 1);
      line(ctx, headX - r * 0.5, headY - r * 0.12, headX - r * 0.58, headY + r * 0.02, 'rgba(110,102,88,.5)', 1);
      line(ctx, headX + r * 0.72, headY + r * 0.35, headX + r * 0.6, headY + r * 0.5, 'rgba(110,102,88,.55)', 1);
      line(ctx, headX + r * 0.3, headY + r * 0.82, headX + r * 0.48, headY + r * 0.7, 'rgba(110,102,88,.5)', 1);
      ell(ctx, headX + r * 0.55, headY + r * 0.3, r * 0.08, r * 0.05, 'rgba(120,110,90,.3)', null);
      break;
    }
    case 'jason': {
      ctx.beginPath();
      ctx.ellipse(headX + r * 0.03, headY + r * 0.02, r * 0.94, r * 1.08, 0, 0, TAU);
      const g = ctx.createLinearGradient(headX - r, headY - r, headX + r, headY + r);
      g.addColorStop(0, '#d9d4bd');
      g.addColorStop(0.6, '#f2eeda');
      g.addColorStop(1, '#c4bfa8');
      ctx.fillStyle = g;
      ctx.fill();
      ctx.strokeStyle = '#7d7a68';
      ctx.lineWidth = 1.4;
      ctx.stroke();
      ell(ctx, headX - r * 0.3, headY - r * 0.12, r * 0.22, r * 0.17, '#16150f', null);
      ell(ctx, headX + r * 0.45, headY - r * 0.14, r * 0.2, r * 0.15, '#16150f', null);
      // nose and mouth holes
      poly(ctx, [[headX + r * 0.1, headY + r * 0.12], [headX + r * 0.2, headY + r * 0.3], [headX + r * 0.04, headY + r * 0.3]], '#4a4637');
      for (let i = 0; i < 4; i++) ell(ctx, headX - r * 0.12 + i * r * 0.1, headY + r * 0.62, r * 0.035, r * 0.09, '#4a4637', null);
      // red triangles
      poly(ctx, [[headX - r * 0.08, headY - r * 0.55], [headX + r * 0.12, headY - r * 0.24], [headX - r * 0.28, headY - r * 0.24]], '#c0392b');
      poly(ctx, [[headX - r * 0.6, headY + r * 0.3], [headX - r * 0.44, headY + r * 0.5], [headX - r * 0.7, headY + r * 0.52]], '#b7332a');
      poly(ctx, [[headX + r * 0.55, headY + r * 0.4], [headX + r * 0.72, headY + r * 0.56], [headX + r * 0.48, headY + r * 0.62]], '#b7332a');
      // straps
      line(ctx, headX - r * 0.85, headY - r * 0.35, headX - r * 1.15, headY - r * 0.45, '#39352b', 3);
      line(ctx, headX - r * 0.82, headY + r * 0.42, headX - r * 1.1, headY + r * 0.42, '#39352b', 3);
      for (const [dx, dy] of [[-0.7, -0.7], [0.75, -0.7], [-0.78, 0.68], [0.78, 0.7], [0.05, 0.9]]) {
        ell(ctx, headX + r * dx, headY + r * dy, r * 0.035, r * 0.035, 'rgba(70,66,52,.55)', null);
      }
      break;
    }
    case 'vader': {
      // flared helmet + faceplate
      ctx.beginPath();
      ctx.moveTo(headX - r * 1.12, headY + r * 0.65);
      ctx.quadraticCurveTo(headX - r * 1.25, headY - r * 0.1, headX - r * 1.1, headY - r * 0.9);
      ctx.quadraticCurveTo(headX, headY - r * 1.55, headX + r * 1.1, headY - r * 0.9);
      ctx.quadraticCurveTo(headX + r * 1.25, headY - r * 0.1, headX + r * 1.12, headY + r * 0.65);
      ctx.quadraticCurveTo(headX + r * 0.9, headY + r * 0.95, headX + r * 0.55, headY + r * 0.78);
      ctx.lineTo(headX - r * 0.55, headY + r * 0.78);
      ctx.quadraticCurveTo(headX - r * 0.9, headY + r * 0.95, headX - r * 1.12, headY + r * 0.65);
      ctx.closePath();
      ctx.fillStyle = '#17181d';
      ctx.fill();
      ctx.strokeStyle = '#3c3f49';
      ctx.lineWidth = 1.6;
      ctx.stroke();
      // brow / faceplate
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.8, headY - r * 0.45);
      ctx.quadraticCurveTo(headX + r * 0.1, headY - r * 0.68, headX + r * 0.85, headY - r * 0.3);
      ctx.lineTo(headX + r * 0.66, headY + r * 0.62);
      ctx.quadraticCurveTo(headX, headY + r * 0.88, headX - r * 0.66, headY + r * 0.55);
      ctx.closePath();
      ctx.fillStyle = '#22242b';
      ctx.fill();
      // red lenses
      ctx.save();
      ctx.shadowColor = '#ff2a1a';
      ctx.shadowBlur = 10;
      for (const dx of [-0.3, 0.42]) {
        ctx.beginPath();
        ctx.ellipse(headX + r * dx, headY - r * 0.13, r * 0.19, r * 0.12, dx > 0 ? 0.18 : -0.12, 0, TAU);
        ctx.fillStyle = '#d92d20';
        ctx.fill();
      }
      ctx.restore();
      // nose ridge
      poly(ctx, [[headX + r * 0.05, headY - r * 0.1], [headX + r * 0.16, headY + r * 0.25], [headX - r * 0.02, headY + r * 0.25], [headX - r * 0.08, headY - r * 0.08]], '#3d404a');
      // grille
      poly(ctx, [[headX - r * 0.14, headY + r * 0.38], [headX + r * 0.24, headY + r * 0.36], [headX + r * 0.18, headY + r * 0.68], [headX - r * 0.08, headY + r * 0.7]], '#111216', '#4a4e5a', 1.2);
      for (let i = 0; i < 4; i++) line(ctx, headX - r * 0.05 + i * r * 0.075, headY + r * 0.4, headX - r * 0.03 + i * r * 0.06, headY + r * 0.67, '#5c606d', 1.4);
      // helmet cheeks
      line(ctx, headX - r * 0.7, headY + r * 0.25, headX - r * 0.52, headY + r * 0.8, '#3c3f49', 1.5);
      line(ctx, headX + r * 0.72, headY + r * 0.2, headX + r * 0.55, headY + r * 0.78, '#3c3f49', 1.5);
      // neck collar
      poly(ctx, [[headX - r * 0.85, headY + r * 0.8], [headX + r * 0.85, headY + r * 0.8], [headX + r * 1.15, headY + r * 1.2], [headX - r * 1.15, headY + r * 1.2]], '#191a20', '#353843', 1.5);
      break;
    }
    case 'clown': {
      // white greasepaint, green eyelids, red grin
      ctx.save();
      headPath(ctx, headX, headY, r, char.headShape);
      ctx.fillStyle = '#f3efe8';
      ctx.fill();
      ctx.restore();
      ctx.strokeStyle = dark(c.skin, 0.15);
      ctx.lineWidth = 1;
      headPath(ctx, headX, headY, r, char.headShape);
      ctx.stroke();
      // eye makeup
      ell(ctx, headX - r * 0.28, headY - r * 0.16, r * 0.36, r * 0.3, 'rgba(80,190,80,.45)', null);
      ell(ctx, headX + r * 0.44, headY - r * 0.18, r * 0.34, r * 0.28, 'rgba(80,190,80,.45)', null);
      ell(ctx, headX - r * 0.26, headY - r * 0.16, r * 0.18, r * 0.15, '#1a1114', null);
      ell(ctx, headX + r * 0.44, headY - r * 0.17, r * 0.16, r * 0.14, '#1a1114', null);
      ell(ctx, headX - r * 0.24, headY - r * 0.17, r * 0.09, r * 0.09, '#ef2a2a', null);
      ell(ctx, headX + r * 0.42, headY - r * 0.18, r * 0.08, r * 0.08, '#ef2a2a', null);
      // red nose
      ctx.save();
      ctx.shadowColor = '#ff2a2a';
      ctx.shadowBlur = 5;
      ell(ctx, headX + r * 0.14, headY + r * 0.25, r * 0.17, r * 0.15, '#e12828', '#9e1a1a', 1.2);
      ctx.restore();
      // giant grin
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.3, headY + r * 0.46);
      ctx.quadraticCurveTo(headX + r * 0.15, headY + r * 0.98, headX + r * 0.72, headY + r * 0.38);
      ctx.quadraticCurveTo(headX + r * 0.2, headY + r * 0.55, headX - r * 0.3, headY + r * 0.46);
      ctx.fillStyle = '#b51e26';
      ctx.fill();
      for (let i = 0; i < 6; i++) {
        poly(ctx, [[headX - r * 0.2 + i * r * 0.14, headY + r * 0.5], [headX - r * 0.12 + i * r * 0.14, headY + r * 0.66], [headX - r * 0.04 + i * r * 0.14, headY + r * 0.5]], '#f6efdd');
      }
      break;
    }
    case 'pennywise': {
      headPath(ctx, headX, headY, r, 'long');
      ctx.fillStyle = '#f6f2ec';
      ctx.fill();
      // eye lines
      for (const dx of [-0.28, 0.44]) {
        line(ctx, headX + r * dx, headY + r * 0.02, headX + r * (dx + 0.03), headY + r * 0.55, '#c0392b', 2);
        line(ctx, headX + r * (dx - 0.1), headY + r * 0.5, headX + r * (dx + 0.16), headY + r * 0.62, '#c0392b', 1.5);
      }
      ell(ctx, headX + r * 0.12, headY + r * 0.22, r * 0.15, r * 0.13, '#e12828', null);
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.3, headY + r * 0.45);
      ctx.quadraticCurveTo(headX + r * 0.1, headY + r * 0.9, headX + r * 0.7, headY + r * 0.4);
      ctx.quadraticCurveTo(headX + r * 0.1, headY + r * 0.58, headX - r * 0.3, headY + r * 0.45);
      ctx.fillStyle = '#b51e26';
      ctx.fill();
      for (let i = 0; i < 4; i++) poly(ctx, [[headX - r * 0.14 + i * r * 0.14, headY + r * 0.5], [headX - r * 0.07 + i * r * 0.14, headY + r * 0.66], [headX + i * r * 0.14, headY + r * 0.5]], '#f6efdd');
      break;
    }
    case 'leather': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 1.0, headY - r * 0.85);
      ctx.quadraticCurveTo(headX, headY - r * 1.3, headX + r * 1.0, headY - r * 0.82);
      ctx.lineTo(headX + r * 1.05, headY + r * 0.55);
      ctx.quadraticCurveTo(headX + r * 0.7, headY + r * 1.15, headX, headY + r * 1.15);
      ctx.quadraticCurveTo(headX - r * 0.75, headY + r * 1.12, headX - r * 1.02, headY + r * 0.5);
      ctx.closePath();
      ctx.fillStyle = '#d9b394';
      ctx.fill();
      ctx.strokeStyle = '#a17a5d';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ell(ctx, headX - r * 0.28, headY - r * 0.1, r * 0.2, r * 0.17, '#1e1512', null);
      ell(ctx, headX + r * 0.44, headY - r * 0.12, r * 0.18, r * 0.16, '#1e1512', null);
      ell(ctx, headX + r * 0.18, headY + r * 0.55, r * 0.14, r * 0.1, '#3a2018', null);
      // stitches
      for (const [sx, sy, ang] of [[-0.55, 0.25, 0.4], [0.4, 0.52, -0.2], [0.05, -0.55, 0.1]]) {
        const x1 = headX + r * sx;
        const y1 = headY + r * sy;
        line(ctx, x1 - r * 0.16, y1 - r * 0.06, x1 + r * 0.16, y1 + r * 0.06, '#6b3f2c', 1.4);
        for (let i = 0; i < 3; i++) line(ctx, x1 - r * 0.12 + i * r * 0.11, y1 - r * 0.06, x1 - r * 0.14 + i * r * 0.11, y1 + r * 0.07, '#6b3f2c', 1);
      }
      ell(ctx, headX + r * 0.62, headY + r * 0.34, r * 0.12, r * 0.08, 'rgba(120,30,25,.5)', null);
      break;
    }
    case 'ghostface': {
      ctx.beginPath();
      ctx.moveTo(headX - r * 0.85, headY - r * 0.9);
      ctx.quadraticCurveTo(headX, headY - r * 1.38, headX + r * 0.9, headY - r * 0.9);
      ctx.quadraticCurveTo(headX + r * 1.02, headY + r * 0.2, headX + r * 0.55, headY + r * 1.0);
      ctx.quadraticCurveTo(headX, headY + r * 1.45, headX - r * 0.6, headY + r * 0.95);
      ctx.quadraticCurveTo(headX - r * 1.02, headY + r * 0.15, headX - r * 0.85, headY - r * 0.9);
      ctx.closePath();
      const g = ctx.createLinearGradient(headX - r, headY - r, headX + r, headY + r);
      g.addColorStop(0, '#eae7df');
      g.addColorStop(0.65, '#f7f4ec');
      g.addColorStop(1, '#c9c5bb');
      ctx.fillStyle = g;
      ctx.fill();
      ctx.strokeStyle = '#8a877e';
      ctx.lineWidth = 1.2;
      ctx.stroke();
      // black eyes
      ell(ctx, headX - r * 0.27, headY - r * 0.18, r * 0.22, r * 0.25, '#111116', null);
      ell(ctx, headX + r * 0.46, headY - r * 0.2, r * 0.2, r * 0.23, '#111116', null);
      // nose slit
      poly(ctx, [[headX + r * 0.1, headY + r * 0.12], [headX + r * 0.23, headY + r * 0.24], [headX + r * 0.08, headY + r * 0.26]], '#3a393e');
      // screaming mouth
      ctx.beginPath();
      ctx.ellipse(headX + r * 0.15, headY + r * 0.58, r * 0.16, r * 0.26, -0.15, 0, TAU);
      ctx.fillStyle = '#15151a';
      ctx.fill();
      // hood edge
      ctx.strokeStyle = '#2a2a33';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(headX - r * 0.05, headY, r * 1.36, Math.PI * 0.75, Math.PI * 2.25);
      ctx.stroke();
      break;
    }
    case 'pinhead': {
      headPath(ctx, headX, headY, r, char.headShape);
      ctx.fillStyle = '#e3dcd2';
      ctx.fill();
      // grid pins
      ctx.strokeStyle = '#7a7a86';
      ctx.lineWidth = 1.2;
      for (let ix = -2; ix <= 2; ix++) {
        for (let iy = -2; iy <= 2; iy++) {
          if (ix === 0 && iy === 0) continue;
          const px = headX + ix * r * 0.33 + r * 0.08;
          const py = headY - r * 0.05 + iy * r * 0.3;
          line(ctx, px, py, px + ix * r * 0.11, py + iy * r * 0.11, '#7a7a86', 1.2);
          ell(ctx, px + ix * r * 0.12, py + iy * r * 0.12, r * 0.025, r * 0.025, '#c9c4bb', null);
        }
      }
      ell(ctx, headX - r * 0.26, headY - r * 0.16, r * 0.16, r * 0.1, '#1a171c', null);
      ell(ctx, headX + r * 0.44, headY - r * 0.17, r * 0.14, r * 0.09, '#1a171c', null);
      line(ctx, headX - r * 0.02, headY + r * 0.52, headX + r * 0.34, headY + r * 0.5, '#6d5f57', 1.8);
      break;
    }
    default: break;
  }
}

export function drawHead(ctx, char, o) {
  const { headX, headY, headR, time = 0 } = o;
  const r = headR;
  const c = char.colors;

  drawHairBack(ctx, char, headX, headY, r);
  if (char.mask === 'ghostface') {
    // hood goes behind the mask (already drawn by hair back)
  }
  drawEar(ctx, char, headX, headY, r);

  if (!char.mask) {
    headPath(ctx, headX, headY, r, char.headShape);
    const g = ctx.createLinearGradient(headX - r, headY - r, headX + r, headY + r);
    g.addColorStop(0, light(c.skin, 0.08));
    g.addColorStop(0.7, c.skin);
    g.addColorStop(1, dark(c.skin, 0.18));
    ctx.fillStyle = g;
    ctx.fill();
    ctx.strokeStyle = dark(c.skin, 0.3);
    ctx.lineWidth = 1.2;
    ctx.stroke();
  }

  if (char.mask) {
    drawMask(ctx, char, headX, headY, r);
  }

  const faceVisible = !char.mask || char.mask === 'burn';
  if (faceVisible) {
    if (char.eyeStyle === 'oneeye') {
      // single central eye
      ell(ctx, headX + r * 0.18, headY - r * 0.12, r * 0.34, r * 0.3, '#f2ead2', '#2b231c', 1.6);
      ell(ctx, headX + r * 0.24, headY - r * 0.12, r * 0.16, r * 0.17, c.eye, null);
      ell(ctx, headX + r * 0.26, headY - r * 0.12, r * 0.075, r * 0.085, '#111', null);
      ell(ctx, headX + r * 0.31, headY - r * 0.18, r * 0.04, r * 0.04, 'rgba(255,255,255,.9)', null);
      // heavy brow
      line(ctx, headX - r * 0.2, headY - r * 0.45, headX + r * 0.62, headY - r * 0.36, char.brow || dark(c.skin, 0.4), r * 0.13);
    } else if (char.eyeStyle === 'small') {
      drawEye(ctx, headX - r * 0.2, headY - r * 0.05, r, 'small', c.eye);
      drawEye(ctx, headX + r * 0.48, headY - r * 0.06, r, 'small', c.eye);
    } else {
      drawEye(ctx, headX - r * 0.2, headY - r * 0.03, r, char.eyeStyle, c.eye);
      drawEye(ctx, headX + r * 0.48, headY - r * 0.05, r, char.eyeStyle, c.eye);
    }
    if (char.eyeStyle !== 'oneeye') drawBrows(ctx, char, headX, headY, r);

    // nose
    if (!char.snout && char.mask !== 'burn') {
      if (char.id === 'ogre' || char.id === 'cyclops' || char.id === 'rawhead' || char.id === 'bigbabytom') {
        ell(ctx, headX + r * 0.2, headY + r * 0.3, r * 0.2, r * 0.13, dark(c.skin, 0.15), null);
        ell(ctx, headX + r * 0.11, headY + r * 0.31, r * 0.04, r * 0.03, dark(c.skin, 0.45), null);
        ell(ctx, headX + r * 0.28, headY + r * 0.31, r * 0.04, r * 0.03, dark(c.skin, 0.45), null);
      } else {
        line(ctx, headX + r * 0.14, headY + r * 0.1, headX + r * 0.2, headY + r * 0.27, dark(c.skin, 0.35), 1.4);
        line(ctx, headX + r * 0.06, headY + r * 0.28, headX + r * 0.28, headY + r * 0.27, dark(c.skin, 0.35), 1.3);
      }
    }

    // muzzles
    if (char.snout === 'dog' && char.mask !== 'burn') {
      ell(ctx, headX + r * 0.55, headY + r * 0.34, r * 0.58, r * 0.3, c.skin, dark(c.skin, 0.3), 1.5);
      ell(ctx, headX + r * 1.02, headY + r * 0.25, r * 0.12, r * 0.09, '#201812', null);
      ctx.beginPath();
      ctx.moveTo(headX + r * 0.35, headY + r * 0.58);
      ctx.quadraticCurveTo(headX + r * 0.7, headY + r * 0.9, headX + r * 1.05, headY + r * 0.5);
      ctx.strokeStyle = '#3a2018';
      ctx.lineWidth = 1.8;
      ctx.stroke();
      for (let i = 0; i < 3; i++) poly(ctx, [[headX + r * 0.56 + i * r * 0.13, headY + r * 0.62], [headX + r * 0.62 + i * r * 0.13, headY + r * 0.76], [headX + r * 0.68 + i * r * 0.13, headY + r * 0.6]], '#f6eedb');
    } else if (char.snout === 'croc' && char.mask !== 'burn') {
      ctx.beginPath();
      ctx.moveTo(headX + r * 0.1, headY + r * 0.15);
      ctx.quadraticCurveTo(headX + r * 1.05, headY + r * 0.1, headX + r * 1.35, headY + r * 0.35);
      ctx.quadraticCurveTo(headX + r * 1.1, headY + r * 0.68, headX + r * 0.3, headY + r * 0.62);
      ctx.closePath();
      ctx.fillStyle = c.skin;
      ctx.fill();
      ctx.strokeStyle = dark(c.skin, 0.3);
      ctx.lineWidth = 1.4;
      ctx.stroke();
      for (let i = 0; i < 5; i++) {
        poly(ctx, [[headX + r * 0.35 + i * r * 0.17, headY + r * 0.58], [headX + r * 0.41 + i * r * 0.17, headY + r * 0.7], [headX + r * 0.47 + i * r * 0.17, headY + r * 0.57]], '#f3ead6');
      }
      ell(ctx, headX + r * 0.95, headY + r * 0.2, r * 0.05, r * 0.035, '#20301c', null);
    } else if (char.snout === 'pig' && char.mask !== 'burn') {
      ell(ctx, headX + r * 0.52, headY + r * 0.36, r * 0.5, r * 0.34, c.skin, dark(c.skin, 0.28), 1.3);
      ell(ctx, headX + r * 0.62, headY + r * 0.28, r * 0.09, r * 0.06, dark(c.skin, 0.45), null);
      ell(ctx, headX + r * 0.48, headY + r * 0.29, r * 0.08, r * 0.055, dark(c.skin, 0.45), null);
      drawMouth(ctx, char, headX + r * 0.05, headY, r);
    }

    if (char.id === 'bowser') {
      ell(ctx, headX + r * 0.5, headY + r * 0.42, r * 0.52, r * 0.26, '#e8d08a', null);
      drawMouth(ctx, { ...char, mouth: 'fangs' }, headX, headY + r * 0.12, r);
      ell(ctx, headX + r * 0.68, headY + r * 0.32, r * 0.05, r * 0.035, '#6b5a2a', null);
      ell(ctx, headX + r * 0.48, headY + r * 0.34, r * 0.045, r * 0.03, '#6b5a2a', null);
    } else if (char.id === 'thanos') {
      line(ctx, headX + r * 0.0, headY + r * 0.55, headX + r * 0.45, headY + r * 0.5, dark(c.skin, 0.4), 1.6);
      for (let i = 0; i < 3; i++) line(ctx, headX + r * (0.08 + i * 0.12), headY + r * 0.42, headX + r * (0.1 + i * 0.12), headY + r * 0.62, dark(c.skin, 0.28), 1.3);
    } else if (char.mouth !== 'fangs' && char.snout !== 'croc' && char.snout !== 'pig') {
      drawMouth(ctx, char, headX, headY, r);
    } else if (char.snout === 'pig' && char.mask !== 'burn') {
      // mouth already drawn above
    } else {
      drawMouth(ctx, char, headX, headY, r);
    }

    // facial damage / details
    if (char.stitches) {
      const sx = headX + r * 0.05;
      const sy = headY + r * 0.2;
      line(ctx, sx - r * 0.35, sy - r * 0.25, sx + r * 0.25, sy + r * 0.3, '#8e2b25', 1.8);
      for (let i = 0; i < 4; i++) {
        const px = sx - r * 0.27 + i * r * 0.15;
        const py = sy - r * 0.18 + i * r * 0.13;
        line(ctx, px - r * 0.06, py - r * 0.07, px + r * 0.07, py + r * 0.08, '#5e1e1b', 1.2);
      }
      line(ctx, headX + r * 0.5, headY + r * 0.15, headX + r * 0.78, headY + r * 0.4, '#8e2b25', 1.4);
    }
    if (char.wrinkles) {
      line(ctx, headX - r * 0.35, headY - r * 0.48, headX + r * 0.25, headY - r * 0.52, 'rgba(90,55,55,.45)', 1.2);
      line(ctx, headX + r * 0.3, headY + r * 0.2, headX + r * 0.5, headY + r * 0.25, 'rgba(90,55,55,.4)', 1);
      line(ctx, headX - r * 0.35, headY + r * 0.1, headX - r * 0.45, headY + r * 0.28, 'rgba(90,55,55,.4)', 1);
    }
    if (char.id === 'jafar') {
      poly(ctx, [[headX + r * 0.05, headY + r * 0.98], [headX + r * 0.28, headY + r * 0.68], [headX + r * 0.44, headY + r * 1.32]], c.hair);
      line(ctx, headX + r * 0.05, headY + r * 0.68, headX + r * 0.45, headY + r * 0.66, c.hair, 2.4);
    }
    if (char.mask === 'burn') {
      // burned patches & scars
      ctx.save();
      ctx.globalAlpha = 0.85;
      for (const [dx, dy, rx, ry] of [[-0.55, -0.55, 0.3, 0.18], [0.25, 0.62, 0.35, 0.15], [0.55, -0.4, 0.22, 0.2], [-0.1, 0.15, 0.14, 0.1]]) {
        ell(ctx, headX + r * dx, headY + r * dy, r * rx, r * ry, 'rgba(95,40,30,.55)', null);
      }
      for (let i = 0; i < 3; i++) line(ctx, headX - r * 0.65 + i * r * 0.2, headY - r * 0.75, headX - r * 0.3 + i * r * 0.2, headY + r * 0.85, 'rgba(70,30,24,.45)', 1.4);
      ctx.restore();
    }
  }

  // hair / headgear on top
  if (!['vader', 'ghostface', 'pinhead', 'michael', 'jason', 'leather', 'pennywise', 'clown'].includes(char.mask)) {
    drawHairFront(ctx, char, headX, headY, r);
  } else if (char.hair === 'tufts' || char.hair === 'jasonhair' || char.hair === 'leatherhair' || char.hair === 'cowlick' || char.hair === 'clownhorn' || char.hair === 'clownfrizz' || char.hair === 'slick' || char.hair === 'longred') {
    drawHairFront(ctx, char, headX, headY, r);
  }
  drawHeadgear(ctx, char, headX, headY, r, time);
}

// Fighters: skeleton, outfits, weapons, poses.
import { TAU, rr, ell, line, poly, limb, dark, light } from './draw-utils.js';
import { drawHead } from './heads.js';

const BARE_CHEST = new Set(['cyclops', 'rawhead', 'ogre', 'bowser', 'krool', 'ren']);
const BARE_LEGS = new Set(['cyclops', 'rawhead', 'ogre', 'bowser', 'krool', 'ren']);
const ROBED = new Set(['jafar', 'lilith']);

function torsoPath(ctx, hw, sw, hipY, sy) {
  ctx.beginPath();
  ctx.moveTo(-hw, hipY);
  ctx.bezierCurveTo(-hw - 6, hipY - 18, -sw - 2, sy + 18, -sw, sy);
  ctx.quadraticCurveTo(0, sy - 7, sw, sy);
  ctx.bezierCurveTo(sw + 2, sy + 18, hw + 6, hipY - 18, hw, hipY);
  ctx.closePath();
}

function drawCape(ctx, char, sy, hipY, time) {
  if (!char.cape) return;
  const sway = Math.sin(time * 2.2) * 4;
  ctx.beginPath();
  ctx.moveTo(-10, sy - 2);
  ctx.quadraticCurveTo(-48, sy + 18, -58 + sway, hipY + 28);
  ctx.quadraticCurveTo(-66, hipY + 55, -50 + sway, 0);
  ctx.lineTo(-10, -2);
  ctx.quadraticCurveTo(-20, hipY + 20, -6, hipY - 6);
  ctx.closePath();
  const g = ctx.createLinearGradient(0, sy, -50, 0);
  g.addColorStop(0, dark(char.cape, 0.32));
  g.addColorStop(1, dark(char.cape, 0.52));
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = dark(char.cape, 0.6);
  ctx.lineWidth = 1.2;
  ctx.stroke();
  line(ctx, -14, sy + 6, -34, hipY + 34, light(char.cape, 0.1), 1.2);
  // high collar
  poly(ctx, [[-6, sy - 2], [-20, sy - 15], [2, sy - 20], [10, sy - 4]], dark(char.cape, 0.4));
}

function drawShell(ctx, char, hipY, sy, time) {
  if (!char.shell) return;
  const cy = (hipY + sy) / 2 - 2;
  ell(ctx, -18, cy, 42, 50, '#3f7a2c', '#244d19', 3);
  ell(ctx, -18, cy, 31, 39, '#5d9a3d', null);
  ctx.strokeStyle = '#2f5a24';
  ctx.lineWidth = 3;
  for (let i = 0; i < 5; i++) {
    const a = -1.1 + i * 0.55;
    line(ctx, -18 + Math.cos(a) * 15, cy + Math.sin(a) * 20, -18 + Math.cos(a) * 35, cy + Math.sin(a) * 43, '#2f5a24', 3);
  }
  for (let i = 0; i < 5; i++) {
    const a = -2.4 + i * 0.72 + Math.sin(time * 1.5) * 0.02;
    poly(ctx, [[-18 + Math.cos(a) * 44, cy + Math.sin(a) * 52], [-18 + Math.cos(a) * 58, cy + Math.sin(a) * 62], [-18 + Math.cos(a) * 40, cy + Math.sin(a) * 58]], '#e8e2c8', '#8a8468', 2);
  }
}

function drawTail(ctx, char, hipY, time) {
  if (!char.tail) return;
  ctx.save();
  ctx.strokeStyle = char.tail;
  ctx.lineWidth = char.id === 'krool' ? 14 : 5;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-8, hipY - 2);
  ctx.bezierCurveTo(-42, hipY + 12, -58, hipY - 20, -50 + Math.sin(time * 3) * 4, hipY - 46);
  ctx.stroke();
  if (char.id === 'ren') {
    ell(ctx, -50 + Math.sin(time * 3) * 4, hipY - 48, 5, 9, '#f2a7c3', null);
    ctx.strokeStyle = '#d98aa8';
    ctx.lineWidth = 2;
    for (let i = 0; i < 3; i++) line(ctx, -28 - i * 8, hipY + 8 - i * 2, -30 - i * 8, hipY + 15 - i * 2, '#d98aa8', 1.5);
  }
  ctx.restore();
}

function drawLeg(ctx, hip, knee, foot, pants, shoe, size, bare, char) {
  limb(ctx, hip, knee, foot, 14 + size * 7, pants);
  if (bare) {
    ell(ctx, foot[0] + 5, foot[1] + 1, 12 + size * 3, 5.5 + size, shoe, dark(shoe, 0.22), 1.2);
    if (char && (char.id === 'ogre' || char.id === 'cyclops' || char.id === 'rawhead')) {
      for (let i = 0; i < 3; i++) ell(ctx, foot[0] + 10 + i * 2.5, foot[1] - 1, 1.6, 1.2, dark(shoe, 0.35), null);
    }
  } else {
    ell(ctx, foot[0] + 4, foot[1] + 1.5, 12 + size * 2.5, 5.5 + size, shoe, dark(shoe, 0.3), 1.2);
    line(ctx, foot[0] - 5, foot[1] + 5, foot[0] + 15, foot[1] + 5, dark(shoe, 0.5), 2.5);
  }
}

function drawArm(ctx, shoulder, elbow, hand, colorSleeve, colorFore, skin, sleeves, width) {
  limb(ctx, shoulder, elbow, hand, width, sleeves === 'long' ? colorSleeve : colorFore);
  if (sleeves === 'short') {
    const mid = [(shoulder[0] + elbow[0]) / 2, (shoulder[1] + elbow[1]) / 2];
    limb(ctx, shoulder, mid, mid, width, colorSleeve);
  }
  ell(ctx, hand[0], hand[1], 5.6, 5.4, skin, dark(skin, 0.28), 1.1);
}

function outfitDetails(ctx, char, hipY, sy, hw, time) {
  const c = char.colors;
  const id = char.id;
  const tx = (v) => sy + v;
  switch (id) {
    case 'michael':
      line(ctx, 2, sy + 4, 2, hipY - 5, 'rgba(180,190,210,.35)', 1.4);
      line(ctx, -8, sy + 3, 2, sy + 16, dark(c.primary, 0.3), 2);
      line(ctx, 12, sy + 3, 2, sy + 16, dark(c.primary, 0.3), 2);
      line(ctx, -hw + 3, hipY - 24, hw - 3, hipY - 24, 'rgba(10,15,25,.3)', 2);
      break;
    case 'chucky': {
      // overalls bib + straps
      ctx.save();
      torsoPath(ctx, hw, 14, hipY, sy);
      ctx.clip();
      ctx.fillStyle = c.secondary;
      ctx.fillRect(-hw - 8, hipY - 34, hw * 2 + 16, 40);
      ctx.restore();
      ctx.strokeStyle = c.secondary;
      ctx.lineWidth = 5;
      line(ctx, -8, sy + 2, -4, hipY - 30, c.secondary, 5);
      line(ctx, 11, sy + 2, 9, hipY - 30, c.secondary, 5);
      ell(ctx, 2, hipY - 24, 3, 3, c.accent, null);
      ell(ctx, -6, hipY - 24, 2.6, 2.6, c.accent, null);
      break;
    }
    case 'vader':
      ctx.fillStyle = '#2a2c34';
      ctx.fillRect(4, sy + 16, 18, 12);
      ctx.strokeStyle = '#4a4d58';
      ctx.lineWidth = 1;
      ctx.strokeRect(4, sy + 16, 18, 12);
      ell(ctx, 10, sy + 22, 2, 2, '#e12828', null);
      ell(ctx, 16, sy + 22, 2, 2, '#63d463', null);
      line(ctx, -hw + 2, sy + 38, hw - 2, sy + 38, '#0c0d11', 5);
      ctx.fillStyle = '#3a3d48';
      ctx.fillRect(-4, sy + 33, 10, 9);
      break;
    case 'boris':
      rr(ctx, 1, hipY - 22, 25, 13, 5);
      ctx.fillStyle = dark(c.primary, 0.18);
      ctx.fill();
      line(ctx, 3, sy + 6, 2, hipY - 20, '#c33b34', 2);
      line(ctx, 11, sy + 6, 12, hipY - 20, '#c33b34', 2);
      ell(ctx, 3, sy + 6, 2.2, 2.2, c.accent, null);
      ell(ctx, 11, sy + 6, 2.2, 2.2, c.accent, null);
      break;
    case 'bowser':
      ell(ctx, 7, hipY - 16, 21 + char.fat * 8, 25, c.secondary, dark(c.secondary, 0.22), 1.6);
      for (let i = 0; i < 3; i++) line(ctx, -10, hipY - 26 + i * 8, 24, hipY - 28 + i * 8, dark(c.secondary, 0.12), 1.2);
      // spiked collar
      line(ctx, -14, sy + 2, 16, sy + 2, '#2c2c33', 5);
      for (let i = 0; i < 4; i++) poly(ctx, [[-10 + i * 7, sy], [-7 + i * 7, sy - 6], [-4 + i * 7, sy]], '#d9d5c4');
      break;
    case 'bison':
      poly(ctx, [[-14, sy + 1], [-4, sy + 1], [-6, sy + 8], [-16, sy + 7]], c.accent);
      poly(ctx, [[6, sy + 1], [16, sy + 1], [18, sy + 7], [8, sy + 8]], c.accent);
      line(ctx, 2, sy + 10, 2, hipY - 4, c.accent, 2);
      line(ctx, -hw, hipY - 6, hw, hipY - 6, c.accent, 5);
      ell(ctx, 2, hipY - 6, 4, 4, c.primary, c.accent, 1.5);
      break;
    case 'concussion':
      ell(ctx, 5, sy + 4, 15, 5, c.accent, null);
      line(ctx, 3, sy + 8, 2, hipY - 5, dark(c.primary, 0.18), 1.4);
      line(ctx, -9, hipY - 8, 14, hipY - 8, dark(c.primary, 0.2), 2);
      break;
    case 'plankton':
      poly(ctx, [[-9, sy + 3], [-2, sy + 13], [2, sy + 3]], c.secondary);
      line(ctx, 0, sy + 15, 0, hipY - 4, dark(c.primary, 0.25), 1.2);
      break;
    case 'bigbabytom':
      ell(ctx, 6, hipY - 18, 19 + char.fat * 9, 24, 'rgba(255,255,255,.12)', null);
      line(ctx, -10, sy + 4, -4, hipY - 3, c.primary, 2);
      line(ctx, 12, sy + 4, 8, hipY - 3, c.primary, 2);
      break;
    case 'jafar':
      line(ctx, 1, sy + 10, 1, hipY - 4, c.detail, 2.2);
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(-hw, hipY - 2);
      ctx.quadraticCurveTo(-20, hipY + 40, -14, 0);
      ctx.lineTo(22, 0);
      ctx.quadraticCurveTo(12, hipY - 6, hw, hipY - 2);
      ctx.closePath();
      ctx.fillStyle = c.primary;
      ctx.fill();
      ctx.strokeStyle = dark(c.primary, 0.25);
      ctx.lineWidth = 1.4;
      ctx.stroke();
      ctx.restore();
      ctx.save();
      ctx.strokeStyle = c.accent;
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.moveTo(-12, sy + 6);
      ctx.lineTo(13, hipY + 4);
      ctx.stroke();
      ctx.restore();
      break;
    case 'ren':
      ell(ctx, 3, hipY - 24, 11, 17, light(c.skin, 0.16), null);
      for (let i = 0; i < 4; i++) line(ctx, -8 + i * 5, sy + 10, -11 + i * 5, sy + 26, dark(c.skin, 0.2), 1.2);
      break;
    case 'elmer': {
      ctx.save();
      torsoPath(ctx, hw, 16, hipY, sy);
      ctx.clip();
      ctx.strokeStyle = 'rgba(30,30,36,.4)';
      ctx.lineWidth = 2;
      for (let i = -2; i < 4; i++) line(ctx, -20 + i * 12, sy, -20 + i * 12, hipY, 'rgba(30,30,36,.4)', 2);
      for (let i = 0; i < 3; i++) line(ctx, -hw - 4, sy + 20 + i * 14, hw + 4, sy + 20 + i * 14, 'rgba(30,30,36,.4)', 2);
      ctx.restore();
      for (let i = 0; i < 3; i++) ell(ctx, 4, sy + 24 + i * 15, 2.2, 2.2, '#2b2d33', null);
      break;
    }
    case 'killjoy':
      line(ctx, -hw, hipY - 4, hw, hipY - 4, c.accent, 7);
      ell(ctx, 2, hipY - 4, 4, 4, c.detail, c.primary, 1.5);
      for (let i = 0; i < 3; i++) ell(ctx, 3, sy + 20 + i * 14, 3.4, 3.4, i % 2 ? c.accent : c.detail, dark(c.primary, 0.2), 1);
      for (let i = 0; i < 5; i++) poly(ctx, [[-12 + i * 5, sy + 4], [-10 + i * 5, sy - 4], [-8 + i * 5, sy + 4]], i % 2 ? c.accent : c.detail);
      break;
    case 'lilith':
      poly(ctx, [[-8, sy + 8], [10, sy + 8], [6, hipY - 18], [-4, hipY - 18]], c.accent);
      for (let i = 0; i < 3; i++) line(ctx, -6 + i * 4, sy + 14 + i * 8, 8 - i * 4, sy + 18 + i * 8, '#1a1218', 1.2);
      ctx.beginPath();
      ctx.moveTo(-hw, hipY - 1);
      ctx.quadraticCurveTo(-22, hipY + 45, -13, 0);
      ctx.lineTo(24, 0);
      ctx.quadraticCurveTo(12, hipY + 10, hw, hipY - 1);
      ctx.closePath();
      ctx.fillStyle = c.primary;
      ctx.fill();
      break;
    case 'cyclops':
      line(ctx, -10, sy + 14, 16, sy + 10, dark(c.skin, 0.28), 2);
      line(ctx, 2, sy + 12, 2, hipY - 10, dark(c.skin, 0.24), 2);
      for (let i = 0; i < 3; i++) line(ctx, -8, sy + 26 + i * 9, 15, sy + 24 + i * 9, dark(c.skin, 0.16), 1.2);
      rr(ctx, -hw - 2, hipY - 18, hw * 2 + 4, 24, 7);
      ctx.fillStyle = c.primary;
      ctx.fill();
      ctx.strokeStyle = dark(c.primary, 0.28);
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ell(ctx, 2, hipY - 6, 2.4, 2.4, c.accent, null);
      break;
    case 'jason':
      poly(ctx, [[-9, sy + 2], [7, sy + 2], [8, hipY - 2], [-8, hipY - 2]], c.accent);
      poly(ctx, [[-16, sy + 2], [-6, sy + 2], [-8, hipY - 2], [-17, hipY - 2]], c.primary);
      poly(ctx, [[6, sy + 2], [17, sy + 2], [18, hipY - 2], [8, hipY - 2]], c.primary);
      line(ctx, -15, sy + 20, -7, sy + 20, dark(c.primary, 0.3), 1.5);
      line(ctx, 8, sy + 20, 16, sy + 20, dark(c.primary, 0.3), 1.5);
      line(ctx, -14, hipY - 3, 15, hipY - 3, dark(c.secondary, 0.2), 4);
      break;
    case 'freddy': {
      ctx.save();
      torsoPath(ctx, hw, 15, hipY, sy);
      ctx.clip();
      ctx.fillStyle = c.primary;
      ctx.fillRect(-25, sy - 5, 50, hipY - sy + 10);
      for (let i = 0; i < 5; i++) {
        ctx.fillStyle = c.accent;
        ctx.fillRect(-25, sy + 6 + i * 14, 50, 7);
      }
      ctx.restore();
      break;
    }
    case 'drunkbill':
      ell(ctx, 7, hipY - 20, 17 + char.fat * 8, 20, 'rgba(255,255,255,.13)', null);
      for (let i = 0; i < 3; i++) ell(ctx, 4, sy + 18 + i * 15, 1.8, 1.8, '#5b5f66', null);
      line(ctx, -hw, hipY - 3, hw, hipY - 3, '#3b332a', 4);
      break;
    case 'rawhead':
      // exposed chest, armor shoulders and belt
      poly(ctx, [[-20, sy + 2], [-6, sy + 2], [-8, sy + 16], [-20, sy + 12]], c.primary);
      poly(ctx, [[8, sy + 2], [20, sy + 2], [22, sy + 12], [10, sy + 16]], c.primary);
      line(ctx, -10, sy + 20, 18, sy + 18, dark(c.skin, 0.3), 1.6);
      for (let i = 0; i < 3; i++) {
        ell(ctx, -6 + i * 7, sy + 30, 2.4, 2.4, dark(c.skin, 0.22), null);
        ell(ctx, -6 + i * 7, sy + 40, 2.4, 2.4, dark(c.skin, 0.22), null);
      }
      line(ctx, -hw, hipY - 8, hw, hipY - 8, c.primary, 8);
      line(ctx, -hw, hipY - 8, hw, hipY - 8, dark(c.primary, 0.25), 2);
      break;
    case 'ogre':
      ell(ctx, 8, hipY - 18, 20 + char.fat * 9, 22, 'rgba(90,100,92,.35)', null);
      line(ctx, -12, sy + 18, 18, sy + 16, dark(c.skin, 0.22), 2);
      for (let i = 0; i < 2; i++) line(ctx, -8, sy + 30 + i * 9, 15, sy + 29 + i * 9, dark(c.skin, 0.14), 1.4);
      rr(ctx, -hw - 3, hipY - 16, hw * 2 + 6, 22, 5);
      ctx.fillStyle = c.primary;
      ctx.fill();
      line(ctx, -hw, hipY - 13, hw, hipY - 13, dark(c.primary, 0.35), 2);
      break;
    case 'thanos':
      poly(ctx, [[-14, sy + 4], [-2, sy + 4], [-4, hipY - 18], [-14, hipY - 12]], c.primary);
      poly(ctx, [[4, sy + 4], [15, sy + 4], [16, hipY - 14], [6, hipY - 18]], c.primary);
      line(ctx, 2, sy + 8, 2, hipY - 4, dark(c.primary, 0.3), 2);
      for (let i = 0; i < 3; i++) line(ctx, -12 + i * 5, sy + 16, 12 + i * 2, sy + 14, dark(c.primary, 0.2), 1.5);
      line(ctx, -hw, hipY - 6, hw, hipY - 6, c.primary, 6);
      break;
    case 'krool':
      ell(ctx, 6, hipY - 18, 26 + char.fat * 7, 26, c.secondary, dark(c.secondary, 0.2), 1.6);
      line(ctx, -12, sy + 2, 18, sy + 2, '#3f5a2a', 2);
      break;
    case 'pennywise':
      for (let i = 0; i < 4; i++) ell(ctx, 2, sy + 18 + i * 16, 4, 4, c.accent, null);
      for (let i = 0; i < 5; i++) poly(ctx, [[-12 + i * 6, sy + 4], [-9 + i * 6, sy - 5], [-6 + i * 6, sy + 4]], c.primary);
      line(ctx, -hw, hipY - 4, hw, hipY - 4, c.accent, 4);
      break;
    case 'leatherface':
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(-13, sy + 2);
      ctx.lineTo(9, sy + 2);
      ctx.lineTo(14, hipY);
      ctx.lineTo(-18, hipY);
      ctx.closePath();
      ctx.fillStyle = '#b89a7a';
      ctx.fill();
      ctx.strokeStyle = '#7d6449';
      ctx.lineWidth = 1.2;
      ctx.stroke();
      for (const [dx, dy, rx, ry] of [[-6, sy + 26, 7, 4], [3, sy + 48, 5, 6], [-10, hipY - 20, 4, 3]]) {
        ell(ctx, dx, dy, rx, ry, 'rgba(120,30,24,.5)', null);
      }
      line(ctx, -11, sy + 2, -7, sy - 6, '#f0e4cc', 2);
      line(ctx, 7, sy + 2, 3, sy - 6, '#f0e4cc', 2);
      ctx.restore();
      break;
    case 'ghostface':
      line(ctx, -hw, hipY - 7, hw, hipY - 7, c.accent, 4);
      line(ctx, 0, sy + 4, 0, hipY - 7, dark(c.primary, 0.35), 1.4);
      break;
    case 'pinhead':
      line(ctx, 0, sy + 4, 0, hipY - 5, dark(c.primary, 0.35), 1.2);
      for (let i = 0; i < 4; i++) {
        ell(ctx, -10 + i * 7, sy + 16, 1.6, 1.6, '#8b8b96', null);
        ell(ctx, -10 + i * 7, sy + 36, 1.6, 1.6, '#8b8b96', null);
      }
      line(ctx, -hw, hipY - 5, hw, hipY - 5, c.accent, 3);
      break;
    case 'dracula':
      poly(ctx, [[-11, sy + 2], [10, sy + 2], [7, hipY - 14], [-8, hipY - 14]], c.accent);
      poly(ctx, [[-3, sy + 2], [4, sy + 2], [1, sy + 16], [-6, sy + 16]], '#e9e2d2');
      line(ctx, -10, sy + 3, 2, sy + 16, c.primary, 4);
      line(ctx, 10, sy + 3, 2, sy + 16, c.primary, 4);
      ell(ctx, 0, sy + 26, 4, 4, c.detail, '#5a4a30', 1.2);
      break;
    default:
      break;
  }
  // belt for most characters
  if (!['michael', 'chucky', 'vader', 'jafar', 'lilith', 'cyclops', 'ogre', 'krool', 'rawhead', 'pennywise', 'leatherface', 'ghostface', 'pinhead', 'thanos'].includes(id)) {
    line(ctx, -hw + 1, hipY - 3, hw - 1, hipY - 3, dark(c.secondary, 0.2), 3.5);
  }
  if (ROBED.has(id)) {
    // hanging robe panels in front of legs
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(-hw, hipY - 2);
    ctx.quadraticCurveTo(-20, hipY + 22, -15, 0);
    ctx.lineTo(-3, 0);
    ctx.quadraticCurveTo(-4, hipY + 6, 4, hipY - 2);
    ctx.closePath();
    ctx.fillStyle = dark(c.primary, 0.08);
    ctx.fill();
    ctx.strokeStyle = dark(c.primary, 0.3);
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.restore();
  }
}

function drawWeapon(ctx, char, hand, angle, pose, time) {
  const c = char.colors;
  const w = char.weapon;
  if (!w || w === 'fists' || w === 'none' || w === 'gauntlet' || w === 'balloon') return;
  ctx.save();
  ctx.translate(hand[0], hand[1]);
  ctx.rotate(angle);
  const metal = '#c8ced7';
  const metalDark = '#7d8592';
  switch (w) {
    case 'knife':
      ctx.fillStyle = '#4a3526';
      rr(ctx, -7, -2.6, 9, 5.2, 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(1, -3.4);
      ctx.lineTo(26, -2);
      ctx.quadraticCurveTo(31, 0, 25, 2.4);
      ctx.lineTo(1, 3.4);
      ctx.closePath();
      ctx.fillStyle = metal;
      ctx.fill();
      ctx.strokeStyle = metalDark;
      ctx.lineWidth = 0.9;
      ctx.stroke();
      line(ctx, 3, 0, 23, 0.5, '#eef2f6', 1);
      break;
    case 'axe':
      ctx.fillStyle = '#6b4a2c';
      rr(ctx, -6, -2.8, 38, 5.6, 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(27, -3);
      ctx.quadraticCurveTo(41, -19, 44, -3);
      ctx.lineTo(42, 2);
      ctx.quadraticCurveTo(38, 11, 26, 6);
      ctx.closePath();
      ctx.fillStyle = '#c0392b';
      ctx.fill();
      ctx.strokeStyle = '#7d2118';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(43, -8);
      ctx.quadraticCurveTo(49, -2, 44, 5);
      ctx.strokeStyle = '#e8edf2';
      ctx.lineWidth = 2;
      ctx.stroke();
      break;
    case 'saber':
      ctx.fillStyle = '#2b2d34';
      rr(ctx, -7, -3.2, 17, 6.4, 2);
      ctx.fill();
      line(ctx, -4, 0, 8, 0, '#8b919e', 1.5);
      ctx.save();
      ctx.shadowColor = '#ff2a1a';
      ctx.shadowBlur = 14;
      ctx.fillStyle = 'rgba(220,30,20,.55)';
      rr(ctx, 10, -3.6, 50, 7.2, 3.6);
      ctx.fill();
      ctx.fillStyle = '#ff6a58';
      rr(ctx, 11, -2.1, 48, 4.2, 2.1);
      ctx.fill();
      ctx.fillStyle = '#ffe7e0';
      rr(ctx, 12, -1, 46, 2, 1);
      ctx.fill();
      ctx.restore();
      break;
    case 'machete':
      ctx.fillStyle = '#3f2e22';
      rr(ctx, -8, -2.5, 10, 5, 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(0, -4);
      ctx.lineTo(30, -5);
      ctx.quadraticCurveTo(39, 0, 29, 6);
      ctx.lineTo(0, 4.5);
      ctx.closePath();
      ctx.fillStyle = '#aab2ba';
      ctx.fill();
      ctx.strokeStyle = '#5f6874';
      ctx.lineWidth = 1;
      ctx.stroke();
      line(ctx, 2, 3, 28, 3.5, '#e6ebef', 1);
      break;
    case 'ruler':
      ctx.fillStyle = '#e8c24a';
      rr(ctx, -5, -3, 34, 6, 1.5);
      ctx.fill();
      ctx.strokeStyle = '#9c7a1c';
      ctx.lineWidth = 1;
      ctx.stroke();
      for (let i = 0; i < 5; i++) line(ctx, 5 + i * 5.5, -3, 5 + i * 5.5, -0.5, '#6b5210', 1);
      break;
    case 'staff':
      line(ctx, -34, 1, 36, -1, '#4a2e1d', 4.5);
      line(ctx, -34, 1, 36, -1, '#7a5130', 1.6);
      ctx.save();
      ctx.shadowColor = c.detail;
      ctx.shadowBlur = 12;
      ell(ctx, 38, -1, 7, 7, c.detail, null);
      ell(ctx, 36, -3, 2.6, 2.6, '#eafbe6', null);
      ctx.restore();
      ctx.beginPath();
      ctx.arc(36, 1, 9, -1.2, 1.2);
      ctx.strokeStyle = dark(c.detail, 0.25);
      ctx.lineWidth = 2;
      ctx.stroke();
      break;
    case 'shotgun':
      ctx.fillStyle = '#5a3d28';
      poly(ctx, [[-15, 1], [-4, -3], [-4, 3]], '#5a3d28');
      ctx.fillStyle = '#343a42';
      rr(ctx, -4, -2.6, 34, 5.2, 2);
      ctx.fill();
      rr(ctx, 28, -3.4, 17, 6.8, 2);
      ctx.fillStyle = '#2a2f36';
      ctx.fill();
      line(ctx, -2, -2, 30, -2, '#8c96a3', 1.2);
      line(ctx, 8, 2, 20, 2, '#565f6a', 1.6);
      break;
    case 'bottle':
      ctx.fillStyle = 'rgba(80,150,80,.85)';
      rr(ctx, 0, -4.5, 15, 9, 3);
      ctx.fill();
      rr(ctx, 14, -2.2, 8, 4.4, 2);
      ctx.fill();
      ctx.fillStyle = '#d9d0b0';
      rr(ctx, 20, -2.4, 4, 4.8, 1);
      ctx.fill();
      line(ctx, 2, -2.5, 12, -2.5, 'rgba(230,255,230,.6)', 1.4);
      break;
    case 'claw': {
      if (char.id === 'freddy') {
        ctx.fillStyle = '#5a4030';
        rr(ctx, -6, -4, 12, 8, 3);
        ctx.fill();
        for (let i = 0; i < 4; i++) {
          const yy = -4 + i * 2.6;
          ctx.beginPath();
          ctx.moveTo(5, yy);
          ctx.quadraticCurveTo(17, yy - 2, 26, yy - 1);
          ctx.strokeStyle = metal;
          ctx.lineWidth = 1.8;
          ctx.stroke();
          line(ctx, 24, yy - 1, 28, yy - 5, '#e8eef2', 1.2);
        }
      } else {
        for (let i = 0; i < 4; i++) {
          poly(ctx, [[-2 + i * 3, -4], [9 + i * 3, -7 + i * 0.5], [6 + i * 3, 3 - i * 1.2]], char.id === 'bowser' ? '#efe8d2' : '#e0d6c2');
        }
      }
      break;
    }
    case 'chainsaw':
      ctx.fillStyle = '#8b5a2b';
      rr(ctx, -7, -5, 17, 10, 2);
      ctx.fill();
      ctx.fillStyle = '#c4682c';
      rr(ctx, 3, -4.2, 12, 8.4, 2);
      ctx.fill();
      ctx.fillStyle = '#9aa2ac';
      rr(ctx, 14, -6.5, 31, 13, 3);
      ctx.fill();
      ctx.fillStyle = '#4a5058';
      rr(ctx, 16, -4.5, 27, 3, 1);
      ctx.fill();
      for (let i = 0; i < 8; i++) poly(ctx, [[15 + i * 3.7, 6.4], [17 + i * 3.7, 10], [19 + i * 3.7, 6.4]], '#dbe1e6');
      line(ctx, 19, -6.5, 19, 6.5, '#5a6068', 1);
      break;
    case 'blade':
      ctx.fillStyle = '#3a2a24';
      rr(ctx, -7, -3, 10, 6, 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(2, -3.6);
      ctx.lineTo(26, -5);
      ctx.quadraticCurveTo(32, -1, 25, 5);
      ctx.lineTo(2, 3.4);
      ctx.closePath();
      ctx.fillStyle = '#d9dee4';
      ctx.fill();
      ctx.strokeStyle = '#8a929c';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(23, -3, 4, -1.4, 1.4);
      ctx.strokeStyle = c.accent;
      ctx.lineWidth = 1;
      ctx.stroke();
      break;
    case 'raygun':
      ctx.fillStyle = '#7d838d';
      rr(ctx, -4, -5, 14, 8, 3);
      ctx.fill();
      rr(ctx, 8, -3, 11, 5, 2.5);
      ctx.fill();
      ctx.save();
      ctx.shadowColor = c.detail;
      ctx.shadowBlur = 10;
      ell(ctx, 20, -0.5, 3.6, 3.6, c.detail, null);
      ctx.restore();
      line(ctx, 1, 2, 3, 8, '#4a4f58', 3);
      break;
    case 'chains':
      ctx.strokeStyle = '#8b8b96';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        ctx.beginPath();
        ctx.arc(4 + i * 7, i % 2 ? -2 : 2, 4, 0.3, 5.6);
        ctx.stroke();
      }
      line(ctx, 30, 0, 38, -4, '#b9c4d9', 1.6);
      poly(ctx, [[34, -4], [42, -8], [40, -1], [45, 2], [36, 2]], '#b9c4d9');
      break;
    default: break;
  }
  ctx.restore();
}

function drawGauntlet(ctx, char, hand, time) {
  if (char.weapon !== 'gauntlet') return;
  ctx.save();
  ctx.translate(hand[0], hand[1]);
  ctx.fillStyle = '#d9b95a';
  rr(ctx, -8, -7, 16, 15, 5);
  ctx.fill();
  ctx.strokeStyle = '#8a6a1f';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  const gems = ['#b34cff', '#4cc9ff', '#ff4c4c', '#ffb347', '#7dff6a'];
  for (let i = 0; i < 5; i++) {
    ctx.save();
    ctx.shadowColor = gems[i];
    ctx.shadowBlur = 6;
    ell(ctx, -5 + i * 2.6, -4 + (i % 2) * 8, 1.6, 1.6, gems[i], null);
    ctx.restore();
  }
  ctx.restore();
}

function drawBalloon(ctx, char, hand, head, time) {
  if (char.weapon !== 'balloon') return;
  const bx = head[0] + 30;
  const by = head[1] - 52 + Math.sin(time * 1.6) * 5;
  ctx.beginPath();
  ctx.moveTo(hand[0], hand[1]);
  ctx.quadraticCurveTo(hand[0] + 20, head[1] - 10, bx, by + 20);
  ctx.strokeStyle = 'rgba(230,225,215,.75)';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.save();
  ctx.shadowColor = '#ff3b3b';
  ctx.shadowBlur = 12;
  ell(ctx, bx, by, 13, 17, '#d92b2b', '#8e1515', 1.2);
  ctx.restore();
  poly(ctx, [[bx - 4, by + 16], [bx + 4, by + 16], [bx, by + 21]], '#8e1515');
  ell(ctx, bx - 4, by - 5, 3.2, 5, 'rgba(255,255,255,.3)', null);
}

function drawSlashArc(ctx, char, pose, progress, sy, hipY) {
  if (!['punch', 'kick', 'special'].includes(pose)) return;
  const a = Math.max(0, Math.min(1, progress));
  if (a < 0.04 || a > 0.62) return;
  const fade = Math.min(1, (a - 0.04) * 6) * Math.min(1, (0.62 - a) * 3.2);
  const color = char.special.color || '#ffffff';
  ctx.save();
  ctx.strokeStyle = color;
  ctx.globalAlpha = fade * 0.55;
  ctx.lineWidth = 5;
  ctx.lineCap = 'round';
  ctx.shadowColor = color;
  ctx.shadowBlur = 10;
  ctx.beginPath();
  if (pose === 'kick') {
    ctx.arc(0, hipY + 8, 56, -0.15, 0.9);
  } else {
    ctx.arc(6, sy + 8, 46, -0.75, 0.55);
  }
  ctx.stroke();
  ctx.globalAlpha = fade * 0.9;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  if (pose === 'kick') ctx.arc(0, hipY + 8, 50, -0.1, 0.85);
  else ctx.arc(6, sy + 8, 40, -0.7, 0.5);
  ctx.stroke();
  ctx.restore();
}

function drawBill(ctx, char, o) {
  const { time, pose } = o;
  const bob = Math.sin(time * 2.4) * 3;
  const spin = pose === 'win' ? Math.sin(time * 8) * 0.12 : 0;
  ctx.save();
  ctx.translate(0, bob);
  ctx.rotate(spin);
  // stick legs
  ctx.strokeStyle = '#14121a';
  ctx.lineWidth = 5;
  ctx.lineCap = 'round';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(side * 12, -38);
    ctx.quadraticCurveTo(side * 16, -20, side * 15, -3);
    ctx.stroke();
    ell(ctx, side * 16, -2, 9, 4.5, '#14121a', null);
  }
  // arms
  ctx.lineWidth = 5;
  const armSwing = pose === 'punch' ? -26 : Math.sin(time * 2) * 4;
  ctx.beginPath();
  ctx.moveTo(-34, -88);
  ctx.lineTo(-56, -80 + armSwing);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(34, -88);
  ctx.lineTo(56, -96 - armSwing);
  ctx.stroke();
  ell(ctx, -57, -80 + armSwing, 5, 5, '#14121a', null);
  ell(ctx, 57, -96 - armSwing, 5, 5, '#14121a', null);
  // triangle body
  ctx.beginPath();
  ctx.moveTo(0, -170);
  ctx.lineTo(-46, -42);
  ctx.lineTo(46, -42);
  ctx.closePath();
  const g = ctx.createLinearGradient(-30, -160, 30, -40);
  g.addColorStop(0, '#ffe75c');
  g.addColorStop(0.55, '#f2d33c');
  g.addColorStop(1, '#d9b82a');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = '#3a2e0a';
  ctx.lineWidth = 2.5;
  ctx.stroke();
  // brick lines
  ctx.save();
  ctx.clip();
  ctx.strokeStyle = 'rgba(120,90,10,.25)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 7; i++) line(ctx, -50, -160 + i * 18, 50, -160 + i * 18, 'rgba(120,90,10,.22)', 1);
  for (let i = 0; i < 5; i++) line(ctx, -30 + i * 14, -150, -20 + i * 14, -50, 'rgba(120,90,10,.16)', 1);
  ctx.restore();
  // bow tie
  poly(ctx, [[-8, -42], [0, -36], [8, -42], [8, -30], [0, -36], [-8, -30]], '#14121a');
  // eye
  ell(ctx, 0, -108, 24, 21, '#f7f2df', '#2a2410', 2);
  ell(ctx, 4, -107, 7.5, 9, '#14121a', null);
  ell(ctx, 7, -111, 2.2, 2.2, '#fff', null);
  line(ctx, -19, -120, 16, -123, '#14121a', 2.4);
  // top hat
  ell(ctx, 0, -168, 30, 5, '#14121a', null);
  ctx.fillStyle = '#14121a';
  ctx.fillRect(-17, -205, 34, 38);
  ctx.fillStyle = '#3a3446';
  ctx.fillRect(-17, -181, 34, 5);
  ctx.restore();
}

export function drawFighter(ctx, char, o = {}) {
  const {
    x = 0, y = 0, facing = 1, pose = 'idle', time = 0, progress = 0,
    alpha = 1, scale = 1, flash = 0,
  } = o;
  const c = char.colors;
  const fat = char.fat || 0;
  const s = (char.scale || 1) * scale;
  const isBill = char.body === 'triangle';

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(x, y);
  ctx.scale(facing * s, s);
  if (flash > 0) ctx.filter = `brightness(${1 + flash * 1.8}) saturate(${1 - flash * 0.4})`;
  if (pose === 'ko') {
    ctx.rotate(-1.32);
    ctx.translate(-4, -4);
  }

  if (isBill) {
    drawBill(ctx, char, o);
    ctx.restore();
    return;
  }

  const hunch = char.body === 'hunch';
  let crouch = pose === 'block' ? 7 : 0;
  let bob = 0;
  if (pose === 'idle' || pose === 'preview') bob = Math.sin(time * 2.2) * 1.2;
  else if (pose === 'walk') bob = Math.abs(Math.sin(time * 9)) * 1.8;
  else if (pose === 'win') bob = Math.sin(time * 6) * 2;

  const hipY = -50 + crouch;
  const sy = (hunch ? -101 : -110) + crouch + bob;
  const headR = 20 * char.headScale;
  const headX = 4 + (hunch ? 9 : 0) + (pose === 'hit' ? -5 : 0);
  const headY = sy - 27 - (char.headScale - 1) * 3 + (hunch ? 2 : 0);
  const head = [headX, headY];

  // pose body
  let fF = [16, -4];
  let fB = [-16, -4];
  let handF = [24, sy + 46];
  let elbowF = [18, sy + 24];
  let handB = [-20, sy + 43];
  let elbowB = [-16, sy + 22];
  const stride = Math.sin(time * 9);

  if (pose === 'walk') {
    fF = [16 + stride * 14, -4 - Math.max(0, stride) * 7];
    fB = [-16 - stride * 14, -4 - Math.max(0, -stride) * 7];
    handF = [24 - stride * 10, sy + 44];
    elbowF = [18 - stride * 6, sy + 24];
    handB = [-20 + stride * 10, sy + 42];
    elbowB = [-16 + stride * 6, sy + 23];
  } else if (pose === 'jump') {
    fF = [10, -22];
    fB = [-14, -14];
    handF = [20, sy + 12];
    elbowF = [26, sy + 23];
    handB = [-18, sy + 10];
    elbowB = [-24, sy + 21];
  } else if (pose === 'kick') {
    fF = [52, -52];
    fB = [-18, -4];
    handF = [34, sy + 4];
    elbowF = [28, sy + 24];
    handB = [-28, sy + 14];
    elbowB = [-24, sy + 20];
  } else if (pose === 'punch') {
    fF = [22, -4];
    fB = [-20, -4];
    handF = [58 + (char.stats.reach || 3) * 2, sy + 2];
    elbowF = [34, sy + 2];
    handB = [-24, sy + 26];
    elbowB = [-20, sy + 20];
  } else if (pose === 'special') {
    fF = [26, -4];
    fB = [-24, -4];
    handF = [46, sy - 12];
    elbowF = [30, sy + 8];
    handB = [14, sy - 26];
    elbowB = [-6, sy - 2];
  } else if (pose === 'block') {
    fF = [24, -4];
    fB = [-24, -4];
    handF = [26, sy + 4];
    elbowF = [24, sy + 22];
    handB = [12, sy - 2];
    elbowB = [2, sy + 18];
  } else if (pose === 'hit') {
    fF = [24, -4];
    fB = [-22, -4];
    handF = [38, sy + 10];
    elbowF = [30, sy + 22];
    handB = [-30, sy + 6];
    elbowB = [-24, sy + 18];
  } else if (pose === 'win') {
    fF = [18, -4];
    fB = [-20, -4];
    handF = [28, sy - 24];
    elbowF = [28, sy + 6];
    handB = [-26, sy - 28];
    elbowB = [-24, sy + 2];
  }

  const footSpread = fat * 5;
  fF[0] += footSpread;
  fB[0] -= footSpread;

  const kneeF = [(0 + fF[0]) / 2 + 8 + fat * 4, (hipY + fF[1]) / 2 + 2];
  const kneeB = [(0 + fB[0]) / 2 - 8 - fat * 4, (hipY + fB[1]) / 2 + 2];

  // 1. cape / shell / tail behind
  drawCape(ctx, char, sy, hipY, time);
  drawShell(ctx, char, hipY, sy, time);
  drawTail(ctx, char, hipY, time);

  const pants = BARE_LEGS.has(char.id) ? c.skin : c.secondary;
  const sleeve = char.sleeveColor || c.primary;
  const forearm = char.sleeves === 'short' ? c.skin : sleeve;

  // 2. back leg
  drawLeg(ctx, [0, hipY - 2], kneeB, fB, dark(pants, 0.18), c.shoes, fat, BARE_LEGS.has(char.id), char);
  // 3. back arm
  drawArm(ctx, [-4, sy + 6], elbowB, handB, dark(sleeve, 0.18), dark(forearm, 0.18), dark(c.skin, 0.12), char.sleeves, 9 + fat * 4);

  // 4. torso
  const hw = 12 + fat * 17 + (char.id === 'ren' ? -3 : 0);
  const sw = 14 + fat * 7;
  const torsoColor = BARE_CHEST.has(char.id) ? c.skin : c.primary;
  torsoPath(ctx, hw, sw, hipY, sy);
  const tg = ctx.createLinearGradient(-sw, sy, sw, hipY);
  tg.addColorStop(0, light(torsoColor, 0.1));
  tg.addColorStop(0.6, torsoColor);
  tg.addColorStop(1, dark(torsoColor, 0.2));
  ctx.fillStyle = tg;
  ctx.fill();
  ctx.strokeStyle = dark(torsoColor, 0.35);
  ctx.lineWidth = 1.2;
  ctx.stroke();

  outfitDetails(ctx, char, hipY, sy, hw, time);

  // 5. front leg
  drawLeg(ctx, [2, hipY - 2], kneeF, fF, pants, c.shoes, fat, BARE_LEGS.has(char.id), char);

  // 6. neck
  ell(ctx, headX - 2, sy - 4, 7, 6, c.skin, null);

  // 7. front arm + weapon slash
  drawSlashArc(ctx, char, pose, progress, sy, hipY);
  drawArm(ctx, [4, sy + 4], elbowF, handF, sleeve, forearm, c.skin, char.sleeves, 10 + fat * 4);

  let weaponAngle = 1.12;
  if (char.weapon === 'staff') weaponAngle = -1.32;
  else if (char.weapon === 'saber') weaponAngle = -1.15;
  else if (char.weapon === 'shotgun') weaponAngle = 0.35;
  else if (char.weapon === 'chainsaw') weaponAngle = 0.5;
  if (pose === 'walk') weaponAngle += Math.sin(time * 9) * 0.08;
  if (pose === 'jump') weaponAngle = 1.35;
  if (pose === 'punch') weaponAngle = 0.02;
  if (pose === 'kick') weaponAngle = 0.9;
  if (pose === 'special') weaponAngle = -0.38;
  if (pose === 'block') weaponAngle = 0.65;
  if (pose === 'hit') weaponAngle = 1.5;
  if (pose === 'win') weaponAngle = -1.15;
  if (pose === 'ko') weaponAngle = 1.5;

  drawWeapon(ctx, char, handF, weaponAngle, pose, time);
  // hand over the grip
  ell(ctx, handF[0], handF[1], 5.6, 5.4, c.skin, dark(c.skin, 0.28), 1.1);
  drawGauntlet(ctx, char, handF, time);

  // 8. head
  drawHead(ctx, char, { headX, headY, headR, time, pose });

  // 9. prop extras
  drawBalloon(ctx, char, handF, head, time);

  // back hand for forms where it reads
  ctx.restore();
}

export function drawFighterShadow(ctx, char, x, y, scale = 1, alpha = 0.45) {
  const s = (char.scale || 1) * scale;
  const fat = char.fat || 0;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.ellipse(x, y + 2, (26 + fat * 20) * s, 8 * s, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

// Painted arenas. All procedural, 1280x720 coordinate space.
import { TAU, ell, line, poly, seeded, rr, dark, light } from './draw-utils.js';

const GROUND = 596;

function vignette(ctx, w, h, strength = 0.7) {
  const g = ctx.createRadialGradient(w / 2, h * 0.48, h * 0.2, w / 2, h * 0.5, h * 0.82);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.72, `rgba(0,0,0,${strength * 0.25})`);
  g.addColorStop(1, `rgba(0,0,0,${strength})`);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
}

function haze(ctx, x, y, w, h, color, time, speed = 1) {
  const g = ctx.createRadialGradient(x, y, 10, x, y, w);
  g.addColorStop(0, color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.globalAlpha = 0.25 + Math.sin(time * speed) * 0.05;
  ctx.fillStyle = g;
  ctx.fillRect(x - w, y - h, w * 2, h * 2);
  ctx.restore();
}

function stageHaddonfield(ctx, w, h, t) {
  const sky = ctx.createLinearGradient(0, 0, 0, GROUND);
  sky.addColorStop(0, '#050a18');
  sky.addColorStop(0.45, '#101d36');
  sky.addColorStop(0.8, '#25344b');
  sky.addColorStop(1, '#3a4552');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, w, GROUND);

  // stars
  for (let i = 0; i < 90; i++) {
    const sx = seeded(i * 3 + 1) * w;
    const sy = seeded(i * 7 + 3) * GROUND * 0.55;
    const a = 0.25 + seeded(i * 11) * 0.6;
    ctx.fillStyle = `rgba(220,235,255,${a})`;
    ctx.fillRect(sx, sy, 1.5, 1.5);
  }

  // moon
  ctx.save();
  ctx.shadowColor = 'rgba(200,220,255,.65)';
  ctx.shadowBlur = 70;
  ell(ctx, 1010, 128, 57, 57, '#e6ecdf', null);
  ctx.restore();
  ell(ctx, 990, 112, 13, 9, 'rgba(150,160,150,.35)', null);
  ell(ctx, 1020, 146, 18, 12, 'rgba(150,160,150,.25)', null);
  ell(ctx, 996, 150, 7, 5, 'rgba(150,160,150,.3)', null);

  // clouds
  for (let i = 0; i < 5; i++) {
    const cx = 150 + i * 270 + Math.sin(t * 0.05 + i) * 18;
    const cy = 90 + (i % 3) * 55;
    ctx.fillStyle = 'rgba(20,32,54,.55)';
    ell(ctx, cx, cy, 100, 22, 'rgba(22,34,56,.55)', null);
    ell(ctx, cx + 40, cy - 10, 70, 20, 'rgba(25,38,62,.45)', null);
  }

  // distant tree line
  ctx.fillStyle = '#0a1220';
  for (let i = 0; i < 9; i++) {
    const bx = -20 + i * 160;
    ctx.beginPath();
    ctx.moveTo(bx, GROUND - 120);
    ctx.lineTo(bx + 40, GROUND - 185 - (i % 3) * 20);
    ctx.lineTo(bx + 90, GROUND - 120);
    ctx.fill();
  }

  // houses
  const houses = [
    { x: 40, y: GROUND - 150, w: 260, h: 150, roof: 80 },
    { x: 330, y: GROUND - 185, w: 210, h: 185, roof: 70 },
    { x: 900, y: GROUND - 165, w: 300, h: 165, roof: 95 },
  ];
  for (const ho of houses) {
    ctx.fillStyle = '#111a26';
    ctx.fillRect(ho.x, ho.y, ho.w, ho.h);
    ctx.beginPath();
    ctx.moveTo(ho.x - 18, ho.y);
    ctx.lineTo(ho.x + ho.w / 2, ho.y - ho.roof);
    ctx.lineTo(ho.x + ho.w + 18, ho.y);
    ctx.closePath();
    ctx.fillStyle = '#0b131d';
    ctx.fill();
    // windows
    for (let ix = 0; ix < 3; ix++) {
      for (let iy = 0; iy < 2; iy++) {
        const lit = (ix + iy + ho.x) % 3 === 0;
        const wx = ho.x + 30 + ix * (ho.w / 3.2);
        const wy = ho.y + 26 + iy * 56;
        ctx.fillStyle = lit ? 'rgba(255,190,90,.72)' : 'rgba(15,24,36,.9)';
        ctx.fillRect(wx, wy, 24, 30);
        ctx.strokeStyle = '#0a111a';
        ctx.lineWidth = 3;
        ctx.strokeRect(wx, wy, 24, 30);
        line(ctx, wx + 12, wy, wx + 12, wy + 30, '#0a111a', 2);
        line(ctx, wx, wy + 15, wx + 24, wy + 15, '#0a111a', 2);
        if (lit) {
          ctx.fillStyle = 'rgba(255,190,90,.08)';
          ctx.fillRect(wx - 10, wy - 8, 44, 48);
        }
      }
    }
  }

  // road / sidewalk
  ctx.fillStyle = '#2c323c';
  ctx.fillRect(0, GROUND, w, h - GROUND);
  ctx.fillStyle = '#3b424c';
  ctx.fillRect(0, GROUND, w, 30);
  ctx.fillStyle = '#454d57';
  for (let i = 0; i < 12; i++) ctx.fillRect(i * 120 - 10, GROUND + 9, 60, 3);
  ctx.fillStyle = '#242a33';
  ctx.fillRect(0, GROUND + 62, w, h - GROUND - 62);
  ctx.fillStyle = 'rgba(210,180,120,.18)';
  ctx.fillRect(0, GROUND + 92, w, 3);
  for (let i = 0; i < 7; i++) {
    ctx.fillStyle = `rgba(255,235,170,${0.32 + seeded(i * 9) * 0.2})`;
    ctx.fillRect(90 + i * 175, GROUND + 101, 56, 3.4);
  }

  // picket fence
  ctx.fillStyle = '#8d8f83';
  for (let i = 0; i < 34; i++) {
    const fx = -5 + i * 40;
    if (fx > 240 && fx < 330) continue;
    ctx.beginPath();
    ctx.moveTo(fx, GROUND - 6);
    ctx.lineTo(fx + 8, GROUND - 20);
    ctx.lineTo(fx + 16, GROUND - 6);
    ctx.lineTo(fx + 16, GROUND - 56);
    ctx.lineTo(fx, GROUND - 56);
    ctx.closePath();
    ctx.fillStyle = i % 5 === 0 ? '#6c6e64' : '#83857a';
    ctx.fill();
  }
  ctx.fillStyle = '#9a9c90';
  ctx.fillRect(0, GROUND - 40, 240, 4);
  ctx.fillRect(330, GROUND - 40, 300, 4);

  // street lamp
  const lampX = 790;
  ctx.strokeStyle = '#0d131c';
  ctx.lineWidth = 7;
  ctx.beginPath();
  ctx.moveTo(lampX, GROUND);
  ctx.lineTo(lampX, GROUND - 230);
  ctx.quadraticCurveTo(lampX, GROUND - 255, lampX + 35, GROUND - 252);
  ctx.stroke();
  ell(ctx, lampX + 42, GROUND - 246, 11, 14, 'rgba(255,215,130,.9)', null);
  ctx.save();
  const cone = ctx.createLinearGradient(lampX + 42, GROUND - 240, lampX + 42, GROUND);
  cone.addColorStop(0, 'rgba(255,210,130,.2)');
  cone.addColorStop(1, 'rgba(255,210,130,0)');
  ctx.fillStyle = cone;
  ctx.beginPath();
  ctx.moveTo(lampX + 34, GROUND - 240);
  ctx.lineTo(lampX + 50, GROUND - 240);
  ctx.lineTo(lampX + 155, GROUND);
  ctx.lineTo(lampX - 80, GROUND);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // pumpkins
  const pumpkins = [[185, GROUND + 36, 25], [1080, GROUND + 60, 32], [1180, GROUND + 34, 19]];
  for (const [px, py, pr] of pumpkins) {
    ell(ctx, px, py, pr, pr * 0.78, '#b4561c', '#5f2a0c', 2);
    ell(ctx, px - pr * 0.38, py + 1, pr * 0.3, pr * 0.68, '#c96a24', null);
    ell(ctx, px + pr * 0.38, py + 1, pr * 0.3, pr * 0.68, '#9e4716', null);
    line(ctx, px, py - pr * 0.7, px + 3, py - pr * 1.05, '#3e5a24', 3);
    poly(ctx, [[px - pr * 0.4, py - pr * 0.05], [px - pr * 0.15, py - pr * 0.25], [px - pr * 0.1, py - pr * 0.02]], 'rgba(255,190,60,.9)');
    poly(ctx, [[px + pr * 0.15, py - pr * 0.25], [px + pr * 0.4, py - pr * 0.02], [px + pr * 0.1, py - pr * 0.02]], 'rgba(255,190,60,.9)');
    ctx.fillStyle = 'rgba(255,170,50,.75)';
    ctx.beginPath();
    ctx.moveTo(px - pr * 0.3, py + pr * 0.16);
    ctx.quadraticCurveTo(px, py + pr * 0.4, px + pr * 0.3, py + pr * 0.14);
    ctx.quadraticCurveTo(px, py + pr * 0.28, px - pr * 0.3, py + pr * 0.16);
    ctx.fill();
  }

  // low fog
  for (let i = 0; i < 4; i++) {
    const fx = ((t * (9 + i * 3) + i * 380) % (w + 500)) - 250;
    haze(ctx, fx, GROUND - 15 - i * 8, 230, 52, 'rgba(190,205,225,.35)', t, 0.6 + i * 0.2);
  }

  // trees at edges
  ctx.strokeStyle = '#070c14';
  ctx.lineWidth = 16;
  for (const [tx, s] of [[70, 1], [1210, 1.1]]) {
    ctx.beginPath();
    ctx.moveTo(tx, GROUND + 20);
    ctx.lineTo(tx + 6 * s, GROUND - 190);
    ctx.stroke();
    ctx.lineWidth = 6;
    for (let i = 0; i < 5; i++) {
      ctx.beginPath();
      ctx.moveTo(tx + i * 2, GROUND - 100 - i * 18);
      ctx.lineTo(tx + (i % 2 ? 55 : -55) * s, GROUND - 175 - i * 20);
      ctx.stroke();
    }
    ctx.lineWidth = 16;
  }

  vignette(ctx, w, h, 0.82);
}

function stageCarnival(ctx, w, h, t) {
  const sky = ctx.createLinearGradient(0, 0, 0, GROUND);
  sky.addColorStop(0, '#120613');
  sky.addColorStop(0.55, '#2a0b1c');
  sky.addColorStop(1, '#3c1720');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, w, GROUND);

  // distant big top
  const tentX = 640;
  const tentW = 760;
  const tentH = 360;
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(tentX - tentW / 2, GROUND - 60);
  ctx.quadraticCurveTo(tentX - tentW * 0.28, GROUND - tentH * 0.8, tentX, GROUND - tentH);
  ctx.quadraticCurveTo(tentX + tentW * 0.28, GROUND - tentH * 0.8, tentX + tentW / 2, GROUND - 60);
  ctx.closePath();
  ctx.clip();
  for (let i = 0; i < 10; i++) {
    ctx.fillStyle = i % 2 ? '#d9c6ae' : '#8e2632';
    ctx.beginPath();
    ctx.moveTo(tentX, GROUND - tentH);
    ctx.lineTo(tentX - tentW / 2 + i * (tentW / 10), GROUND - 40);
    ctx.lineTo(tentX - tentW / 2 + (i + 1) * (tentW / 10), GROUND - 40);
    ctx.closePath();
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(20,6,12,.5)';
  ctx.fillRect(0, GROUND - 180, w, 180);
  ctx.restore();
  // tent trim
  ctx.strokeStyle = '#e8c24a';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(tentX - tentW / 2, GROUND - 62);
  ctx.quadraticCurveTo(tentX, GROUND - 240, tentX + tentW / 2, GROUND - 62);
  ctx.stroke();
  // flag
  line(ctx, tentX, GROUND - tentH, tentX, GROUND - tentH - 60, '#d9c6ae', 4);
  poly(ctx, [[tentX, GROUND - tentH - 60], [tentX + 50, GROUND - tentH - 45], [tentX, GROUND - tentH - 28]], '#c22c2c');

  // entrance arch
  const archX = 640;
  ctx.fillStyle = '#1c0a10';
  ctx.beginPath();
  ctx.moveTo(archX - 120, GROUND);
  ctx.lineTo(archX - 120, GROUND - 150);
  ctx.quadraticCurveTo(archX, GROUND - 235, archX + 120, GROUND - 150);
  ctx.lineTo(archX + 120, GROUND);
  ctx.closePath();
  ctx.fill();
  // bulbs around arch
  for (let i = 0; i < 14; i++) {
    const a = Math.PI + (i / 13) * Math.PI;
    const bx = archX + Math.cos(a) * 128;
    const by = GROUND - 150 + Math.sin(a) * 120;
    const pulse = 0.55 + Math.sin(t * 3 + i * 0.9) * 0.35;
    ctx.save();
    ctx.shadowColor = '#ffd45c';
    ctx.shadowBlur = 9;
    ell(ctx, bx, by, 4, 4, `rgba(255,212,92,${pulse})`, null);
    ctx.restore();
  }

  // ferris wheel
  const fx = 180;
  const fy = 250;
  const fr = 150;
  ctx.strokeStyle = 'rgba(25,15,25,.85)';
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.arc(fx, fy, fr, 0, TAU);
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(fx, fy, fr - 12, 0, TAU);
  ctx.stroke();
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU + t * 0.05;
    line(ctx, fx, fy, fx + Math.cos(a) * fr, fy + Math.sin(a) * fr, 'rgba(50,35,45,.8)', 2);
    const cx = fx + Math.cos(a) * fr;
    const cy = fy + Math.sin(a) * fr;
    ctx.fillStyle = i % 3 === 0 ? '#7d2c3c' : '#2c2430';
    ctx.fillRect(cx - 9, cy + 3, 18, 14);
    const blink = Math.sin(t * 2 + i) > 0.3;
    if (blink) {
      ctx.fillStyle = 'rgba(255,210,120,.8)';
      ctx.fillRect(cx - 2, cy + 7, 4, 4);
    }
  }
  ell(ctx, fx, fy, 14, 14, '#38283a', '#e8c24a', 2);
  ctx.strokeStyle = '#241a26';
  ctx.lineWidth = 8;
  line(ctx, fx - 60, GROUND, fx, fy, '#241a26', 7);
  line(ctx, fx + 60, GROUND, fx, fy, '#241a26', 7);

  // string lights
  for (let row = 0; row < 2; row++) {
    const y = 70 + row * 48;
    ctx.beginPath();
    ctx.moveTo(0, y + 20);
    for (let i = 0; i <= 8; i++) {
      const px = (i / 8) * w;
      const py = y + Math.sin((i / 8) * Math.PI * 3) * 22;
      ctx.lineTo(px, py);
    }
    ctx.strokeStyle = 'rgba(15,10,15,.8)';
    ctx.lineWidth = 1.6;
    ctx.stroke();
    for (let i = 0; i < 18; i++) {
      const px = (i / 17) * w;
      const py = y + Math.sin((i / 17) * Math.PI * 3) * 22 + 6;
      const colors = ['#ffd45c', '#ff6a6a', '#7dff6a', '#6ac9ff'];
      const pulse = 0.4 + Math.sin(t * 3 + i * 1.7) * 0.3;
      ctx.save();
      ctx.shadowColor = colors[i % 4];
      ctx.shadowBlur = 8;
      ell(ctx, px, py, 3.4, 3.4, `${colors[i % 4]}${Math.round((0.4 + pulse) * 255).toString(16).padStart(2, '0')}`, null);
      ctx.restore();
    }
  }

  // side spotlights
  for (const [sx, dir] of [[-40, 1], [w + 40, -1]]) {
    const g = ctx.createLinearGradient(sx, 80, sx + dir * 500, GROUND);
    g.addColorStop(0, 'rgba(255,220,150,.22)');
    g.addColorStop(1, 'rgba(255,220,150,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(sx, 30);
    ctx.lineTo(sx + dir * 60, 30);
    ctx.lineTo(sx + dir * 620, GROUND);
    ctx.lineTo(sx + dir * 260, GROUND);
    ctx.closePath();
    ctx.fill();
  }

  // ground
  const gg = ctx.createLinearGradient(0, GROUND, 0, h);
  gg.addColorStop(0, '#3a242b');
  gg.addColorStop(1, '#1a1016');
  ctx.fillStyle = gg;
  ctx.fillRect(0, GROUND, w, h - GROUND);
  ctx.fillStyle = 'rgba(30,16,22,.6)';
  for (let i = 0; i < 9; i++) ctx.fillRect(i * 150 - 20, GROUND + 30, 80, 4);
  // sawdust ring
  ctx.strokeStyle = 'rgba(200,160,100,.25)';
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.ellipse(w / 2, GROUND + 74, 430, 60, 0, 0, TAU);
  ctx.stroke();

  // confetti
  for (let i = 0; i < 26; i++) {
    const px = (seeded(i + 20) * w + t * (12 + seeded(i) * 20)) % w;
    const py = (seeded(i + 41) * (h - 100) + t * (20 + seeded(i + 2) * 30)) % (h - 90);
    const a = 0.3 + Math.sin(t * 2 + i) * 0.2;
    ctx.fillStyle = i % 3 === 0 ? `rgba(255,90,90,${a})` : i % 3 === 1 ? `rgba(255,210,80,${a})` : `rgba(120,255,120,${a})`;
    ctx.fillRect(px, py, 3, 6);
  }

  vignette(ctx, w, h, 0.85);
}

function stageThrone(ctx, w, h, t) {
  const bg = ctx.createLinearGradient(0, 0, 0, GROUND);
  bg.addColorStop(0, '#09070c');
  bg.addColorStop(0.5, '#171019');
  bg.addColorStop(1, '#241a20');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, GROUND);

  // giant arched window
  const wx = 640;
  const wy = 360;
  ctx.beginPath();
  ctx.moveTo(wx - 220, GROUND);
  ctx.lineTo(wx - 220, wy - 200);
  ctx.quadraticCurveTo(wx, wy - 380, wx + 220, wy - 200);
  ctx.lineTo(wx + 220, GROUND);
  ctx.closePath();
  const wg = ctx.createLinearGradient(0, 120, 0, GROUND);
  wg.addColorStop(0, '#5c1b2e');
  wg.addColorStop(0.5, '#941f33');
  wg.addColorStop(1, '#3a111d');
  ctx.fillStyle = wg;
  ctx.fill();
  ctx.strokeStyle = '#3a2a30';
  ctx.lineWidth = 14;
  ctx.stroke();
  // window tracery
  ctx.strokeStyle = 'rgba(20,12,18,.8)';
  ctx.lineWidth = 5;
  line(ctx, wx, 160, wx, GROUND, 'rgba(20,12,18,.8)', 5);
  for (let i = 1; i < 4; i++) {
    const yy = 300 + i * 90;
    line(ctx, wx - 215, yy, wx + 215, yy, 'rgba(20,12,18,.55)', 3);
  }
  ctx.beginPath();
  ctx.arc(wx, wy - 170, 90, Math.PI, TAU);
  ctx.strokeStyle = 'rgba(20,12,18,.6)';
  ctx.lineWidth = 4;
  ctx.stroke();
  // moon in window
  ell(ctx, wx + 40, 240, 48, 48, 'rgba(240,220,190,.75)', null);

  // pillars
  for (const px of [80, 1200]) {
    ctx.fillStyle = '#191319';
    ctx.fillRect(px - 70, 0, 140, GROUND);
    const pg = ctx.createLinearGradient(px - 70, 0, px + 70, 0);
    pg.addColorStop(0, 'rgba(255,255,255,.03)');
    pg.addColorStop(0.5, 'rgba(255,255,255,.09)');
    pg.addColorStop(1, 'rgba(0,0,0,.35)');
    ctx.fillStyle = pg;
    ctx.fillRect(px - 70, 0, 140, GROUND);
    ctx.fillStyle = '#221a21';
    ctx.fillRect(px - 90, 0, 180, 36);
    ctx.fillRect(px - 90, GROUND - 52, 180, 52);
    for (let i = 0; i < 4; i++) line(ctx, px - 40 + i * 27, 40, px - 40 + i * 27, GROUND - 60, 'rgba(0,0,0,.35)', 3);
    // candle sconce
    for (const cy of [180, 380]) {
      ctx.fillStyle = '#2a2028';
      ctx.fillRect(px + 70, cy, 22, 8);
      for (let i = 0; i < 2; i++) {
        ctx.fillStyle = '#d9c9a3';
        ctx.fillRect(px + 76 + i * 9, cy - 16, 4, 16);
        const flick = 0.7 + Math.sin(t * 9 + i * 2 + px) * 0.25;
        ell(ctx, px + 78 + i * 9, cy - 21, 3, 6 * flick, 'rgba(255,190,90,.95)', null);
      }
    }
  }

  // throne
  const thx = 640;
  ctx.fillStyle = '#241722';
  ctx.beginPath();
  ctx.moveTo(thx - 100, GROUND - 90);
  ctx.lineTo(thx - 100, GROUND - 300);
  ctx.quadraticCurveTo(thx, GROUND - 420, thx + 100, GROUND - 300);
  ctx.lineTo(thx + 100, GROUND - 90);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#6b4a2a';
  ctx.lineWidth = 6;
  ctx.stroke();
  ctx.fillStyle = '#3d1a26';
  ctx.fillRect(thx - 75, GROUND - 250, 150, 160);
  ctx.fillStyle = '#c9a44a';
  for (let i = 0; i < 5; i++) poly(ctx, [[thx - 70 + i * 35, GROUND - 300], [thx - 55 + i * 35, GROUND - 340], [thx - 40 + i * 35, GROUND - 300]], '#c9a44a');
  // skull on throne
  ell(ctx, thx, GROUND - 316, 20, 22, '#d9d2c0', null);
  ell(ctx, thx - 7, GROUND - 320, 5, 6, '#1a1418', null);
  ell(ctx, thx + 7, GROUND - 320, 5, 6, '#1a1418', null);
  for (let i = 0; i < 4; i++) line(ctx, thx - 8 + i * 5, GROUND - 304, thx - 8 + i * 5, GROUND - 295, '#8a8270', 1.5);

  // banners
  for (const bx of [300, 980]) {
    ctx.fillStyle = 'rgba(110,20,34,.85)';
    ctx.beginPath();
    ctx.moveTo(bx - 55, 30);
    ctx.lineTo(bx + 55, 30);
    ctx.lineTo(bx + 55, 240);
    ctx.lineTo(bx, 270);
    ctx.lineTo(bx - 55, 240);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#c9a44a';
    ctx.lineWidth = 3;
    ctx.stroke();
    // emblem
    ctx.strokeStyle = 'rgba(220,180,100,.55)';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(bx, 140, 34, 0, TAU);
    ctx.stroke();
    line(ctx, bx - 24, 140, bx + 24, 140, 'rgba(220,180,100,.55)', 3);
    line(ctx, bx, 116, bx, 164, 'rgba(220,180,100,.55)', 3);
  }

  // carpet
  ctx.beginPath();
  ctx.moveTo(420, GROUND);
  ctx.lineTo(860, GROUND);
  ctx.lineTo(1010, h);
  ctx.lineTo(270, h);
  ctx.closePath();
  const cg = ctx.createLinearGradient(0, GROUND, 0, h);
  cg.addColorStop(0, '#5c1826');
  cg.addColorStop(1, '#260b12');
  ctx.fillStyle = cg;
  ctx.fill();
  ctx.strokeStyle = '#c9a44a';
  ctx.lineWidth = 3;
  ctx.stroke();
  line(ctx, 440, GROUND + 20, 480, h, 'rgba(220,180,100,.3)', 2);
  line(ctx, 840, GROUND + 20, 800, h, 'rgba(220,180,100,.3)', 2);

  // floor
  ctx.fillStyle = '#140f13';
  ctx fillRect?.(0, 0, 0, 0);
  ctx.fillStyle = '#140f13';
  ctx.fillRect(0, GROUND, w, h - GROUND);
  for (let i = 0; i < 8; i++) {
    line(ctx, 0, GROUND + 18 + i * 18, w, GROUND + 18 + i * 18, 'rgba(255,255,255,.03)', 1);
  }

  // embers
  for (let i = 0; i < 30; i++) {
    const px = (seeded(i + 5) * w + Math.sin(t * 0.7 + i) * 30) % w;
    const py = 720 - ((t * (18 + seeded(i) * 20) + seeded(i + 9) * 720) % 720);
    const a = 0.25 + (Math.sin(t * 3 + i) + 1) * 0.2;
    ell(ctx, px, py, 1.8, 1.8, `rgba(255,150,70,${a})`, null);
  }

  vignette(ctx, w, h, 0.85);
}

function stageInfernal(ctx, w, h, t) {
  const sky = ctx.createLinearGradient(0, 0, 0, GROUND);
  sky.addColorStop(0, '#160609');
  sky.addColorStop(0.45, '#3d0e10');
  sky.addColorStop(0.75, '#7d2214');
  sky.addColorStop(1, '#c04a1c');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, w, GROUND);

  // smoke clouds
  for (let i = 0; i < 7; i++) {
    const cx = (seeded(i) * w + t * (4 + i)) % w;
    const cy = 70 + seeded(i + 4) * 220;
    ctx.fillStyle = `rgba(20,8,9,${0.25 + seeded(i + 8) * 0.2})`;
    ell(ctx, cx, cy, 150, 35, ctx.fillStyle, null);
  }

  // volcano glow
  haze(ctx, 640, 300, 420, 220, 'rgba(255,120,30,.5)', t, 0.8);
  haze(ctx, 250, 330, 260, 200, 'rgba(255,80,20,.3)', t, 0.5);

  // mountains
  const ranges = [
    { color: '#240b0c', y: GROUND - 140, peaks: [[-50, 500], [120, 300], [290, 430], [430, 250], [590, 390], [760, 240], [940, 400], [1090, 260], [1330, 470]] },
    { color: '#170708', y: GROUND - 80, peaks: [[-50, 470], [180, 370], [340, 460], [520, 320], [720, 450], [900, 350], [1080, 450], [1250, 360], [1330, 440]] },
  ];
  for (const r of ranges) {
    ctx.fillStyle = r.color;
    ctx.beginPath();
    ctx.moveTo(-60, GROUND);
    for (const [px, py] of r.peaks) ctx.lineTo(px, r.y - (470 - py));
    ctx.lineTo(1330, GROUND);
    ctx.closePath();
    ctx.fill();
  }

  // lava cracks in mountains
  ctx.strokeStyle = 'rgba(255,120,30,.55)';
  ctx.lineWidth = 3;
  ctx.save();
  ctx.shadowColor = '#ff6a1a';
  ctx.shadowBlur = 10;
  for (let i = 0; i < 5; i++) {
    const bx = 160 + i * 230;
    ctx.beginPath();
    ctx.moveTo(bx, GROUND - 120);
    ctx.lineTo(bx + 30, GROUND - 190);
    ctx.lineTo(bx + 16, GROUND - 240);
    ctx.stroke();
  }
  ctx.restore();

  // giant rock arch
  ctx.fillStyle = '#180909';
  ctx.beginPath();
  ctx.moveTo(-40, GROUND);
  ctx.lineTo(-40, 160);
  ctx.quadraticCurveTo(250, 40, 470, 250);
  ctx.lineTo(430, 430);
  ctx.quadraticCurveTo(250, 260, 80, 340);
  ctx.lineTo(80, GROUND);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(1320, GROUND);
  ctx.lineTo(1320, 140);
  ctx.quadraticCurveTo(1050, 40, 820, 260);
  ctx.lineTo(860, 440);
  ctx.quadraticCurveTo(1060, 270, 1230, 350);
  ctx.lineTo(1230, GROUND);
  ctx.closePath();
  ctx.fill();

  // lava river
  const lavaY = GROUND - 48;
  const lg = ctx.createLinearGradient(0, lavaY, 0, lavaY + 48);
  lg.addColorStop(0, '#ffb03a');
  lg.addColorStop(0.4, '#e2571a');
  lg.addColorStop(1, '#7d1f0e');
  ctx.fillStyle = lg;
  ctx.fillRect(0, lavaY, w, 46);
  ctx.save();
  ctx.shadowColor = '#ff7a20';
  ctx.shadowBlur = 30;
  ctx.fillStyle = 'rgba(255,140,40,.5)';
  ctx.fillRect(0, lavaY - 6, w, 8);
  ctx.restore();
  // lava highlights
  for (let i = 0; i < 14; i++) {
    const lx = (seeded(i) * w + t * 14) % w;
    ell(ctx, lx, lavaY + 12 + seeded(i + 1) * 24, 20 + seeded(i + 2) * 40, 3, 'rgba(255,220,130,.5)', null);
  }

  // ground
  ctx.fillStyle = '#1a0b0a';
  ctx.fillRect(0, GROUND, w, h - GROUND);
  ctx.fillStyle = '#24100d';
  ctx.beginPath();
  ctx.moveTo(0, GROUND);
  for (let i = 0; i <= 12; i++) {
    ctx.lineTo(i * 116, GROUND + Math.sin(i * 1.7) * 4);
  }
  ctx.lineTo(w, GROUND + 26);
  ctx.lineTo(0, GROUND + 26);
  ctx.closePath();
  ctx.fill();
  // glowing cracks
  ctx.save();
  ctx.shadowColor = '#ff6a1a';
  ctx.shadowBlur = 12;
  ctx.strokeStyle = 'rgba(255,110,30,.7)';
  ctx.lineWidth = 2.4;
  for (let i = 0; i < 7; i++) {
    const cx = 100 + i * 170;
    ctx.beginPath();
    ctx.moveTo(cx, GROUND + 6);
    ctx.lineTo(cx + 18, GROUND + 30);
    ctx.lineTo(cx + 6, GROUND + 48);
    ctx.lineTo(cx + 30, GROUND + 80);
    ctx.stroke();
  }
  ctx.restore();

  // stalagmites / rocks
  for (const [rx, rw, rh] of [[120, 60, 100], [1120, 72, 130], [310, 30, 60], [980, 34, 70]]) {
    poly(ctx, [[rx - rw / 2, GROUND], [rx - rw * 0.2, GROUND - rh], [rx + rw * 0.15, GROUND - rh * 0.8], [rx + rw / 2, GROUND]], '#170a09', '#0c0505', 2);
  }

  // skulls
  for (const [sx, sy, ss] of [[430, GROUND + 44, 1], [860, GROUND + 62, 1.2], [250, GROUND + 78, 0.8]]) {
    ell(ctx, sx, sy, 13 * ss, 11 * ss, '#c9bda1', null);
    ell(ctx, sx - 5 * ss, sy - 2 * ss, 3 * ss, 3 * ss, '#1a0f0d', null);
    ell(ctx, sx + 5 * ss, sy - 2 * ss, 3 * ss, 3 * ss, '#1a0f0d', null);
    line(ctx, sx - 4 * ss, sy + 5 * ss, sx + 4 * ss, sy + 5 * ss, '#6b5f4a', 1.5);
  }

  // chains hanging
  ctx.strokeStyle = 'rgba(25,15,14,.9)';
  ctx.lineWidth = 3;
  for (const cx of [520, 800]) {
    for (let i = 0; i < 6; i++) {
      ctx.beginPath();
      ctx.arc(cx + Math.sin(i * 1.7) * 3, i * 18, 5, 0, TAU);
      ctx.stroke();
    }
  }

  // embers
  for (let i = 0; i < 42; i++) {
    const px = (seeded(i + 3) * w + Math.sin(t * 0.6 + i) * 26) % w;
    const py = 720 - ((t * (24 + seeded(i) * 34) + seeded(i + 7) * 720) % 760);
    const a = 0.3 + (Math.sin(t * 3.4 + i) + 1) * 0.25;
    ell(ctx, px, py, 1.4 + seeded(i + 2) * 1.8, 1.4 + seeded(i + 2) * 1.8, `rgba(255,${120 + (i % 5) * 15},50,${a})`, null);
  }

  vignette(ctx, w, h, 0.88);
}

export function drawStage(ctx, id, w, h, time) {
  ctx.save();
  if (id === 'carnival') stageCarnival(ctx, w, h, time);
  else if (id === 'throne') stageThrone(ctx, w, h, time);
  else if (id === 'infernal') stageInfernal(ctx, w, h, time);
  else stageHaddonfield(ctx, w, h, time);
  ctx.restore();
}

export function drawTitleBackdrop(ctx, w, h, time) {
  drawStage(ctx, 'haddonfield', w, h, time);
  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, 'rgba(5,4,8,.55)');
  g.addColorStop(0.55, 'rgba(5,4,8,.72)');
  g.addColorStop(1, 'rgba(5,4,8,.9)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
}

export const GROUND_Y = GROUND;

