// Character portrait rendering for the roster, HUD and result screens.
import { drawFighter, drawFighterShadow } from './art.js';
import { ell } from './draw-utils.js';

const cache = new Map();

export function makeCharacterCanvas(char, w = 300, h = 360, opts = {}) {
  const key = `${char.id}:${w}x${h}:${opts.pose || 'preview'}:${opts.dpr || 2}:${opts.bg ? 'bg' : ''}`;
  if (!opts.time && cache.has(key)) return cache.get(key);

  const dpr = opts.dpr ?? 2;
  const cv = document.createElement('canvas');
  cv.width = Math.round(w * dpr);
  cv.height = Math.round(h * dpr);
  const ctx = cv.getContext('2d');
  ctx.scale(dpr, dpr);

  if (opts.bg) {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, opts.bg[0]);
    g.addColorStop(1, opts.bg[1]);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    const r = ctx.createRadialGradient(w / 2, h * 0.58, 10, w / 2, h * 0.6, w * 0.72);
    r.addColorStop(0, 'rgba(255,255,255,.08)');
    r.addColorStop(1, 'rgba(0,0,0,.25)');
    ctx.fillStyle = r;
    ctx.fillRect(0, 0, w, h);
  }

  const bodyH = 215;
  const scale = (h * 0.9) / (bodyH * (char.scale || 1));
  ctx.save();
  ctx.translate(w / 2, h * 0.94);
  drawFighterShadow(ctx, char, 0, 0, scale, 0.5);
  drawFighter(ctx, char, {
    x: 0, y: 0, facing: 1, pose: opts.pose || 'preview',
    time: opts.time || 0, scale, alpha: 1,
  });
  ctx.restore();

  if (!opts.time) cache.set(key, cv);
  return cv;
}

// Close-up cropped avatar for the in-game HUD.
export function makeHudAvatar(char, w = 150, h = 170) {
  const key = `hud:${char.id}:${w}x${h}`;
  if (cache.has(key)) return cache.get(key);
  const full = makeCharacterCanvas(char, 240, 300, { dpr: 1, pose: 'preview' });
  const cv = document.createElement('canvas');
  cv.width = w * 2;
  cv.height = h * 2;
  const ctx = cv.getContext('2d');
  ctx.imageSmoothingQuality = 'high';
  // crop the top of the full-body render (head and torso)
  const sx = 42;
  const sy = 12;
  const sw = 156;
  const sh = 176;
  ctx.drawImage(full, sx, sy, sw, sh, 0, 0, w * 2, h * 2);
  cache.set(key, cv);
  return cv;
}

export function makeStageChip(stage, w = 150, h = 54) {
  const cv = document.createElement('canvas');
  cv.width = w * 2;
  cv.height = h * 2;
  const ctx = cv.getContext('2d');
  ctx.scale(2, 2);
  const cols = {
    haddonfield: ['#101d36', '#3a4552'],
    carnival: ['#2a0b1c', '#3c1720'],
    throne: ['#171019', '#241a20'],
    infernal: ['#3d0e10', '#c04a1c'],
  }[stage.id];
  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, cols[0]);
  g.addColorStop(1, cols[1]);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  const accent = { haddonfield: '#9fb6d8', carnival: '#ffd45c', throne: '#d94a5c', infernal: '#ff8a2a' }[stage.id];
  for (let i = 0; i < 12; i++) {
    ctx.fillStyle = `${accent}${i % 2 ? '22' : '11'}`;
    ctx.fillRect(0, 10 + i * 4, w, 1);
  }
  ell(ctx, w * 0.8, 16, 7, 7, `${accent}99`, null);
  return cv;
}

// In-canvas fighting HUD and announcements.
import { TAU, rr, ell, line, poly, dark } from './draw-utils.js';

function font(size, weight = 900) {
  return `${weight} ${size}px Impact, "Arial Black", "Franklin Gothic Heavy", sans-serif`;
}

function txt(ctx, text, x, y, size, o = {}) {
  const { align = 'left', color = '#f5efe2', stroke = '#0a0709', lw = 7, weight = 900, alpha = 1 } = o;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.font = font(size, weight);
  ctx.textAlign = align;
  ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round';
  if (lw > 0) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.strokeText(text, x, y);
  }
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function skewBarPath(ctx, x, y, w, h, mirror) {
  const s = 9;
  ctx.beginPath();
  if (!mirror) {
    ctx.moveTo(x + s, y);
    ctx.lineTo(x + w, y);
    ctx.lineTo(x + w - s, y + h);
    ctx.lineTo(x, y + h);
  } else {
    ctx.moveTo(x, y);
    ctx.lineTo(x + w - s, y);
    ctx.lineTo(x + w, y + h);
    ctx.lineTo(x + s, y + h);
  }
  ctx.closePath();
}

function bar(ctx, x, y, w, h, ratio, ghost, mirror, color, accent) {
  const r = Math.max(0, Math.min(1, ratio));
  const g = Math.max(0, Math.min(1, ghost));
  skewBarPath(ctx, x, y, w, h, mirror);
  ctx.fillStyle = 'rgba(8,6,9,.9)';
  ctx.fill();
  ctx.save();
  skewBarPath(ctx, x, y, w, h, mirror);
  ctx.clip();
  if (g > r) {
    if (!mirror) ctx.fillStyle = 'rgba(255,205,80,.55)';
    else ctx.fillStyle = 'rgba(255,205,80,.55)';
    if (!mirror) ctx.fillRect(x, y, w * g, h);
    else ctx.fillRect(x + w * (1 - g), y, w * g, h);
  }
  if (!mirror) ctx.fillStyle = color;
  else ctx.fillStyle = color;
  if (!mirror) {
    const grad = ctx.createLinearGradient(x, y, x, y + h);
    grad.addColorStop(0, accent || color);
    grad.addColorStop(1, color);
    ctx.fillStyle = grad;
    ctx.fillRect(x, y, w * r, h);
  } else {
    const grad = ctx.createLinearGradient(x + w, y, x + w, y + h);
    grad.addColorStop(0, accent || color);
    grad.addColorStop(1, color);
    ctx.fillStyle = grad;
    ctx.fillRect(x + w * (1 - r), y, w * r, h);
  }
  // shine
  ctx.fillStyle = 'rgba(255,255,255,.22)';
  if (!mirror) ctx.fillRect(x, y + 2, w * r, 3);
  else ctx.fillRect(x + w * (1 - r), y + 2, w * r, 3);
  ctx.restore();
  skewBarPath(ctx, x, y, w, h, mirror);
  ctx.strokeStyle = 'rgba(240,230,210,.28)';
  ctx.lineWidth = 1.4;
  ctx.stroke();
}

function portrait(ctx, cv, x, y, w, h, mirror) {
  ctx.save();
  ctx.translate(x + w / 2, y + h / 2);
  if (mirror) ctx.scale(-1, 1);
  ctx.translate(-w / 2, -h / 2);
  rr(ctx, 0, 0, w, h, 5);
  ctx.fillStyle = '#171217';
  ctx.fill();
  ctx.save();
  rr(ctx, 0, 0, w, h, 5);
  ctx.clip();
  ctx.globalAlpha = 0.96;
  ctx.drawImage(cv, 0, 0, w, h);
  const g = ctx.createLinearGradient(0, h * 0.5, 0, h);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  ctx.restore();
  rr(ctx, 0.5, 0.5, w - 1, h - 1, 5);
  ctx.strokeStyle = '#5a4a3c';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.restore();
}

function pips(ctx, x, y, wins, mirror) {
  for (let i = 0; i < 2; i++) {
    const px = x + (mirror ? -1 : 1) * i * 17;
    ctx.save();
    ctx.translate(px, y);
    ctx.rotate(Math.PI / 4);
    ctx.fillStyle = i < wins ? '#ffd447' : 'rgba(255,255,255,.14)';
    if (i < wins) {
      ctx.shadowColor = '#ffd447';
      ctx.shadowBlur = 8;
    }
    ctx.fillRect(-5, -5, 10, 10);
    ctx.strokeStyle = i < wins ? '#fff2b0' : 'rgba(255,255,255,.25)';
    ctx.lineWidth = 1;
    ctx.strokeRect(-5, -5, 10, 10);
    ctx.restore();
  }
}

function meterBar(ctx, f, x, y, w, mirror) {
  const ratio = f.meter / 100;
  const ready = f.meter >= 50;
  const h = 9;
  skewBarPath(ctx, x, y, w, h, mirror);
  ctx.fillStyle = 'rgba(8,6,9,.85)';
  ctx.fill();
  ctx.save();
  skewBarPath(ctx, x, y, w, h, mirror);
  ctx.clip();
  const grad = ctx.createLinearGradient(x, y, x + w, y);
  if (ready) {
    grad.addColorStop(0, '#fff08a');
    grad.addColorStop(1, '#ffb02a');
  } else {
    grad.addColorStop(0, '#4a86c9');
    grad.addColorStop(1, '#6ac9ff');
  }
  ctx.fillStyle = grad;
  if (!mirror) ctx.fillRect(x, y, w * ratio, h);
  else ctx.fillRect(x + w * (1 - ratio), y, w * ratio, h);
  // cost notch at 50%
  ctx.fillStyle = 'rgba(0,0,0,.55)';
  ctx.fillRect(x + w * 0.5, y, 2, h);
  ctx.restore();
  skewBarPath(ctx, x, y, w, h, mirror);
  ctx.strokeStyle = ready ? 'rgba(255,220,90,.75)' : 'rgba(240,230,210,.2)';
  ctx.lineWidth = 1;
  ctx.stroke();
  if (ready) {
    const pulse = 0.6 + Math.sin(performance.now() / 240) * 0.3;
    ctx.save();
    ctx.globalAlpha = pulse;
    ctx.shadowColor = '#ffd447';
    ctx.shadowBlur = 8;
    txt(ctx, ratio >= 1 ? 'SPECIAL READY!' : 'SPECIAL', mirror ? x - 8 : x + w + 10, y + 9, 12, {
      align: mirror ? 'right' : 'left', color: '#ffd447', lw: 4,
    });
    ctx.restore();
  } else {
    txt(ctx, 'SPECIAL', mirror ? x - 8 : x + w + 10, y + 9, 11, {
      align: mirror ? 'right' : 'left', color: 'rgba(220,214,200,.4)', lw: 3,
    });
  }
}

function timerPlate(ctx, timeLeft) {
  ctx.save();
  ctx.translate(640, 78);
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = -Math.PI / 2 + (i / 6) * TAU;
    const px = Math.cos(a) * 62;
    const py = Math.sin(a) * 44;
    i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
  }
  ctx.closePath();
  const g = ctx.createLinearGradient(0, -44, 0, 44);
  g.addColorStop(0, '#2a1e20');
  g.addColorStop(1, '#120c0e');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = '#6b4a2a';
  ctx.lineWidth = 2.5;
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,205,90,.35)';
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.restore();

  const t = Math.max(0, Math.ceil(timeLeft));
  const low = t <= 10;
  txt(ctx, String(t).padStart(2, '0'), 640, 96, 50, {
    align: 'center', color: low ? '#ff4a3a' : '#f6efdd', lw: 6,
  });
  txt(ctx, 'TIME', 640, 112, 10, {
    align: 'center', color: low ? '#ff9a8a' : 'rgba(230,220,200,.55)', lw: 2,
  });
}

export function drawHud(ctx, game) {
  const w = game.w;
  const h = game.h;
  const [a, b] = game.fighters;
  const aw = game.avatars[0];
  const bw = game.avatars[1];

  // top gradient
  const g = ctx.createLinearGradient(0, 0, 0, 160);
  g.addColorStop(0, 'rgba(6,4,7,.92)');
  g.addColorStop(0.7, 'rgba(6,4,7,.62)');
  g.addColorStop(1, 'rgba(6,4,7,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, 178);

  // portrait plates
  portrait(ctx, aw, 26, 22, 72, 84, false);
  portrait(ctx, bw, w - 98, 22, 72, 84, true);

  // P1 name
  const aName = a.char.name;
  const bName = b.char.name;
  const aSize = aName.length > 15 ? 22 : aName.length > 12 ? 26 : 30;
  const bSize = bName.length > 15 ? 22 : bName.length > 12 ? 26 : 30;
  txt(ctx, aName, 112, 47, aSize, { color: '#f6efdd', lw: 6 });
  txt(ctx, bName, w - 112, 47, bSize, { align: 'right', color: '#f6efdd', lw: 6 });

  // health
  const p1Low = a.hp <= 30;
  const p2Low = b.hp <= 30;
  bar(ctx, 112, 56, 442, 27, a.hp / 100, a.displayHp / 100, false, p1Low ? '#e12828' : '#b8e64a', p1Low ? '#ff6a4a' : '#ecff8a');
  bar(ctx, w - 112 - 442, 56, 442, 27, b.hp / 100, b.displayHp / 100, true, p2Low ? '#e12828' : '#b8e64a', p2Low ? '#ff6a4a' : '#ecff8a');

  // pips + round text
  pips(ctx, 508, 108, game.wins[0], false);
  pips(ctx, w - 508, 108, game.wins[1], true);
  txt(ctx, `ROUND ${game.round}`, 640, 141, 13, { align: 'center', color: 'rgba(235,225,205,.5)', lw: 3 });
  txt(ctx, 'BEST OF 3', 640, 155, 9, { align: 'center', color: 'rgba(235,225,205,.26)', lw: 2 });

  meterBar(ctx, a, 112, 92, 312, false);
  meterBar(ctx, b, w - 112 - 312, 92, 312, true);

  timerPlate(ctx, game.roundTime);

  // stage label
  txt(ctx, game.stage.name, 22, h - 12, 12, { color: 'rgba(240,230,210,.32)', lw: 3 });
  txt(ctx, 'VILLAINS: RUMBLE', w - 22, h - 12, 12, { align: 'right', color: 'rgba(240,230,210,.2)', lw: 3 });

  // combo counters
  for (let i = 0; i < 2; i++) {
    const f = game.fighters[i];
    if (f.combo >= 2 && f.comboTimer > 0) {
      const x = i === 0 ? 250 : w - 250;
      const align = i === 0 ? 'left' : 'right';
      const bounce = 1 + Math.min(0.25, f.comboTimer * 0.02);
      ctx.save();
      ctx.translate(x, 200);
      ctx.scale(bounce, bounce);
      txt(ctx, `${f.combo} HIT`, 0, 0, 40, { align, color: '#ffd447', lw: 7 });
      txt(ctx, 'COMBO', 0, 22, 15, { align, color: '#f6efdd', lw: 4 });
      ctx.restore();
    }
  }

  // control hint during opening seconds
  if (game.phase === 'fight' && game.time < 9 && game.mode !== 'local') {
    const alpha = Math.min(1, Math.max(0, (9 - game.time) / 2)) * 0.5;
    txt(ctx, 'A / D  MOVE      W  JUMP      S  BLOCK      J  PUNCH      K  KICK      L  SPECIAL', 640, 696, 14, {
      align: 'center', color: '#e8dfcc', lw: 3, alpha,
    });
    txt(ctx, 'GET CLOSE. HIT HARD. DON’T GET GROUNDED.', 640, 676, 10, {
      align: 'center', color: '#ffd447', lw: 2, alpha: alpha * 0.8,
    });
  } else if (game.mode === 'local' && game.phase === 'fight' && game.time < 9) {
    const alpha = Math.min(1, Math.max(0, (9 - game.time) / 2)) * 0.5;
    txt(ctx, 'P1: A/D MOVE · W JUMP · S BLOCK · J/K/L ATTACK', 640, 688, 13, {
      align: 'center', color: '#e8dfcc', lw: 3, alpha,
    });
    txt(ctx, 'P2: ARROWS MOVE · UP JUMP · DOWN BLOCK · , . / ATTACK', 640, 704, 12, {
      align: 'center', color: '#ffd447', lw: 3, alpha,
    });
  }

  // low health warning tint
  const low = Math.min(a.hp, b.hp);
  if (low <= 25 && game.phase !== 'intro') {
    const pulse = 0.16 + Math.sin(game.time * 6) * 0.06;
    const vg = ctx.createRadialGradient(w / 2, h / 2, h * 0.32, w / 2, h / 2, h * 0.8);
    vg.addColorStop(0, 'rgba(120,0,0,0)');
    vg.addColorStop(1, `rgba(150,0,0,${pulse})`);
    ctx.fillStyle = vg;
    ctx.fillRect(0, 0, w, h);
  }

  drawAnnouncement(ctx, game);
}

export function drawAnnouncement(ctx, game) {
  const a = game.announcement;
  if (!a) return;
  const p = a.t / a.dur;
  if (p >= 1) return;
  const pop = p < 0.16 ? 0.55 + (p / 0.16) * 0.55 : 1 + Math.sin(Math.min(1, (p - 0.16) / 0.3) * Math.PI) * 0.05;
  const fade = p > 0.82 ? 1 - (p - 0.82) / 0.18 : 1;
  const styles = {
    fight: { color: '#ff3b2e', size: 120, sub: '#ffd447' },
    ko: { color: '#ff1e14', size: 158, sub: '#f6efdd' },
    round: { color: '#ffd447', size: 92, sub: '#f6efdd' },
    time: { color: '#ffd447', size: 108, sub: '#f6efdd' },
    win: { color: '#b8ff6a', size: 92, sub: '#f6efdd' },
    draw: { color: '#c9c4b8', size: 106, sub: '#f6efdd' },
    default: { color: '#f6efdd', size: 92, sub: '#ffd447' },
  };
  const st = styles[a.style] || styles.default;

  // band behind big callouts
  if (a.style === 'fight' || a.style === 'ko' || a.style === 'time') {
    ctx.save();
    ctx.globalAlpha = fade * 0.6;
    const g = ctx.createLinearGradient(0, 250, 0, 390);
    g.addColorStop(0, 'rgba(8,4,6,0)');
    g.addColorStop(0.2, 'rgba(8,4,6,.78)');
    g.addColorStop(0.8, 'rgba(8,4,6,.78)');
    g.addColorStop(1, 'rgba(8,4,6,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 250, game.w, 150);
    ctx.strokeStyle = a.style === 'ko' ? 'rgba(225,40,40,.55)' : 'rgba(255,212,71,.35)';
    ctx.lineWidth = 2;
    line(ctx, 0, 300, game.w, 300, ctx.strokeStyle, 2);
    line(ctx, 0, 390, game.w, 390, ctx.strokeStyle, 2);
    ctx.restore();
  }

  ctx.save();
  ctx.globalAlpha = fade;
  ctx.translate(game.w / 2, a.style === 'ko' ? 342 : 340);
  ctx.scale(pop, pop);
  ctx.rotate(-0.025);
  const grad = ctx.createLinearGradient(0, -st.size / 2, 0, st.size / 2);
  grad.addColorStop(0, '#fff7df');
  grad.addColorStop(0.42, st.color);
  grad.addColorStop(1, dark(st.color, 0.18));
  txt(ctx, a.text, 0, 0, st.size, { align: 'center', color: st.color, lw: 13, stroke: '#080507' });
  // colored inner highlight
  ctx.save();
  ctx.globalAlpha *= 0.85;
  ctx.font = font(st.size);
  ctx.textAlign = 'center';
  ctx.fillStyle = grad;
  ctx.fillText(a.text, 0, 0);
  ctx.restore();
  if (a.sub) {
    txt(ctx, a.sub, 0, st.size * 0.55 + 18, 24, { align: 'center', color: st.sub, lw: 5 });
  }
  ctx.restore();
}

export function drawVignette(ctx, w, h) {
  const g = ctx.createRadialGradient(w / 2, h * 0.5, h * 0.3, w / 2, h * 0.5, h * 0.85);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.8, 'rgba(0,0,0,.18)');
  g.addColorStop(1, 'rgba(0,0,0,.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
}

// Tiny WebAudio synthesizer for hits, UI and a grim little battle loop.
let ctx = null;
let master = null;
let sfx = null;
let music = null;
let noiseBuf = null;
let enabled = true;
let musicOn = false;
let musicTimer = null;
let step = 0;
let drone = null;

function makeNoise() {
  const len = ctx.sampleRate * 1.2;
  const b = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = b.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
  return b;
}

function init() {
  if (ctx) {
    if (ctx.state === 'suspended') ctx.resume();
    return;
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return;
  ctx = new AC();
  master = ctx.createGain();
  master.gain.value = enabled ? 0.9 : 0;
  master.connect(ctx.destination);
  sfx = ctx.createGain();
  sfx.gain.value = 0.55;
  sfx.connect(master);
  music = ctx.createGain();
  music.gain.value = 0.3;
  music.connect(master);
  noiseBuf = makeNoise();
}

function env(node, gain, a, d, peak = 1) {
  const t = ctx.currentTime;
  gain.gain.setValueAtTime(0.0001, t);
  gain.gain.linearRampToValueAtTime(peak, t + a);
  gain.gain.exponentialRampToValueAtTime(0.0001, t + a + d);
  node.start(t);
  node.stop(t + a + d + 0.02);
}

function noise(dur = 0.16, freq = 1800, q = 1, vol = 0.5, type = 'lowpass') {
  if (!ctx) return;
  const src = ctx.createBufferSource();
  src.buffer = noiseBuf;
  const f = ctx.createBiquadFilter();
  f.type = type;
  f.frequency.value = freq;
  f.Q.value = q;
  const g = ctx.createGain();
  src.connect(f).connect(g).connect(sfx);
  env(src, g, 0.003, dur, vol);
}

function tone(freq, dur, type = 'sine', vol = 0.3, slide = 0, delay = 0) {
  if (!ctx) return;
  const o = ctx.createOscillator();
  const g = ctx.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, ctx.currentTime + delay);
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), ctx.currentTime + delay + dur);
  o.connect(g).connect(sfx);
  const t = ctx.currentTime + delay;
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(vol, t + 0.006);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.start(t);
  o.stop(t + dur + 0.02);
}

export const sound = {
  init,
  get ready() { return !!ctx; },
  setEnabled(v) {
    enabled = v;
    if (master) master.gain.value = v ? 0.9 : 0;
  },
  get enabled() { return enabled; },
  toggle() {
    this.setEnabled(!enabled);
    return enabled;
  },
  play(name) {
    if (!ctx || !enabled) return;
    switch (name) {
      case 'hit':
        noise(0.12, 900, 0.8, 0.7);
        tone(150, 0.16, 'sine', 0.5, -95);
        break;
      case 'heavy':
        noise(0.22, 500, 0.7, 0.85);
        tone(95, 0.3, 'sine', 0.8, -55);
        tone(60, 0.35, 'triangle', 0.35, -20);
        break;
      case 'block':
        noise(0.07, 3200, 2, 0.35, 'bandpass');
        tone(880, 0.09, 'square', 0.12, -260);
        break;
      case 'swing':
        noise(0.12, 1500, 1.2, 0.25, 'bandpass');
        break;
      case 'special':
        tone(90, 0.5, 'sawtooth', 0.22, 320);
        noise(0.4, 2000, 0.7, 0.3, 'bandpass');
        break;
      case 'beam':
        tone(500, 0.5, 'sawtooth', 0.15, -380);
        noise(0.5, 2600, 1.4, 0.3, 'bandpass');
        break;
      case 'ko':
        noise(0.55, 320, 0.6, 0.9);
        tone(80, 0.7, 'sine', 0.8, -50);
        tone(160, 0.5, 'sawtooth', 0.15, -120);
        break;
      case 'bell':
        tone(220, 0.5, 'sine', 0.3);
        tone(440, 0.45, 'sine', 0.18);
        tone(660, 0.35, 'sine', 0.09);
        break;
      case 'select':
        tone(520, 0.07, 'square', 0.1, 120);
        break;
      case 'back':
        tone(320, 0.08, 'square', 0.08, -100);
        break;
      case 'win':
        [261, 329, 392, 523].forEach((f, i) => tone(f, 0.5, 'triangle', 0.15, 0, i * 0.11));
        break;
      case 'lose':
        tone(180, 0.4, 'sawtooth', 0.1, -60);
        break;
      default:
        break;
    }
  },
  startMusic() {
    if (!ctx || musicOn) return;
    musicOn = true;
    step = 0;
    // dark drone bed
    const o1 = ctx.createOscillator();
    const o2 = ctx.createOscillator();
    const g = ctx.createGain();
    const f = ctx.createBiquadFilter();
    o1.type = 'sawtooth';
    o2.type = 'sawtooth';
    o1.frequency.value = 55;
    o2.frequency.value = 55.6;
    f.type = 'lowpass';
    f.frequency.value = 150;
    g.gain.value = 0.0001;
    g.gain.linearRampToValueAtTime(0.05, ctx.currentTime + 2);
    o1.connect(f);
    o2.connect(f);
    f.connect(g).connect(music);
    o1.start();
    o2.start();
    drone = { o1, o2, g };
    const pattern = [55, 55, 65.41, 49, 55, 73.42, 65.41, 49];
    const ticks = 0.32;
    musicTimer = setInterval(() => {
      if (!musicOn || !ctx) return;
      const t = ctx.currentTime + 0.05;
      const base = pattern[step % pattern.length];
      const o = ctx.createOscillator();
      const gg = ctx.createGain();
      const ff = ctx.createBiquadFilter();
      o.type = 'triangle';
      o.frequency.value = base * 2;
      ff.type = 'lowpass';
      ff.frequency.value = 280;
      o.connect(ff).connect(gg).connect(music);
      gg.gain.setValueAtTime(0.0001, t);
      gg.gain.linearRampToValueAtTime(0.14, t + 0.008);
      gg.gain.exponentialRampToValueAtTime(0.0001, t + 0.28);
      o.start(t);
      o.stop(t + 0.3);
      if (step % 4 === 0) {
        const k = ctx.createOscillator();
        const kg = ctx.createGain();
        k.type = 'sine';
        k.frequency.setValueAtTime(110, t);
        k.frequency.exponentialRampToValueAtTime(45, t + 0.16);
        k.connect(kg).connect(music);
        kg.gain.setValueAtTime(0.0001, t);
        kg.gain.linearRampToValueAtTime(0.22, t + 0.006);
        kg.gain.exponentialRampToValueAtTime(0.0001, t + 0.2);
        k.start(t);
        k.stop(t + 0.22);
      }
      if (step % 2 === 1) {
        const h = ctx.createBufferSource();
        h.buffer = noiseBuf;
        const hg = ctx.createGain();
        const hf = ctx.createBiquadFilter();
        hf.type = 'highpass';
        hf.frequency.value = 5000;
        h.connect(hf).connect(hg).connect(music);
        hg.gain.setValueAtTime(0.0001, t);
        hg.gain.linearRampToValueAtTime(0.035, t + 0.005);
        hg.gain.exponentialRampToValueAtTime(0.0001, t + 0.05);
        h.start(t);
        h.stop(t + 0.06);
      }
      step++;
    }, ticks * 1000);
  },
  stopMusic() {
    musicOn = false;
    if (musicTimer) clearInterval(musicTimer);
    musicTimer = null;
    if (drone) {
      try {
        drone.g.gain.cancelScheduledValues(ctx.currentTime);
        drone.g.gain.setTargetAtTime(0.0001, ctx.currentTime, 0.2);
        drone.o1.stop(ctx.currentTime + 0.8);
        drone.o2.stop(ctx.currentTime + 0.8);
      } catch (e) { /* already stopped */ }
      drone = null;
    }
  },
};

// Hit sparks, projectiles, beams and shockwaves.
import { TAU, ell, line, poly, dark } from './draw-utils.js';

function lookFor(char) {
  if (char.id === 'vader') return 'wave';
  if (char.id === 'bowser' || char.id === 'elmer') return 'fire';
  if (char.id === 'pennywise') return 'balloon';
  if (char.id === 'pinhead') return 'chain';
  if (char.id === 'dracula') return 'bats';
  if (['jafar', 'lilith', 'killjoy'].includes(char.id)) return 'magic';
  return 'orb';
}

export function spawnProjectile(game, ownerIndex) {
  const f = game.fighters[ownerIndex];
  const c = f.char;
  const color = c.special.color;
  const scale = c.scale;
  const p = {
    owner: ownerIndex,
    x: f.x + f.facing * (42 * scale + 10),
    y: f.y - 112 * scale,
    vx: f.facing * (540 + c.stats.speed * 26),
    r: 16 + c.stats.power * 1.8,
    color,
    look: lookFor(c),
    life: 1.7,
    damage: 15 * f.powerFactor,
    trail: 0,
  };
  game.projectiles.push(p);
  game.shake(3, 0.12);
  game.sound.play('special');
  game.burst(p.x, p.y, color, 14, 3);
  game.flash(color, 0.1);
}

export function spawnBeam(game, ownerIndex) {
  const f = game.fighters[ownerIndex];
  const c = f.char;
  const scale = c.scale;
  const isEye = c.id === 'cyclops' || c.id === 'bill';
  const origin = {
    x: f.x + f.facing * (isEye ? 16 : 34) * scale,
    y: f.y - (isEye ? 138 : 96) * scale,
  };
  const beam = {
    owner: ownerIndex,
    x: origin.x,
    y: origin.y,
    dir: f.facing,
    len: 900,
    color: c.special.color,
    t: 0,
    dur: 0.42,
    thick: c.id === 'cyclops' ? 16 : 9,
  };
  game.beams.push(beam);
  // immediate damage check
  const d = game.fighters[1 - ownerIndex];
  if (!d.ko) {
    const horizontal = (d.x - origin.x) * f.facing;
    const vertical = Math.abs((d.y - 90 * d.char.scale) - origin.y);
    if (horizontal > 0 && horizontal < 900 && vertical < 95 * d.char.scale) {
      game.hitFighter(ownerIndex, 1 - ownerIndex, {
        damage: 17 * f.powerFactor,
        knockback: 420,
        vy: -160,
        hitstun: 0.5,
        type: 'special',
        contact: { x: d.x, y: origin.y },
        color: c.special.color,
      });
    }
  }
  game.sound.play('beam');
  game.shake(10, 0.3);
  game.flash(c.special.color, 0.24);
  for (let i = 0; i < 24; i++) {
    game.burst(origin.x + f.facing * (40 + i * 30), origin.y + (Math.random() - 0.5) * 40, c.special.color, 2, 2);
  }
}

export function spawnShockwave(game, ownerIndex) {
  const f = game.fighters[ownerIndex];
  const c = f.char;
  const big = c.id === 'thanos';
  const maxR = big ? 290 : 190 + f.char.fat * 60;
  game.waves.push({
    owner: ownerIndex, x: f.x, t: 0, dur: 0.75, maxR,
    color: c.special.color,
  });
  const d = game.fighters[1 - ownerIndex];
  if (!d.ko) {
    const dist = Math.abs(d.x - f.x);
    if (dist < maxR + 20 && d.y > -120) {
      game.hitFighter(ownerIndex, 1 - ownerIndex, {
        damage: (big ? 20 : 16) * f.powerFactor,
        knockback: 380 + (maxR - 190),
        vy: -360,
        hitstun: 0.6,
        type: 'special',
        contact: { x: d.x, y: d.y - 40 },
        color: c.special.color,
      });
    }
  }
  game.sound.play('heavy');
  game.shake(big ? 22 : 14, 0.4);
  game.flash(c.special.color, big ? 0.22 : 0.14);
  game.burst(f.x, f.y - 20, c.special.color, 30, 7, 'dust');
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * TAU;
    game.particles.push({
      x: f.x + Math.cos(a) * 14, y: f.y - 8 + Math.sin(a) * 8,
      vx: Math.cos(a) * (120 + Math.random() * 140), vy: -Math.random() * 220 - 40,
      life: 0.7, maxLife: 0.7, size: 3 + Math.random() * 5, color: c.special.color,
      grav: 900, additive: true, shape: 'spark',
    });
  }
}

export function updateEffects(game, dt) {
  const { particles, projectiles, beams, waves, floats } = game;

  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.life -= dt;
    if (p.life <= 0) { particles.splice(i, 1); continue; }
    p.vy += (p.grav ?? 750) * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    if (p.y > 0 && p.grav !== 0) {
      p.y = 0;
      p.vy *= -0.35;
      p.vx *= 0.7;
    }
    p.vx *= 0.99;
  }

  for (let i = projectiles.length - 1; i >= 0; i--) {
    const p = projectiles[i];
    p.life -= dt;
    p.x += p.vx * dt;
    p.trail -= dt;
    if (p.trail <= 0) {
      p.trail = 0.035;
      game.particles.push({
        x: p.x + (Math.random() - 0.5) * 10, y: p.y + (Math.random() - 0.5) * 10,
        vx: -p.vx * 0.08 + (Math.random() - 0.5) * 30, vy: (Math.random() - 0.5) * 30,
        life: 0.3, maxLife: 0.3, size: 3 + Math.random() * 4, color: p.color,
        grav: 0, additive: true, shape: 'circle',
      });
    }
    const d = game.fighters[1 - p.owner];
    if (!d.ko) {
      const width = 25 * d.char.scale + d.char.fat * 25;
      if (Math.abs(p.x - d.x) < width + p.r && p.y > d.y - 180 * d.char.scale && p.y < d.y + 2) {
        game.hitFighter(p.owner, 1 - p.owner, {
          damage: p.damage, knockback: 420, vy: -160, hitstun: 0.46, type: 'special',
          contact: { x: p.x, y: p.y }, color: p.color,
        });
        game.burst(p.x, p.y, p.color, 26, 6);
        projectiles.splice(i, 1);
        continue;
      }
    }
    // projectile clash
    let clashed = false;
    for (const q of projectiles) {
      if (q === p || q.owner === p.owner) continue;
      if (Math.abs(q.x - p.x) < 44 && Math.abs(q.y - p.y) < 44) {
        game.burst((p.x + q.x) / 2, (p.y + q.y) / 2, '#fff2c0', 30, 7);
        projectiles.splice(projectiles.indexOf(q), 1);
        clashed = true;
        break;
      }
    }
    if (clashed) { projectiles.splice(i, 1); continue; }
    if (p.life <= 0 || p.x < -120 || p.x > game.w + 120) projectiles.splice(i, 1);
  }

  for (let i = beams.length - 1; i >= 0; i--) {
    beams[i].t += dt;
    if (beams[i].t >= beams[i].dur) beams.splice(i, 1);
  }
  for (let i = waves.length - 1; i >= 0; i--) {
    waves[i].t += dt;
    if (waves[i].t >= waves[i].dur) waves.splice(i, 1);
  }
  for (let i = floats.length - 1; i >= 0; i--) {
    floats[i].t += dt;
    floats[i].y -= 36 * dt;
    if (floats[i].t >= floats[i].dur) floats.splice(i, 1);
  }
  if (game.flashAlpha > 0) game.flashAlpha = Math.max(0, game.flashAlpha - dt * 2.4);
}

function drawOrb(ctx, p, time) {
  const glow = ctx.createRadialGradient(p.x, p.y, 2, p.x, p.y, p.r * 2.6);
  glow.addColorStop(0, '#ffffff');
  glow.addColorStop(0.18, p.color);
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(p.x, p.y, p.r * 2.6, 0, TAU);
  ctx.fill();
  ell(ctx, p.x, p.y, p.r * 0.82, p.r * 0.82, p.color, null);
  ell(ctx, p.x - p.r * 0.15, p.y - p.r * 0.2, p.r * 0.28, p.r * 0.24, 'rgba(255,255,255,.85)', null);
  ctx.strokeStyle = p.color;
  ctx.lineWidth = 2;
  ctx.globalAlpha = 0.65;
  ctx.beginPath();
  ctx.arc(p.x, p.y, p.r * 1.35 + Math.sin(time * 10) * 2, 0, TAU);
  ctx.stroke();
  ctx.globalAlpha = 1;
}

function drawProjectile(ctx, p, time) {
  const dir = Math.sign(p.vx) || 1;
  ctx.save();
  if (p.look === 'fire') {
    ctx.save();
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 24;
    for (let i = 0; i < 4; i++) {
      const rr = p.r * (1.5 - i * 0.28);
      ell(ctx, p.x - dir * i * 7, p.y + Math.sin(time * 20 + i) * 3, rr, rr * 0.9, i === 0 ? p.color : i === 1 ? '#ffd24a' : '#fff2c8', null);
    }
    ctx.restore();
    // flame tail
    for (let i = 0; i < 5; i++) {
      ell(ctx, p.x - dir * (20 + i * 14), p.y + Math.sin(time * 24 + i) * 8, 10 - i * 1.4, 7 - i, `rgba(255,${130 - i * 16},40,${0.4 - i * 0.06})`, null);
    }
  } else if (p.look === 'wave') {
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.scale(dir, 1);
    ctx.strokeStyle = p.color;
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 15;
    for (let i = 0; i < 4; i++) {
      ctx.globalAlpha = 0.7 - i * 0.13;
      ctx.lineWidth = 5 - i;
      ctx.beginPath();
      ctx.arc(0, 0, 16 + i * 9, -1.1, 1.1);
      ctx.stroke();
    }
    ctx.restore();
  } else if (p.look === 'balloon') {
    const bob = Math.sin(time * 3) * 4;
    ctx.strokeStyle = 'rgba(230,220,210,.65)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(p.x - dir * 30, p.y + 14);
    ctx.quadraticCurveTo(p.x - dir * 12, p.y + 30, p.x, p.y + 14 + bob);
    ctx.stroke();
    ctx.save();
    ctx.shadowColor = '#ff3b3b';
    ctx.shadowBlur = 18;
    ell(ctx, p.x, p.y + bob, p.r, p.r * 1.25, '#d92b2b', '#7d1212', 1.5);
    ell(ctx, p.x - p.r * 0.3, p.y - p.r * 0.35 + bob, p.r * 0.22, p.r * 0.4, 'rgba(255,255,255,.35)', null);
    poly(ctx, [[p.x - 4, p.y + p.r * 1.2 + bob], [p.x + 4, p.y + p.r * 1.2 + bob], [p.x, p.y + p.r * 1.4 + bob]], '#7d1212');
    ctx.restore();
  } else if (p.look === 'bats') {
    ctx.save();
    ctx.translate(p.x, p.y);
    for (let i = 0; i < 4; i++) {
      const a = time * 5 + i * 1.7;
      const bx = Math.cos(a) * 22;
      const by = Math.sin(a * 1.3) * 16;
      ctx.fillStyle = i % 2 ? '#1a0d12' : '#2b1218';
      poly(ctx, [[bx - 10, by], [bx - 3, by - 6], [bx, by - 1], [bx + 3, by - 6], [bx + 10, by], [bx + 3, by + 2], [bx, by + 5], [bx - 3, by + 2]], i % 2 ? '#1a0d12' : '#2b1218');
      ell(ctx, bx, by - 1, 2, 2.4, '#c93a3a', null);
    }
    ell(ctx, p.x, p.y, p.r * 0.55, p.r * 0.55, 'rgba(255,40,60,.5)', null);
    ctx.restore();
  } else if (p.look === 'chain') {
    ctx.strokeStyle = '#8b8b96';
    ctx.lineWidth = 2.4;
    for (let i = 0; i < 5; i++) {
      ctx.beginPath();
      ctx.arc(p.x - dir * i * 9, p.y + Math.sin(time * 8 + i) * 2, 5, 0.2, 5.9);
      ctx.stroke();
    }
    ell(ctx, p.x, p.y, p.r * 0.5, p.r * 0.5, '#b9c4d9', null);
    ctx.save();
    ctx.translate(p.x + dir * 16, p.y);
    ctx.rotate(time * 8);
    poly(ctx, [[-6, -10], [10, 0], [-6, 10], [-2, 0]], '#b9c4d9');
    ctx.restore();
  } else if (p.look === 'magic') {
    const glow = ctx.createRadialGradient(p.x, p.y, 2, p.x, p.y, p.r * 3);
    glow.addColorStop(0, '#fff');
    glow.addColorStop(0.3, p.color);
    glow.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r * 3, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = p.color;
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 3; i++) {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(time * 3 + i);
      ctx.beginPath();
      for (let j = 0; j < 3; j++) {
        const a = (j / 3) * TAU;
        const x = Math.cos(a) * p.r * 1.5;
        const y = Math.sin(a) * p.r * 1.5;
        j ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
      }
      ctx.closePath();
      ctx.stroke();
      ctx.restore();
    }
    ell(ctx, p.x, p.y, p.r * 0.55, p.r * 0.55, '#fff', null);
  } else {
    drawOrb(ctx, p, time);
  }
  ctx.restore();
}

function drawBeam(ctx, b) {
  const fade = Math.sin(Math.min(1, b.t / b.dur) * Math.PI) * 0.9 + 0.1;
  const flick = 0.85 + Math.random() * 0.3;
  const x2 = b.x + b.dir * b.len;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = fade;
  ctx.lineCap = 'round';
  ctx.shadowColor = b.color;
  ctx.shadowBlur = 30;
  const g = ctx.createLinearGradient(b.x, b.y, x2, b.y);
  g.addColorStop(0, b.color);
  g.addColorStop(0.15, '#ffffff');
  g.addColorStop(0.7, b.color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.strokeStyle = g;
  ctx.lineWidth = b.thick * 2.6 * flick;
  ctx.beginPath();
  ctx.moveTo(b.x, b.y);
  ctx.lineTo(x2, b.y);
  ctx.stroke();
  ctx.strokeStyle = '#fffbe8';
  ctx.lineWidth = b.thick * flick;
  ctx.beginPath();
  ctx.moveTo(b.x, b.y);
  ctx.lineTo(x2, b.y);
  ctx.stroke();
  // muzzle flare
  const mg = ctx.createRadialGradient(b.x, b.y, 2, b.x, b.y, 60);
  mg.addColorStop(0, '#fff');
  mg.addColorStop(0.3, b.color);
  mg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = mg;
  ctx.beginPath();
  ctx.arc(b.x, b.y, 60, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawWave(ctx, wv, time) {
  const p = wv.t / wv.dur;
  const r = 20 + p * wv.maxR;
  const alpha = (1 - p) * 0.85;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = wv.color;
  ctx.shadowColor = wv.color;
  ctx.shadowBlur = 18;
  ctx.lineWidth = 6 * (1 - p) + 1.5;
  ctx.beginPath();
  ctx.ellipse(wv.x, 4, r, r * 0.22, 0, 0, TAU);
  ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.ellipse(wv.x, 4, r * 0.74, r * 0.17, 0, 0, TAU);
  ctx.stroke();
  // cracks
  ctx.globalAlpha = alpha * 0.8;
  ctx.lineWidth = 2.4;
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    const len = r * (0.45 + (i % 3) * 0.18);
    line(ctx, wv.x + Math.cos(a) * 20, 2 + Math.sin(a) * 6, wv.x + Math.cos(a) * len, 2 + Math.sin(a) * len * 0.2, wv.color, 2);
  }
  ctx.restore();
}

export function drawEffects(ctx, game, time) {
  const { particles, projectiles, beams, waves, floats } = game;

  // projectiles under the fighters' sparks but above ground
  for (const p of projectiles) drawProjectile(ctx, p, time);
  for (const b of beams) drawBeam(ctx, b);
  for (const wv of waves) drawWave(ctx, wv, time);

  ctx.save();
  for (const p of particles) {
    const a = Math.max(0, p.life / p.maxLife);
    ctx.globalAlpha = a;
    if (p.additive) ctx.globalCompositeOperation = 'lighter';
    else ctx.globalCompositeOperation = 'source-over';
    if (p.shape === 'dust') {
      ell(ctx, p.x, p.y, p.size * (1.6 - a * 0.6), p.size * (1.6 - a * 0.6), p.color, null);
    } else if (p.shape === 'spark') {
      line(ctx, p.x, p.y, p.x - p.vx * 0.02, p.y - p.vy * 0.02, p.color, Math.max(1, p.size * 0.4));
    } else {
      ell(ctx, p.x, p.y, p.size * a, p.size * a, p.color, null);
    }
  }
  ctx.restore();

  for (const f of floats) {
    const a = Math.max(0, 1 - f.t / f.dur);
    ctx.save();
    ctx.globalAlpha = a;
    ctx.font = '900 22px Impact, "Arial Black", sans-serif';
    ctx.textAlign = 'center';
    ctx.strokeStyle = '#0a0709';
    ctx.lineWidth = 5;
    ctx.strokeText(f.text, f.x, f.y);
    ctx.fillStyle = f.color;
    ctx.fillText(f.text, f.x, f.y);
    ctx.restore();
  }
}

export function drawFlash(ctx, game) {
  if (game.flashAlpha <= 0) return;
  ctx.save();
  ctx.globalAlpha = Math.min(0.65, game.flashAlpha);
  ctx.fillStyle = game.flashColor;
  ctx.fillRect(0, 0, game.w, game.h);
  ctx.restore();
}

content.text:
Now game.js. Let's write carefully.

Imports:
import { drawFighter, drawFighterShadow } from './art.js';
import { drawStage, GROUND_Y } from './stages.js';
import { makeHudAvatar } from './portraits.js';
import { drawHud, drawVignette } from './hud.js';
import { updateEffects, drawEffects, drawFlash, spawnProjectile, spawnBeam, spawnShockwave } from './fx.js';
import { sound } from './audio.js';

Constants W=1280 H=720 GROUND=596.

Difficulty config.

class FightGame {
 constructor(opts) { canvas etc; this.ctx; this.setup; add listeners; this.loop bound; start }
 setup:
   this.p1char, p2char, mode, difficulty, stage index/obj.
   this.fighters = [this.makeFighter(p1,0), makeFighter(p2,1)];
   this.wins=[0,0]; this.round=1; this.roundTime=60;
   this.phase='intro'; this.introTime=0; this.roundEndTime=0; this.matchEndTime=0;
   this.time=0; this.paused=false; this.hitStop=0; this.shakeMag=0; this.shakeTime=0;
   arrays.
   this.avatars=[makeHudAvatar(p1), makeHudAvatar(p2)];
   this.keys = new Set(); this.held=[{...}, {...}];
   this.buffer arrays? fighter.buffer.
   this.ai = {timer:0.4, dir:0, block:0, cool:0, jump:0}
   this.aiHeld = {left:false,right:false,down:false}
   this.announcement = null
   this.flashAlpha=0; flashColor='#fff'
   this.flash(c = '#fff', a) method.
   this.startRound(1); actually set positions/hp and announce round & intro.
   Bind events: keydown, keyup, blur (clear held), pointer? UI handles touch.
   window.addEventListener.
   this.raf = requestAnimationFrame(this.frame).
 }

 makeFighter(char, index):
  base speed = 170 + speed*17 + (1 - fat)*12? tiny chars? Let's use 185 + speed*15. reach = 44 + reach*6? The attack function uses stats.
  maxHp=100; hp=100; meter=0.
  scale char.scale.
  width = (24 + fat*26)*scale (collision half width) maybe.
  this properties:
  x = index===0 ? 430 : 850, y=0, vx=0, vy=0, facing= index===0?1:-1,
  state='idle', animTime=0, attack=null, special=null, dash=null,
  blocking=false, hitstun=0, invuln=0, ko=false, win=false,
  combo=0, comboTimer=0, cooldown=0, buffer:{jump:0,punch:0,kick:0,special:0},
  hp, displayHp=100, meter=0, maxHp=100,
  powerFactor=0.82 + char.stats.power*0.07,
  speed=185 + char.stats.speed*15 - fat*20? For fat speed lower; stats already. use 180+speed*17,
  weight=1+fat*0.55,
  width=(26+fat*26)*char.scale,
  height=(172+char.fat*10)*char.scale (Bill: 190)
  inAir false.
  wins? game.

 Round start:
  resetFighter(f,index): x positions, hp 100, displayHp 100, meter keep? For initial round meter 0. Keep across rounds (set at creation). On round 2 keep meter.
  vy=0 vx=0 state idle; attack null special null dash null; blocking false; hitstun 0; ko false; win false; combo 0; cooldown 0.
  roundTime=60.
  phase='intro'; introTime=0; roundEndTime=0.
  announce('ROUND '+this.round, this.stage.name, 'round', 1.1); this.introAnnouncedFight=false.
  sound bell.

 frame(ts):
  dt = min(0.033, (ts-last)/1000) (first frame dt 0.016)
  last=ts
  if(!paused) this.update(dt)
  this.draw(ts/1000)
  raf.

 update(dt):
  this.time += dt;
  announcement t += dt; if t>dur+.1 set null (keep it simple after dur).
  if hitStop>0: hitStop -= dt; update shake? decay; return; but announcement still; also display? Keep screen shake.
  update shake: shakeTime -= dt; mag; 
  phase intro: introTime += dt; fighters animTime += dt; idle states; if introTime>1.0 && !fightAnnounced: announce('FIGHT!', fighter names? '', 'fight', 0.8); fightAnnounced=true; sound play bell/fight; if introTime>1.65: phase='fight'; 
  fight: roundTime -= dt; if <=0 → endRound(timeUp).
    update inputs: apply human/AI; update fighters; update effects; check KO (if any f.hp<=0 and phase still fight → endRound(winner)).
  roundEnd: roundEndTime += dt; update fighters without input (physics, ko) and effects; at 1.2 maybe winner win pose? Set at endRound: winner.state='win'? But they should idle; KO loser flying. Set winner.win=true and state='win' after 0.8s. We'll set immediately winner.state='win'? That looks odd while loser flies. Fine after 0.8.
    if roundEndTime>2.5: resolve (if match over → matchend callback else next round).
  matchEnd: update fighters idle/win, effects; maybe nothing.
  In fight, also update AI.
  timers for fighter (buffer, cooldown) update.
  fade announcement.
  flashAlpha decay in updateEffects.

  Handle pause: skip all including effects.

 updateFighter(f, opponent, dt, allowInput):
  f.animTime += dt;
  decrement buffer values by dt, cooldown, invuln, comboTimer.
  displayHp += (hp-displayHp)*min(1,dt*6); if abs<.2 set.
  if f.ko: apply physics only (y, vy, vx friction), return.
  if f.hitstun>0: f.hitstun-=dt; f.state='hit'; physics; return.
  if (f.state==='win' && !allowInput) { return; }
  // Attack progression
  if (f.attack) { updateAttack...; applyPhysics; return; }
  if (f.special) { updateSpecial...; applyPhysics; return; }
  if (f.dash) ... special handles.
  // actions from buffer
  if(allowInput) {
    if f.buffer.jump>0 && f.grounded && canAct: jump
    if f.buffer.special>0 & meter>=50: startSpecial
    else if f.buffer.kick>0: startAttack
    else if f.buffer.punch>0: startAttack
  }
  // movement
  if (allowInput) {
    const held=this.getHeld(f.side)
    ...
  } else { f.vx *= 0.8; if(!f.attack) f.state = f.state==='ko'?'ko': (f.state==='win'?'win':'idle'); }
  physics
  // facing
  if (allowInput) f.facing = opponent.x >= f.x ? 1 : -1;

 Need handle state 'idle' etc.

 applyPhysics(f,dt):
  f.x += vx*dt; f.y += vy*dt;
  if f.y < 0? y is negative when airborne. Ground at y=0. On jump vy negative, gravity positive.
  if (f.y > 0) { f.y=0; f.vy=0; f.grounded=true; }
  if (!f.grounded) f.vy += 2200*dt; Wait integrate: y += vy*dt; vy += g*dt. If y>=0 land.
  Clamp x [70, 1210].

 For Bill floating? standard.

 Jump: f.vy=-720; f.grounded=false; f.state='jump'; sound swing? no.

 Movement speed with fat: use f.speed * (1 - fat*0.2).
 Air control: vx += axis*420*dt clamp ±speed*1.15.

 Blocking: if held.down && grounded → f.blocking=true, state='block', vx=0. Blocking persists only when held; can we block in air? no.
 If not down, blocking false.

 Auto facing when not attacking: face opponent always during idle/walk/block. Good.

 Attack:
 startAttack(f,type):
  if f.meter etc.
  f.attack={type, elapsed:0, hit:false, dur: type==='punch'?0.32:0.48};
  f.state='attack'; f.vx = 0; if type kick f.vy = f.grounded? 0; sound swing.
  For air attack, keep vy.
 update:
  elapsed +=dt;
  const activeStart = punch .08, activeEnd .19; kick .15-.30.
  if in window & !hit: this.checkAttack(f,opponent,type).
  if elapsed>=dur: f.attack=null; f.state=grounded?'idle':'jump'; f.cooldown=.08.
  friction.
  Do not move.
  If attack in air, physics continues.

 Special:
 startSpecial(f): meter-=50; f.special={type: char.special.type, elapsed:0, fired:false, dashDone:false}; f.state='special'; f.vx=0; f.attack=null; this.announce? No; maybe show float with special name near fighter once: float text char.special.name at f.x, f.y-220*scale with color. That could be cool. Add game.addFloat(text,x,y,color,size?) HUD floats only 22px. Use 18px; text may be long. Maybe skip to avoid clutter. Instead spawn aura particles.
 sound.play('special')? triggers at spawn for projectile; for others at start. Do at start generic 'special' for dash/slam/beam? Beam plays beam at spawn. Let's play special at start for all.
 update:
  elapsed += dt;
  if type dash:
    if !dashDone && elapsed > 0.16: f.dash={time:0.34, hit:false}; f.vx=f.facing*640; f.dashDone=true;
    if f.dash:
      f.dash.time-=dt; f.vx = f.facing*640*(0.6+0.4*(f.dash.time/0.34));
      trail particles each frame; check hit: if !dash.hit and distance < 78*scale → this.hitFighter(f.side,...,dmg 16*power, knock 500, vy -120...) and dash.hit=true; burst.
      if dash.time<=0 f.dash=null;
  if projectile and elapsed>0.24 && !fired: spawnProjectile, fired=true.
  if beam and >0.28 && !fired: spawnBeam.
  if slam and >0.36 && !fired: spawnShockwave.
  if elapsed > dur (1.0 dash .8) → special=null; state idle.
  applyPhysics (dash vx movement).
  For dash, allow gravity.

 Need dash can hit only once; hitFighter may set phase roundEnd and hitstun etc. set dash.hit=true.

 Also during special, opponent could hit; fine.

checkAttack(attacker, defender, type):
 if defender.ko return; compute:
  const s = attacker.char.scale, reach=attacker.char.stats.reach, fat=attacker.char.fat;
  const bodyHalf = defender.width;
  let hx, hy, range;
  if punch: range = (58 + reach*6 + fat*8) * s; hy = attacker.y - 102*s; 
  kick: range = (78 + reach*7 + fat*6)*s; hy = attacker.y - 74*s;
  Attack must be in front: dx = (defender.x - attacker.x)*attacker.facing; if dx < -10 or dx > range + bodyHalf return.
  vertical: defender's body from y-175*scale*? to y; hy between defender.y - 170*defScale and defender.y + 10.
  contact = {x: attacker.x + attacker.facing*range*0.82, y: hy}
  damage base punch 5.6, kick 8.4; times powerFactor; combo scaling.
  hitFighter(attacker.side, defender.side, {damage, knockback punch 170 kick 300, vy kick -120 else 0, hitstun punch .3 kick .4, type, contact, color})
  attacker.attack.hit = true.

hitFighter(ai, di, spec):
  attacker = fighters[ai], defender = fighters[di].
  if defender.ko || this.phase!=='fight'? For dash maybe phase changed after hit; allow during fight only. Actually phase roundEnd after KO; no more hits. Guard if defender.ko.
  blocked = defender.blocking && defender.state !== 'hit';
  const defReduction = 1 - (defender.char.stats.defense - 1)*0.045;
  let dmg = spec.damage * defReduction;
  if blocked dmg *= 0.2;
  combo scaling: if spec.type !== 'special' and attacker.combo>0: dmg *= Math.max(.55, 1-attacker.combo*0.07).
  defender.hp = max(0, hp - dmg);
  if blocked:
    defender.vx = attacker.facing * (spec.knockback||180)*0.35;
    defender.hitstun = 0.14; defender.state='block'; attacker.meter=min(100,+4); defender.meter+5;
    this.hitStop=0.03; shake 2; sound block; burst(contact, '#cfd8e8', 8, 3); addFloat('BLOCKED', contact.x, contact.y-30, '#cfd8e8');
  else:
    defender.hitstun = spec.hitstun || .3;
    defender.invuln = 0.06;
    defender.vx = attacker.facing * (spec.knockback||220) / defender.weight;
    if (spec.vy) { defender.vy = spec.vy; defender.grounded=false; }
    defender.state='hit';
    attacker.combo += 1; attacker.comboTimer = 1.25;
    attacker.meter = min(100, +9); defender.meter = min(100, +7);
    this.hitStop = spec.type==='special'?0.09:0.05;
    this.shake(spec.type==='special'?10:5, .2);
    this.sound.play(spec.type==='special'?'heavy':'hit');
    this.burst(contact.x, contact.y, spec.color||'#ffd45c', spec.type==='special'?26:14, spec.type==='special'?6:4);
    this.flash('#fff', spec.type==='special'?0.12:0.04);
    if (defender.hp<=0) { defender.hp=0; this.onKO(attacker, defender); }
  defender.displayHp maybe not immediate; fine.
  Defender blocking should turn off? After hit, hitstun blocks inputs; blocking property still true but check uses hitstun state; set defender.blocking=false maybe.
  contact coordinates passed.

onKO(attacker, defender):
 defender.ko=true; defender.state='ko'; defender.hitstun=0; defender.vy=-450; defender.vx=attacker.facing*260; defender.grounded=false? For flying; draw rotate; y may go up. We'll set vy=-320, grounded=false. if defender.y already 0.
 defender.hp=0;
 attacker.combo=0? keep.
 this.endRound(attacker.side, 'ko');
 sound ko.
 announce('K.O.', `${defender.char.name} IS DOWN`, 'ko', 2.0);
 shake 26 .6; flash '#fff', .35; hitStop .16.
 spawn big burst at defender.

endRound(winnerIndex, reason):
 if phase!=='fight' return.
 this.phase='roundEnd'; this.roundEndTime=0;
 this.roundWinner = winnerIndex;
 if winnerIndex>=0 → wins[winnerIndex]++.
 if reason==='time' announce('TIME UP', winner text..., 'time', 1.8) else (KO already announced in onKO). For time: sound bell; if winner -1 announce DRAW.
 this.matchOver = wins[0]>=2 || wins[1]>=2;
 this.roundResolved = false.
 set loser state ko? For time, both alive; loser could be idle. Winner state='win' after delay.
 this.roundEndTimer.
 Note: for KO already announcement; endRound shouldn't override. Pass reason.

 update roundEnd:
  time += dt; update fighters allowInput false; but fighters with state win remain; effects.
  at 0.8: winner.state='win'; winner.win=true; sound win maybe once (round win jingle).
  at 2.6: if matchOver → phase='matchEnd'; call onMatchEnd after timeout? We'll call this.onMatchEnd({winnerIndex, wins, round}) now, and UI overlay has delay. Set phase='matchEnd'; sound win/lose.
  else { this.round++; this.startRound(); }

 startRound:
  reset fighters positions/hp (keep meter). For round>1, maybe keep winner's meter; fine.
  hunter: ensure y=0, vy=0, grounded true; ko false; state idle; facing.
  roundTime=60; phase='intro'; introTime=0; fightAnnounced=false;
  announcement ROUND.
  sound bell.
  If round 1 initially meter 0.

 matchEnd: winner.state='win'; loser.ko already true if KO. If time win loser not ko; loser state idle; winner win. UI overlay.

 AI update:
 updateAI(dt):
  const f=fighters[1], o=fighters[0];
  ai.timer -= dt; ai.cool -=dt; ai.blockTimer -=dt; 
  // block reaction
  if (o.attack || o.special) {
    if (ai.blockTimer<=0 && Math.random() < cfg.blockChance*dt*8) { ai.blockTimer = .3+Math.random()*.3; }
  }
  this.aiHeld.down = ai.blockTimer>0;
  if ai.timer<=0:
    ai.timer = cfg.think * (0.7+Math.random()*0.6);
    const dist = abs(o.x-f.x);
    const dir = Math.sign(o.x-f.x);
    this.aiHeld.left=false; this.aiHeld.right=false;
    const specialRange = f.char.special.type==='dash'||f.char.special.type==='slam' ? 230 : 900;
    if (ai.cool<=0 && f.meter>=50 && Math.random()<cfg.specialChance && dist<specialRange) {
      this.pressAction(1,'special'); ai.cool = .9;
    } else if (ai.cool<=0 && dist < 150 && Math.random()<cfg.aggr) {
      this.pressAction(1, Math.random()<0.55?'punch':'kick');
      ai.cool = 0.28 + Math.random()*0.4;
    } else if (dist > 165) {
      if (dir>0) this.aiHeld.right=true; else this.aiHeld.left=true;
    } else if (dist < 75 && Math.random()<0.35) {
      if (dir>0) this.aiHeld.left=true; else this.aiHeld.right=true;
    } else if (Math.random()<cfg.jump && f.grounded && dist<300) {
      this.pressAction(1,'jump');
    }
  // avoid corner
  if (f.x<120) aiHeld.left=false;
  if (f.x>1160) aiHeld.right=false;
  // ai random errors: not attacking if too far (attack range based)
  If AI request happens while too far, it will whiff; acceptable but lower difficulty should whiff. Attack condition dist<150 might be too far for punch but kick reaches. Use dist < 120 for punch, <145 kick. Simpler choose kick if dist>90 else punch.
  Difficulty config:
   rookie: think .5, blockChance .12, aggr .55, specialChance .3, jump .15
   normal: think .32, blockChance .3, aggr .75, specialChance .55, jump .2
   nightmare: think .18, blockChance .5, aggr .95, specialChance .85, jump .25
  Block reaction formula with dt*8 gives per-frame probability .3*.016*8=.038, over .3s ~ 50%? Fine. Better use ai.blockCheckTimer. Simpler: when opponent starts attack and random < blockChance*0.6 → set blockTimer .4. Check if ai.blockTimer<=0. The attack lasts .3s, AI update each frame; repeated checks could trigger quickly. ok.
  AI must not block permanently: blockTimer decrements.
  Also AI should approach when opponent far and use projectiles.

 getHeld(side): if side===1 && mode==='cpu' return this.aiHeld; else this.held[side].

 applyInput:
 if allowInput and phase fight:
  const held=getHeld(side);
  movement; jump via buffer; etc. We'll incorporate in updateFighter.
  For jump pressed through pressAction.
  Buffer processing within updateFighter.

 pressAction(side, action):
  if phase!=='fight' || paused return.
  f = fighters[side]; if f.ko or hitstun>0 return.
  Buffer set `.15` and if canAct immediate.
  For special require meter>=50; still buffer? Only press if meter>=50.
  call start...; else buffer.
  canAct = !f.attack && !f.special && !f.hitstun>0 && f.grounded? Air attacks allowed. Jump only grounded.
  For jump: if grounded & no attack/special → jump else buffer.
  For punch/kick: if no attack/special & hitstun<=0 → start; else buffer.
  For special: if meter>=50 and no attack/special → start.
  Also if blocking maybe allow attack (release block) yes.

 updateFighter action buffers: use buffer timers set by pressAction when not started. Implement helper setBuffer(f,key,val=.14).
 In updateFighter before movement:
  if allowInput:
    if f.buffer.special>0 && f.meter>=50 && canAct → startSpecial; clear
    if f.buffer.kick>0 && canAct → startAttack kick
    if f.buffer.punch>0 && canAct → startAttack punch
    if f.buffer.jump>0 && f.grounded && canAct → jump
  But canAct after start? sequence of ifs; use else-if.
  Note buffer decremented before.

 Physics and collision:
  this.separate(f,opponent).
  separate: if both not ko: const minDist = f.width + opponent.width; const dx = opponent.x - f.x; if abs(dx)<minDist: push = (minDist-abs(dx))/2; sign=Math.sign(dx)||1; f.x -= sign*push; opponent.x += sign*push; clamp.
