    radial-gradient(ellipse at 15% 0%, rgba(225,40,40,.15), transparent 42%),
    radial-gradient(ellipse at 92% 80%, rgba(176,92,255,.09), transparent 45%),
    linear-gradient(180deg, #08060a 0%, #0d090e 100%);
}
.select-screen::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(244,237,220,.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(244,237,220,.028) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(ellipse at 50% 40%, #000 25%, transparent 80%);
}
.select-header {
  position: sticky;
  top: 0;
  z-index: 12;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: calc(12px + var(--safe-top)) clamp(14px, 2.4vw, 34px) 12px;
  background: linear-gradient(180deg, rgba(8,6,10,.98) 0%, rgba(8,6,10,.92) 70%, rgba(8,6,10,0) 100%);
  backdrop-filter: blur(8px);
}
.select-heading { display: flex; flex-direction: column; gap: 0; flex: 1; min-width: 0; }
.select-heading h2 {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(26px, 3.4vw, 46px);
  letter-spacing: .02em;
  line-height: 1;
  color: var(--ink);
  white-space: nowrap;
}
.select-heading .eyebrow { font-size: 9px; letter-spacing: .24em; }
.select-modes { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: flex-end; }
.segmented {
  display: flex;
  border: 1px solid var(--line);
  background: rgba(12,9,13,.8);
  padding: 3px;
  gap: 2px;
}
.segmented button {
  border: 0;
  background: transparent;
  color: var(--muted);
  font-family: var(--font-ui);
  font-weight: 800;
  font-size: 11px;
  letter-spacing: .13em;
  padding: 7px 11px;
  cursor: pointer;
  transition: background .15s, color .15s;
  white-space: nowrap;
}
.segmented button:hover { color: var(--ink); }
.segmented button.active {
  background: var(--red);
  color: #fff;
  box-shadow: 0 2px 10px rgba(225,40,40,.35);
}
.segmented-diff button.active { background: #312532; color: var(--gold); box-shadow: none; }

.select-main {
  position: relative;
  z-index: 3;
  width: 100%;
  max-width: 1540px;
  margin: 0 auto;
  padding: 6px clamp(14px, 2.4vw, 34px) calc(30px + var(--safe-bottom));
  display: grid;
  grid-template-columns: minmax(280px, 330px) minmax(0, 1fr);
  gap: clamp(14px, 2vw, 28px);
  align-items: start;
}

/* preview */
.preview-panel {
  position: sticky;
  top: 86px;
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(24,17,25,.96) 0%, rgba(12,9,13,.98) 100%);
  box-shadow: 0 24px 60px rgba(0,0,0,.5);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
}
.preview-frame {
  position: relative;
  overflow: hidden;
  background: #070509;
  border-bottom: 1px solid var(--line);
}
.preview-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 55%, rgba(225,40,40,.16), transparent 58%),
    linear-gradient(180deg, rgba(255,255,255,.03), transparent 40%);
  z-index: 1;
  pointer-events: none;
}
#previewCanvas { width: 100%; height: auto; aspect-ratio: 720 / 760; }
.preview-scan {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(0,0,0,.14) 0 1px, transparent 1px 4px);
  opacity: .55;
}
.preview-tag {
  position: absolute;
  top: 10px;
  right: 12px;
  z-index: 3;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: .12em;
  color: rgba(244,237,220,.45);
}
.preview-vs {
  position: absolute;
  left: 12px;
  bottom: 10px;
  z-index: 3;
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: .14em;
  color: var(--gold);
  text-shadow: 0 2px 6px #000;
}
.preview-corner {
  position: absolute;
  width: 14px; height: 14px;
  border-color: rgba(255,212,71,.55);
  border-style: solid;
  z-index: 3;
}
.preview-corner.tl { top: 7px; left: 7px; border-width: 2px 0 0 2px; }
.preview-corner.tr { top: 7px; right: 7px; border-width: 2px 2px 0 0; }
.preview-corner.bl { bottom: 7px; left: 7px; border-width: 0 0 2px 2px; }
.preview-corner.br { bottom: 7px; right: 7px; border-width: 0 2px 2px 0; }

.preview-info { padding: 15px 17px 17px; }
.preview-info h3 {
  margin: 3px 0 1px;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(25px, 2.4vw, 34px);
  line-height: .98;
  letter-spacing: .01em;
}
.pv-title {
  margin: 0 0 8px;
  font-weight: 800;
  font-size: 11px;
  letter-spacing: .18em;
  color: var(--red-bright);
  text-transform: uppercase;
}
.pv-quote {
  margin: 0 0 13px;
  font-size: 13px;
  line-height: 1.35;
  font-style: italic;
  color: var(--ink-dim);
  border-left: 2px solid rgba(225,40,40,.5);
  padding-left: 9px;
  min-height: 35px;
}
.stat-grid { display: grid; gap: 5px; margin-bottom: 13px; }
.stat-row { display: grid; grid-template-columns: 52px 1fr; align-items: center; gap: 8px; }
.stat-row span {
  font-size: 9px; font-weight: 800; letter-spacing: .14em; color: var(--muted); text-transform: uppercase;
}
.stat-segs { display: flex; gap: 3px; }
.stat-seg { height: 6px; flex: 1; background: rgba(255,255,255,.08); transform: skewX(-18deg); }
.stat-seg.on { background: linear-gradient(90deg, var(--red), #ff7a3c); box-shadow: 0 0 8px rgba(225,40,40,.35); }
.stat-seg.gold.on { background: linear-gradient(90deg, #d9a12c, var(--gold)); }

.special-card {
  border: 1px solid rgba(255,212,71,.2);
  border-left: 3px solid var(--gold);
  background: rgba(255,212,71,.045);
  padding: 9px 11px 10px;
  position: relative;
}
.special-card .eyebrow { font-size: 8px; color: rgba(255,212,71,.7); }
.special-card strong {
  display: block;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 18px;
  letter-spacing: .035em;
  color: var(--gold);
  margin: 2px 0 2px;
}
.special-card p { margin: 0; font-size: 11px; line-height: 1.35; color: var(--ink-dim); }

/* roster */
.roster-area { min-width: 0; display: flex; flex-direction: column; }
.roster-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
  flex-wrap: wrap;
}
.step-tabs { display: flex; gap: 4px; }
.step-tabs button {
  appearance: none;
  border: 1px solid var(--line);
  background: rgba(13,10,14,.7);
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  font-family: var(--font-ui);
  font-weight: 800;
  letter-spacing: .1em;
  font-size: 11px;
  cursor: pointer;
  transition: all .15s;
}
.step-tabs button span {
  display: grid;
  place-items: center;
  width: 18px; height: 18px;
  background: rgba(255,255,255,.08);
  font-family: var(--font-display);
  font-size: 11px;
  color: var(--ink-dim);
}
.step-tabs button:hover { color: var(--ink); border-color: rgba(255,212,71,.35); }
.step-tabs button.active {
  color: var(--ink);
  border-color: rgba(225,40,40,.65);
  background: rgba(225,40,40,.12);
  box-shadow: inset 0 -2px 0 var(--red);
}
.step-tabs button.active span { background: var(--red); color: #fff; }
.roster-tools { display: flex; gap: 6px; }

.roster-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 7px;
}
.fighter-card {
  position: relative;
  appearance: none;
  border: 1px solid rgba(244,237,220,.11);
  background:
    linear-gradient(180deg, rgba(34,25,35,.65) 0%, rgba(13,10,14,.9) 100%);
  padding: 0;
  cursor: pointer;
  text-align: left;
  overflow: hidden;
  min-height: 96px;
  transition: transform .14s ease, border-color .14s ease, box-shadow .14s ease;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 6px), calc(100% - 6px) 100%, 0 100%);
}
.fighter-card canvas {
  width: 100%;
  height: 78px;
  object-fit: contain;
  display: block;
  padding: 2px 2px 0;
  filter: drop-shadow(0 4px 6px rgba(0,0,0,.45));
}
.fighter-card .card-name {
  display: block;
  padding: 3px 5px 4px;
  font-family: var(--font-ui);
  font-weight: 800;
  font-size: 9.5px;
  line-height: 1.05;
  letter-spacing: .035em;
  text-transform: uppercase;
  color: rgba(244,237,220,.72);
  border-top: 1px solid rgba(255,255,255,.06);
  background: rgba(7,5,9,.65);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fighter-card:hover {
  transform: translateY(-3px);
  border-color: rgba(255,212,71,.65);
  box-shadow: 0 10px 22px rgba(0,0,0,.5), 0 0 0 1px rgba(255,212,71,.15);
  z-index: 4;
}
.fighter-card:hover .card-name { color: var(--ink); }
.fighter-card.is-p1 {
  border-color: var(--green);
  box-shadow: 0 0 0 1px rgba(184,230,74,.55), 0 0 18px rgba(184,230,74,.14);
}
.fighter-card.is-p2 {
  border-color: var(--red-bright);
  box-shadow: 0 0 0 1px rgba(255,68,56,.6), 0 0 18px rgba(255,68,56,.16);
}
.fighter-card.is-p1.is-p2 { border-color: var(--gold); box-shadow: 0 0 0 1px var(--gold), 0 0 20px rgba(255,212,71,.25); }
.card-badge {
  position: absolute;
  top: 3px;
  left: 3px;
  z-index: 3;
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: .06em;
  padding: 2px 5px;
  color: #0b0807;
  background: var(--green);
  box-shadow: 0 2px 8px rgba(0,0,0,.4);
}
.card-badge.p2 { background: var(--red-bright); color: #fff; }
.fighter-card.is-p1.is-p2 .card-badge.p2 { left: auto; right: 3px; background: var(--gold); }
.fighter-card .card-num {
  position: absolute;
  right: 3px;
  bottom: 23px;
  font-family: var(--font-mono);
  font-size: 8px;
  color: rgba(244,237,220,.26);
}

.arena-bar {
  margin-top: 11px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-top: 1px solid var(--line);
  padding-top: 11px;
  flex-wrap: wrap;
}
.arena-label { display: flex; flex-direction: column; min-width: 78px; }
.arena-label .eyebrow { font-size: 8px; }
.arena-label strong {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 16px;
  letter-spacing: .03em;
  white-space: nowrap;
}
.arena-list { display: flex; gap: 5px; flex: 1; flex-wrap: wrap; }
.arena-btn {
  appearance: none;
  border: 1px solid rgba(244,237,220,.12);
  background: #0c090d;
  padding: 3px;
  cursor: pointer;
  transition: border-color .15s, transform .15s;
  display: flex;
  flex-direction: column;
  gap: 2px;
  align-items: stretch;
}
.arena-btn canvas { width: 82px; height: 34px; display: block; opacity: .75; }
.arena-btn span {
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: .08em;
  color: var(--muted);
  text-align: center;
  text-transform: uppercase;
}
.arena-btn:hover { border-color: rgba(255,212,71,.5); transform: translateY(-1px); }
.arena-btn.active { border-color: var(--gold); box-shadow: 0 0 14px rgba(255,212,71,.16); }
.arena-btn.active canvas { opacity: 1; }
.arena-btn.active span { color: var(--gold); }
.btn-fight { margin-left: auto; }
.btn-fight:not(:disabled) { animation: fightPulse 2.4s ease-in-out infinite; }
@keyframes fightPulse {
  0%, 100% { box-shadow: 0 8px 34px rgba(225,40,40,.26); }
  50% { box-shadow: 0 8px 46px rgba(255,90,50,.5); }
}

/* ============================================================
   FIGHT
   ============================================================ */
.fight-screen {
  background: radial-gradient(ellipse at center, #120a10 0%, #050407 70%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.stage-wrap {
  position: relative;
  width: min(100vw, calc(100dvh * 16 / 9));
  height: min(100dvh, calc(100vw * 9 / 16));
  max-width: 100vw;
  max-height: 100dvh;
}
.stage-frame { position: absolute; inset: 0; background: #050407; }
#gameCanvas { width: 100%; height: 100%; display: block; }
.pause-btn {
  position: absolute;
  top: max(10px, 1.6%);
  right: max(10px, 1.4%);
  z-index: 6;
  width: 40px;
  height: 36px;
  appearance: none;
  border: 1px solid rgba(244,237,220,.22);
  background: rgba(8,6,9,.55);
  color: rgba(244,237,220,.7);
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: .08em;
  cursor: pointer;
  backdrop-filter: blur(4px);
  transition: all .15s;
}
.pause-btn:hover { color: var(--gold); border-color: rgba(255,212,71,.5); background: rgba(15,10,15,.8); }
.fight-hint {
  position: absolute;
  left: 12px;
  bottom: 10px;
  z-index: 6;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .12em;
  color: rgba(244,237,220,.25);
  pointer-events: none;
}
.rotate-hint { display: none; }

/* touch */
.touch-controls { display: none; }
body.touch .touch-controls {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  z-index: 8;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  padding: 0 12px 12px;
  pointer-events: none;
}
.touch-move { display: flex; gap: 8px; align-items: flex-end; }
.touch-actions {
  display: grid;
  grid-template-columns: repeat(2, 64px);
  grid-template-rows: repeat(2, 64px);
  gap: 7px;
}
.tbtn {
  pointer-events: auto;
  appearance: none;
  width: 64px; height: 64px;
  border-radius: 50%;
  border: 2px solid rgba(244,237,220,.28);
  background: rgba(10, 7, 11, .62);
  color: rgba(244,237,220,.85);
  font-family: var(--font-display);
  font-size: 12px;
  letter-spacing: .06em;
  cursor: pointer;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  backdrop-filter: blur(6px);
  box-shadow: 0 4px 16px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.09);
  transition: transform .08s, background .08s, border-color .08s;
}
.tbtn:active, .tbtn.down { transform: scale(.93); background: rgba(225,40,40,.45); border-color: rgba(255,150,120,.9); }
.tbtn-dir { width: 58px; height: 58px; }
.tbtn-up { border-color: rgba(106,201,255,.35); }
.tbtn-punch, .tbtn-kick { border-color: rgba(225,40,40,.55); background: rgba(120,18,22,.4); }
.tbtn-special { border-color: rgba(255,212,71,.7); color: var(--gold); background: rgba(90,65,9,.4); }
.tbtn-special.ready { animation: specialGlow 1.1s ease-in-out infinite; }
@keyframes specialGlow {
  0%, 100% { box-shadow: 0 0 10px rgba(255,212,71,.3); }
  50% { box-shadow: 0 0 26px rgba(255,212,71,.75); }
}
.tbtn-block { border-color: rgba(106,201,255,.35); font-size: 11px; }

/* ============================================================
   OVERLAYS / MODALS
   ============================================================ */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  padding: calc(16px + var(--safe-top)) 16px calc(16px + var(--safe-bottom));
  background: rgba(4, 3, 6, .8);
  backdrop-filter: blur(9px) saturate(.7);
  overflow-y: auto;
  animation: overlayIn .22s ease both;
}
@keyframes overlayIn { from { opacity: 0; } to { opacity: 1; } }

.modal {
  position: relative;
  width: min(560px, 94vw);
  background:
    radial-gradient(ellipse at 25% 0%, rgba(225,40,40,.13), transparent 48%),
    linear-gradient(180deg, #171019 0%, #0b080c 100%);
  border: 1px solid rgba(244,237,220,.16);
  box-shadow: 0 30px 90px rgba(0,0,0,.7), inset 0 1px 0 rgba(255,255,255,.07);
  padding: clamp(20px, 3vw, 38px);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
  animation: modalIn .28s cubic-bezier(.2,.9,.25,1.1) both;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(18px) scale(.98); } to { opacity: 1; transform: none; } }
.modal h2 {
  margin: 4px 0 18px;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(42px, 7vw, 64px);
  line-height: .9;
  letter-spacing: .015em;
  color: var(--ink);
  text-shadow: 0 4px 0 rgba(0,0,0,.4);
}
.pause-modal { text-align: center; }
.pause-fighters { display: flex; align-items: center; justify-content: center; gap: 12px; margin: -8px 0 20px; }
.pause-fighter { display: flex; flex-direction: column; align-items: center; gap: 4px; }
.pause-fighter canvas { width: 92px; height: 100px; object-fit: contain; filter: drop-shadow(0 8px 12px rgba(0,0,0,.5)); }
.pause-fighter span { font-family: var(--font-ui); font-size: 10px; font-weight: 800; letter-spacing: .1em; color: var(--ink-dim); text-transform: uppercase; }
.pause-vs { font-family: var(--font-display); font-size: 20px; color: var(--red); }
.modal-actions { display: flex; flex-direction: column; gap: 8px; margin-bottom: 18px; }
.modal-actions .btn { width: 100%; }
.pause-controls {
  display: flex; flex-direction: column; gap: 4px;
  padding-top: 13px; border-top: 1px solid var(--line);
  font-size: 10.5px; letter-spacing: .04em; color: var(--muted);
}
.pause-controls b { color: var(--gold); font-weight: 800; }

/* result */
.result-modal {
  position: relative;
  width: min(800px, 94vw);
  display: grid;
  grid-template-columns: minmax(0, 1fr) 250px;
  gap: 12px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 80% 20%, rgba(225,40,40,.22), transparent 52%),
    linear-gradient(180deg, #191019 0%, #09070b 100%);
  border: 1px solid rgba(255,212,71,.25);
  box-shadow: 0 40px 120px rgba(0,0,0,.8), inset 0 1px 0 rgba(255,255,255,.08);
  padding: clamp(22px, 4vw, 46px);
  clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 26px 100%, 0 calc(100% - 26px));
  animation: modalIn .4s cubic-bezier(.2,.9,.25,1.1) both;
}
.result-glow {
  position: absolute;
  inset: -20%;
  background: radial-gradient(circle at 78% 55%, rgba(225,40,40,.2), transparent 38%);
  pointer-events: none;
}
.result-copy { position: relative; z-index: 2; display: flex; flex-direction: column; justify-content: center; }
.result-copy h2 {
  margin: 4px 0 2px;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(38px, 7vw, 76px);
  line-height: .86;
  letter-spacing: .005em;
  color: var(--ink);
  text-shadow: 0 5px 0 rgba(0,0,0,.45), 0 0 40px rgba(225,40,40,.18);
  overflow-wrap: anywhere;
}
.result-title {
  margin: 6px 0 12px;
  font-weight: 800;
  font-size: 12px;
  letter-spacing: .2em;
  color: var(--red-bright);
  text-transform: uppercase;
}
.result-quote {
  margin: 0 0 16px;
  font-style: italic;
  font-size: 15px;
  line-height: 1.4;
  color: var(--ink-dim);
  max-width: 44ch;
}
.result-stats { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 18px; }
.result-stats .meta-chip { color: var(--ink-dim); }
.result-stats .meta-chip.hot { color: var(--gold); border-color: rgba(255,212,71,.4); }
.result-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.result-portrait {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  margin: -18px -16px -18px 0;
  pointer-events: none;
}
.result-portrait canvas {
  width: 100%;
  max-width: 280px;
  height: auto;
  filter: drop-shadow(0 18px 30px rgba(0,0,0,.65));
  animation: winnerIn .55s .12s cubic-bezier(.2,.8,.3,1.1) both;
}
@keyframes winnerIn { from { opacity: 0; transform: translateY(30px) scale(.94); } to { opacity: 1; transform: none; } }

/* help */
.help-modal { width: min(880px, 95vw); }
.help-modal h2 { margin-bottom: 20px; }
.modal-close {
  position: absolute;
  top: 14px; right: 14px;
  width: 34px; height: 34px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.04);
  color: var(--ink-dim);
  cursor: pointer;
  font-size: 14px;
  z-index: 3;
}
.modal-close:hover { color: var(--ink); border-color: rgba(255,212,71,.5); }
.help-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; margin-bottom: 20px; }
.help-col h4 {
  margin: 0 0 10px;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 18px;
  letter-spacing: .05em;
  color: var(--gold);
  border-bottom: 1px solid rgba(255,212,71,.2);
  padding-bottom: 6px;
}
