254: 
255:   shake(mag, time) {
256:     if (mag >= this.shakeMag || this.shakeTime <= 0) {
257:       this.shakeMag = mag;
258:       this.shakeTime = time;
259:     }
260:   }
261: 
262:   burst(x, y, color, count = 12, size = 4, shape = 'spark') {
263:     for (let i = 0; i < count; i++) {
264:       const a = Math.random() * Math.PI * 2;
265:       const sp = 60 + Math.random() * 340;
266:       this.particles.push({
267:         x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 80,
268:         life: 0.35 + Math.random() * 0.4, maxLife: 0.75,
269:         size: size * (0.6 + Math.random() * 0.8), color,
270:         grav: shape === 'dust' ? 500 : 900, additive: shape !== 'dust',
271:         shape,
272:       });
273:     }
274:   }
275: 
276:   addFloat(text, x, y, color, size = 20) {
277:     this.floats.push({ text, x, y, color, size, t: 0, dur: 0.9 });
278:   }
279: 
280:   frame(ts) {
281:     if (this.destroyed) return;
282:     if (!this.last) this.last = ts;
283:     let dt = (ts - this.last) / 1000;
284:     this.last = ts;
285:     dt = Math.min(0.034, Math.max(0.001, dt));
286:     if (!this.paused) this.update(dt);
287:     this.draw(ts / 1000);
288:     this.raf = requestAnimationFrame(this._frame);
289:   }
290: 
291:   update(dt) {
292:     this.time += dt;
293:     if (this.announcement) {
294:       this.announcement.t += dt;
295:       if (this.announcement.t > this.announcement.dur) this.announcement = null;
296:     }
297:     if (this.shakeTime > 0) this.shakeTime -= dt;
298:     if (this.hitStop > 0) {
299:       this.hitStop -= dt;
300:       return;
301:     }
302: 
303:     if (this.phase === 'intro') {
304:       this.introTime += dt;
305:       for (const f of this.fighters) f.animTime += dt;
306:       if (this.introTime > 1.05 && !this.fightAnnounced) {
307:         this.fightAnnounced = true;
308:         this.announce('FIGHT!', '', 'fight', 0.75);
309:         sound.play('bell');
310:         this.flash('#fff', 0.05);
311:       }
312:       if (this.introTime > 1.65) this.phase = 'fight';
313:       return;
314:     }
315: 
316:     if (this.phase === 'fight') {
317:       this.roundTime -= dt;
318:       if (this.mode === 'cpu') this.updateAI(dt);
319:       for (let i = 0; i < 2; i++) {
320:         const f = this.fighters[i];
321:         const o = this.fighters[1 - i];
322:         this.updateFighter(f, o, dt, true);
323:         this.separate(f, o);
324:       }
325:       updateEffects(this, dt);
326:       if (this.roundTime <= 0) {
327:         const r0 = this.fighters[0].hp / 100;
328:         const r1 = this.fighters[1].hp / 100;
329:         let winner = -1;
330:         if (r0 > r1 + 0.001) winner = 0;
331:         else if (r1 > r0 + 0.001) winner = 1;
332:         this.endRound(winner, 'time');
333:       }
334:       return;
335:     }
336: 
337:     if (this.phase === 'roundEnd') {
338:       this.roundEndTime += dt;
339:       for (let i = 0; i < 2; i++) {
340:         const f = this.fighters[i];
341:         const o = this.fighters[1 - i];
342:         this.updateFighter(f, o, dt, false);
343:       }
344:       updateEffects(this, dt);
345:       if (this.roundEndTime > 0.9 && this.roundWinner >= 0) {
346:         const w = this.fighters[this.roundWinner];
347:         if (!w.ko) { w.state = 'win'; w.win = true; }
348:       }
349:       if (this.roundEndTime > 2.55) this.resolveRound();
350:       return;
351:     }
352: 
353:     if (this.phase === 'matchEnd') {
354:       this.matchEndTime += dt;
355:       for (const f of this.fighters) f.animTime += dt;
356:       updateEffects(this, dt);
357:     }
358:   }
359: 
360:   resolveRound() {
361:     if (this.matchOver) {
362:       this.phase = 'matchEnd';
363:       const winner = this.roundWinner >= 0 ? this.roundWinner : (this.wins[0] >= this.wins[1] ? 0 : 1);
364:       if (this.roundWinner < 0) { /* draw edge case */ }
365:       this.fighters[winner].state = 'win';
366:       this.fighters[winner].win = true;
367:       sound.play(this.mode === 'cpu' && winner === 1 ? 'lose' : 'win');
368:       if (!this.matchSent) {
369:         this.matchSent = true;
370:         this.onMatchEnd({
371:           winnerSide: winner,
372:           winner: this.fighters[winner].char,
373:           loser: this.fighters[1 - winner].char,
374:           wins: [...this.wins],
375:           round: this.round,
376:           mode: this.mode,
377:         });
378:       }
379:       return;
380:     }
381:     this.round += 1;
382:     this.startRound(false);
383:   }
384: 
385:   endRound(winner, reason) {
386:     if (this.phase !== 'fight') return;
387:     this.phase = 'roundEnd';
388:     this.roundEndTime = 0;
389:     this.roundWinner = winner;
390:     if (winner >= 0) this.wins[winner] += 1;
391:     this.matchOver = this.wins[0] >= 2 || this.wins[1] >= 2;
392:     if (reason === 'time') {
393:       if (winner >= 0) {
394:         this.announce('TIME UP', `${this.fighters[winner].char.name} TAKES THE ROUND`, 'time', 1.9);
395:         sound.play('bell');
396:       } else {
397:         this.announce('DRAW', 'NOBODY WINS THIS ONE', 'draw', 1.9);
398:         sound.play('bell');
399:         this.round = Math.max(1, this.round - 1);
400:       }
401:     }
402:   }
403: 
404:   updateFighter(f, o, dt, allowInput) {
405:     f.animTime += dt;
406:     f.hitFlash = Math.max(0, f.hitFlash - dt * 5);
407:     f.displayHp += (f.hp - f.displayHp) * Math.min(1, dt * 5.5);
408:     if (Math.abs(f.displayHp - f.hp) < 0.15) f.displayHp = f.hp;
409:     f.cooldown = Math.max(0, f.cooldown - dt);
410:     f.invuln = Math.max(0, f.invuln - dt);
411:     f.comboTimer = Math.max(0, f.comboTimer - dt);
412:     if (f.comboTimer <= 0) f.combo = 0;
413:     for (const k of Object.keys(f.buffer)) f.buffer[k] = Math.max(0, f.buffer[k] - dt);
414: 
415:     if (f.ko) {
416:       this.physics(f, dt);
417:       f.vx *= 0.94;
418:       f.state = 'ko';
419:       return;
420:     }
421: 
422:     if (f.hitstun > 0) {
423:       f.hitstun -= dt;
424:       f.state = 'hit';
425:       this.physics(f, dt);
426:       f.vx *= 0.9;
427:       return;
428:     }
429: 
430:     if (f.attack) {
431:       f.attack.elapsed += dt;
432:       const at = f.attack;
433:       const activeStart = at.type === 'punch' ? 0.075 : 0.145;
434:       const activeEnd = at.type === 'punch' ? 0.19 : 0.3;
435:       if (!at.hit && at.elapsed >= activeStart && at.elapsed <= activeEnd) {
436:         this.checkAttack(f, o, at.type);
437:       }
438:       f.state = 'attack';
439:       this.physics(f, dt);
440:       f.vx *= f.grounded ? 0.82 : 0.99;
441:       if (at.elapsed >= at.dur) {
442:         f.attack = null;
443:         f.state = f.grounded ? 'idle' : 'jump';
444:         f.cooldown = 0.06;
445:       }
446:       if (allowInput) f.facing = o.x >= f.x ? 1 : -1;
447:       return;
448:     }
449: 
450:     if (f.special) {
451:       this.updateSpecial(f, o, dt);
452:       if (allowInput && !f.special) f.facing = o.x >= f.x ? 1 : -1;
453:       return;
454:     }
455: 
456:     if (f.state === 'win' && !allowInput) {
457:       this.physics(f, dt);
458:       return;
459:     }
460: 
461:     if (allowInput && this.phase === 'fight') {
462:       const canAct = f.hitstun <= 0;
463:       if (canAct && f.buffer.special > 0 && f.meter >= 50) {
464:         f.buffer.special = 0;
465:         this.startSpecial(f);
466:         return;
467:       }
468:       if (canAct && f.buffer.kick > 0) {
469:         f.buffer.kick = 0;
470:         this.startAttack(f, 'kick');
471:         return;
472:       }
473:       if (canAct && f.buffer.punch > 0) {
474:         f.buffer.punch = 0;
475:         this.startAttack(f, 'punch');
476:         return;
477:       }
478:       if (canAct && f.buffer.jump > 0 && f.grounded) {
479:         f.buffer.jump = 0;
480:         this.jump(f);
481:       }
482:     }
483: 
484:     if (allowInput) {
485:       const held = this.getHeld(f.side);
486:       const axis = (held.right ? 1 : 0) - (held.left ? 1 : 0);
487:       f.blocking = held.down && f.grounded;
488:       if (f.blocking) {
489:         f.vx *= 0.6;
490:         f.state = 'block';
491:       } else if (axis !== 0) {
492:         if (f.grounded) {
493:           f.vx = axis * f.speed;
494:           f.state = 'walk';
495:         } else {
496:           f.vx = clamp(f.vx + axis * 500 * dt, -f.speed * 1.15, f.speed * 1.15);
497:         }
498:       } else {
499:         f.vx *= f.grounded ? 0.72 : 1;
500:         if (f.grounded) f.state = 'idle';
501:       }
502:       f.facing = o.x >= f.x ? 1 : -1;
503:     } else {
504:       f.blocking = false;
505:       f.vx *= 0.85;
506:       if (f.grounded && f.state !== 'win') f.state = 'idle';
507:     }
508: 
509:     this.physics(f, dt);
510:   }
511: 
512:   physics(f, dt) {
513:     if (f.grounded && f.y === 0) f.vy = 0;
514:     f.x += f.vx * dt;
515:     f.y += f.vy * dt;
516:     if (!f.grounded || f.y < 0) {
517:       f.vy += GRAVITY * dt;
518:       f.grounded = false;
519:     }
520:     if (f.y >= 0) {
521:       f.y = 0;
522:       f.vy = 0;
523:       if (!f.grounded) {
524:         f.grounded = true;
525:         if (f.state === 'jump') f.state = 'idle';
526:       }
527:     }
528:     f.x = clamp(f.x, 60, this.w - 60);
529:   }
530: 
531:   updateSpecial(f, o, dt) {
532:     const sp = f.special;
533:     sp.elapsed += dt;
534:     const char = f.char;
535:     if (sp.type === 'dash') {
536:       if (!sp.dashStarted && sp.elapsed > 0.15) {
537:         sp.dashStarted = true;
538:         f.dash = { time: 0.34, hit: false };
539:         f.vx = f.facing * 670;
540:         this.shake(5, 0.15);
541:       }
542:       if (f.dash) {
543:         f.dash.time -= dt;
544:         f.vx = f.facing * (440 + 260 * Math.max(0, f.dash.time / 0.34));
545:         if (Math.random() < 0.7) {
546:           this.particles.push({
547:             x: f.x - f.facing * 10, y: f.y - Math.random() * 120 * char.scale,
548:             vx: -f.facing * 40, vy: -20 + Math.random() * 40,
549:             life: 0.25, maxLife: 0.25, size: 4 + Math.random() * 5,
550:             color: char.special.color, grav: 0, additive: true, shape: 'spark',
551:           });
552:         }
553:         if (!f.dash.hit) {
554:           const dist = Math.abs(o.x - f.x);
555:           if (!o.ko && dist < f.width + o.width + 34) {
556:             f.dash.hit = true;
557:             this.hitFighter(f.side, 1 - f.side, {
558:               damage: 16 * f.powerFactor, knockback: 480, vy: -140, hitstun: 0.6, type: 'special',
559:               contact: { x: (f.x + o.x) / 2, y: o.y - 100 * o.char.scale },
560:               color: char.special.color,
561:             });
562:           }
563:         }
564:         if (f.dash.time <= 0) f.dash = null;
565:       }
566:     } else if (sp.type === 'projectile') {
567:       if (!sp.fired && sp.elapsed > 0.24) {
568:         sp.fired = true;
569:         spawnProjectile(this, f.side);
570:       }
571:     } else if (sp.type === 'beam') {
572:       if (!sp.fired && sp.elapsed > 0.26) {
573:         sp.fired = true;
574:         spawnBeam(this, f.side);
575:       }
576:     } else if (sp.type === 'slam') {
577:       if (!sp.fired && sp.elapsed > 0.34) {
578:         sp.fired = true;
579:         spawnShockwave(this, f.side);
580:         this.physics(f, dt);
581:       }
582:     }
583:     this.physics(f, dt);
584:     if (sp.elapsed >= sp.dur) {
585:       f.special = null;
586:       f.dash = null;
587:       f.state = f.grounded ? 'idle' : 'jump';
588:       f.cooldown = 0.15;
589:     }
590:   }
591: 
592:   checkAttack(f, o, type) {
593:     if (o.ko) return;
594:     const s = f.char.scale;
595:     const fat = f.char.fat || 0;
596:     const reach = f.char.stats.reach;
597:     const range = type === 'punch' ? (54 + reach * 6 + fat * 8) * s : (74 + reach * 7 + fat * 6) * s;
598:     const dx = (o.x - f.x) * f.facing;
599:     if (dx < -12 || dx > range + o.width * 0.8) return;
600:     const hy = f.y - (type === 'punch' ? 102 : 76) * s;
601:     if (hy < o.y - o.height - 20 || hy > o.y + 10) return;
602:     f.attack.hit = true;
603:     const contact = {
604:       x: f.x + f.facing * Math.min(range * 0.9, dx + o.width * 0.4),
605:       y: type === 'punch' ? hy : f.y - 80 * s,
606:     };
607:     this.hitFighter(f.side, 1 - f.side, {
608:       damage: (type === 'punch' ? 5.6 : 8.6) * f.powerFactor,
609:       knockback: type === 'punch' ? 170 : 300,
610:       vy: type === 'kick' ? -130 : 0,
611:       hitstun: type === 'punch' ? 0.3 : 0.4,
612:       type,
613:       contact,
614:       color: type === 'punch' ? '#ffe6a8' : '#ffd45c',
615:     });
616:   }
617: 
618:   hitFighter(ai, di, spec) {
619:     const attacker = this.fighters[ai];
620:     const defender = this.fighters[di];
621:     if (defender.ko || this.phase !== 'fight') return;
622:     const blocked = defender.blocking && defender.hitstun <= 0;
623:     let dmg = spec.damage * (1 - (defender.char.stats.defense - 1) * 0.045);
624:     if (blocked) dmg *= 0.18;
625:     if (!blocked && spec.type !== 'special' && attacker.combo > 0) {
626:       dmg *= Math.max(0.55, 1 - attacker.combo * 0.07);
627:     }
628:     defender.hp = Math.max(0, defender.hp - dmg);
629:     defender.hitFlash = 1;
630: 
631:     if (blocked) {
632:       defender.vx = attacker.facing * (spec.knockback || 180) * 0.32;
633:       defender.hitstun = 0.14;
634:       attacker.meter = Math.min(100, attacker.meter + 4);
635:       defender.meter = Math.min(100, defender.meter + 5);
636:       this.hitStop = 0.03;
637:       this.shake(2, 0.1);
638:       sound.play('block');
639:       this.burst(spec.contact.x, spec.contact.y, '#d6e4ff', 8, 3);
640:       this.addFloat('BLOCKED', spec.contact.x, spec.contact.y - 26, '#d6e4ff');
641:     } else {
642:       defender.hitstun = spec.hitstun || 0.3;
643:       defender.invuln = 0.05;
644:       defender.blocking = false;
645:       defender.state = 'hit';
646:       defender.vx = attacker.facing * (spec.knockback || 220) / defender.weight;
647:       if (spec.vy) { defender.vy = spec.vy; defender.grounded = false; }
648:       attacker.combo += 1;
649:       attacker.comboTimer = 1.3;
650:       attacker.meter = Math.min(100, attacker.meter + 9);
651:       defender.meter = Math.min(100, defender.meter + 7);
652:       this.hitStop = spec.type === 'special' ? 0.09 : 0.05;
653:       this.shake(spec.type === 'special' ? 9 : 5, 0.18);
654:       sound.play(spec.type === 'special' ? 'heavy' : 'hit');
655:       this.burst(spec.contact.x, spec.contact.y, spec.color || '#ffd45c', spec.type === 'special' ? 26 : 14, spec.type === 'special' ? 6 : 4);
656:       if (spec.type === 'special') this.flash(spec.color || '#fff', 0.13);
657:       if (defender.hp <= 0) this.onKO(attacker, defender);
658:     }
659:   }
660: 
661:   onKO(attacker, defender) {
662:     defender.ko = true;
663:     defender.hp = 0;
664:     defender.state = 'ko';
665:     defender.hitstun = 0;
666:     defender.vy = -380;
667:     defender.vx = attacker.facing * 280;
668:     defender.grounded = false;
669:     this.hitStop = 0.16;
670:     this.shake(24, 0.55);
671:     this.flash('#ffffff', 0.36);
672:     sound.play('ko');
673:     this.burst(defender.x, defender.y - 120 * defender.char.scale, '#e12828', 40, 7);
674:     this.burst(defender.x, defender.y - 100 * defender.char.scale, '#ffd45c', 24, 5);
675:     this.announce('K.O.', `${defender.char.name} IS DOWN`, 'ko', 2.1);
676:     this.endRound(attacker.side, 'ko');
677:   }
678: 
679:   separate(a, b) {
680:     if (a.ko && b.ko) return;
681:     const min = a.width + b.width + 6;
682:     const dx = b.x - a.x;
683:     if (Math.abs(dx) < min) {
684:       const push = (min - Math.abs(dx)) / 2;
685:       const dir = Math.sign(dx) || 1;
686:       a.x = clamp(a.x - dir * push, 60, this.w - 60);
687:       b.x = clamp(b.x + dir * push, 60, this.w - 60);
688:     }
689:   }
690: 
691:   getHeld(side) {
692:     if (side === 1 && this.mode === 'cpu') return this.aiHeld;
693:     return this.held[side];
694:   }
695: 
696:   updateAI(dt) {
697:     const f = this.fighters[1];
698:     const o = this.fighters[0];
699:     if (f.ko) return;
700:     const cfg = DIFFICULTY[this.difficulty] || DIFFICULTY.normal;
701:     const ai = this.ai;
702:     ai.timer -= dt;
703:     ai.cool = Math.max(0, ai.cool - dt);
704:     ai.blockTimer = Math.max(0, ai.blockTimer - dt);
705: 
706:     if ((o.attack || o.special) && ai.blockTimer <= 0) {
707:       const dist = Math.abs(o.x - f.x);
708:       if (dist < 230 && Math.random() < cfg.block * dt * 10) {
709:         ai.blockTimer = 0.34 + Math.random() * 0.25;
710:       }
711:     }
712:     this.aiHeld.down = ai.blockTimer > 0;
713: 
714:     if (ai.timer <= 0) {
715:       ai.timer = cfg.think * (0.65 + Math.random() * 0.7);
716:       this.aiHeld.left = false;
717:       this.aiHeld.right = false;
718:       const dx = o.x - f.x;
719:       const dist = Math.abs(dx);
720:       const dir = Math.sign(dx) || 1;
721:       const specialRange = f.char.special.type === 'dash' || f.char.special.type === 'slam' ? 260 : 980;
722:       const atkRange = 70 + f.char.stats.reach * 22 + f.char.scale * 18;
723: 
724:       if (ai.cool <= 0 && f.meter >= 50 && dist < specialRange && Math.random() < cfg.special) {
725:         this.pressAction(1, 'special');
726:         ai.cool = 0.9;
727:       } else if (ai.cool <= 0 && dist < atkRange && Math.random() < cfg.aggr) {
728:         this.pressAction(1, dist > atkRange * 0.7 ? 'kick' : (Math.random() < 0.58 ? 'punch' : 'kick'));
729:         ai.cool = 0.26 + Math.random() * 0.45;
730:       } else if (dist > 150) {
731:         if (dir > 0) this.aiHeld.right = true;
732:         else this.aiHeld.left = true;
733:         if (Math.random() < cfg.jump && f.grounded && dist < 340) this.pressAction(1, 'jump');
734:       } else if (dist < 62 && Math.random() < 0.34) {
735:         if (dir > 0) this.aiHeld.left = true;
736:         else this.aiHeld.right = true;
737:       }
738:     }
739:     if (f.x < 100) this.aiHeld.left = false;
740:     if (f.x > this.w - 100) this.aiHeld.right = false;
741:     if (f.blocking) {
742:       if (ai.blockTimer > 0) this.aiHeld.down = true;
743:       else this.aiHeld.down = false;
744:     }
745:   }
746: 
747:   draw(ts) {
748:     const ctx = this.ctx;
749:     ctx.clearRect(0, 0, W, H);
750:     let ox = 0, oy = 0;
751:     if (this.shakeTime > 0) {
752:       const m = this.shakeMag * Math.max(0, this.shakeTime / 0.3);
753:       ox = (Math.random() - 0.5) * m;
754:       oy = (Math.random() - 0.5) * m;
755:     }
756:     ctx.save();
757:     ctx.translate(ox, oy);
758:     drawStage(ctx, this.stage.id, W, H, this.time);
759: 
760:     const order = this.fighters[0].attack || this.fighters[0].special ? [1, 0] : [0, 1];
761:     for (const i of order) {
762:       const f = this.fighters[i];
763:       if (!f.ko) drawFighterShadow(ctx, f.char, f.x, Math.max(f.y, -2), 1, 0.42);
764:     }
765:     for (const i of order) {
766:       const f = this.fighters[i];
767:       if (!f.ko) continue;
768:       drawFighterShadow(ctx, f.char, f.x, 0, 1, 0.2);
769:     }
770:     for (const i of order) {
771:       const f = this.fighters[i];
772:       this.drawFighter(ctx, f);
773:     }
774:     drawEffects(ctx, this, this.time);
775:     ctx.restore();
776: 
777:     drawFlash(ctx, this);
778:     drawVignette(ctx, W, H);
779:     drawHud(ctx, this);
