306: export function drawAnnouncement(ctx, game) {
307:   const a = game.announcement;
308:   if (!a) return;
309:   const p = a.t / a.dur;
310:   if (p >= 1) return;
311:   const pop = p < 0.16 ? 0.55 + (p / 0.16) * 0.55 : 1 + Math.sin(Math.min(1, (p - 0.16) / 0.3) * Math.PI) * 0.05;
312:   const fade = p > 0.82 ? 1 - (p - 0.82) / 0.18 : 1;
313:   const styles = {
314:     fight: { color: '#ff3b2e', size: 120, sub: '#ffd447' },
315:     ko: { color: '#ff1e14', size: 158, sub: '#f6efdd' },
316:     round: { color: '#ffd447', size: 92, sub: '#f6efdd' },
317:     time: { color: '#ffd447', size: 108, sub: '#f6efdd' },
318:     win: { color: '#b8ff6a', size: 92, sub: '#f6efdd' },
319:     draw: { color: '#c9c4b8', size: 106, sub: '#f6efdd' },
320:     default: { color: '#f6efdd', size: 92, sub: '#ffd447' },
321:   };
322:   const st = styles[a.style] || styles.default;
323: 
324:   // band behind big callouts
325:   if (a.style === 'fight' || a.style === 'ko' || a.style === 'time') {
326:     ctx.save();
327:     ctx.globalAlpha = fade * 0.6;
328:     const g = ctx.createLinearGradient(0, 250, 0, 390);
329:     g.addColorStop(0, 'rgba(8,4,6,0)');
330:     g.addColorStop(0.2, 'rgba(8,4,6,.78)');
331:     g.addColorStop(0.8, 'rgba(8,4,6,.78)');
332:     g.addColorStop(1, 'rgba(8,4,6,0)');
333:     ctx.fillStyle = g;
334:     ctx.fillRect(0, 250, game.w, 150);
335:     ctx.strokeStyle = a.style === 'ko' ? 'rgba(225,40,40,.55)' : 'rgba(255,212,71,.35)';
336:     ctx.lineWidth = 2;
337:     line(ctx, 0, 300, game.w, 300, ctx.strokeStyle, 2);
338:     line(ctx, 0, 390, game.w, 390, ctx.strokeStyle, 2);
339:     ctx.restore();
340:   }
341: 
342:   ctx.save();
343:   ctx.globalAlpha = fade;
344:   ctx.translate(game.w / 2, a.style === 'ko' ? 342 : 340);
345:   ctx.scale(pop, pop);
346:   ctx.rotate(-0.025);
347:   const grad = ctx.createLinearGradient(0, -st.size / 2, 0, st.size / 2);
348:   grad.addColorStop(0, '#fff7df');
349:   grad.addColorStop(0.42, st.color);
350:   grad.addColorStop(1, dark(st.color, 0.18));
351:   txt(ctx, a.text, 0, 0, st.size, { align: 'center', color: st.color, lw: 13, stroke: '#080507' });
352:   // colored inner highlight
353:   ctx.save();
354:   ctx.globalAlpha *= 0.85;
355:   ctx.font = font(st.size);
356:   ctx.textAlign = 'center';
357:   ctx.fillStyle = grad;
358:   ctx.fillText(a.text, 0, 0);
359:   ctx.restore();
360:   if (a.sub) {
361:     txt(ctx, a.sub, 0, st.size * 0.55 + 18, 24, { align: 'center', color: st.sub, lw: 5 });
362:   }
363:   ctx.restore();
364: }
